css:
/* ══════════════════════════════════════════════
   菜谱本 · 样式表
   极简黑白灰 + 点缀色；底色 / 卡片 / 主色 / 点缀
   四色可在「首页汉堡菜单 → 配色」里自由更改
   ══════════════════════════════════════════════ */

:root{
  /* ── 用户可改的 4 个配色（JS 会直接覆盖这 4 个） ── */
  --c-bg:#E7E7E4;
  --c-card:#FFFFFF;
  --c-ink:#141412;
  --c-accent:#E24B4A;

  /* ── 以下全部由上面 4 色自动推导，不单独设置 ── */
  --bg:var(--c-bg);
  --surface:var(--c-card);
  --ink:var(--c-ink);
  --ink-2:color-mix(in srgb, var(--c-ink) 62%, var(--c-bg));
  --ink-3:color-mix(in srgb, var(--c-ink) 40%, var(--c-bg));
  --line:color-mix(in srgb, var(--c-ink) 14%, var(--c-card));
  --line-soft:color-mix(in srgb, var(--c-ink) 8%, var(--c-card));

  /* 悬浮 / 按下时的浅填充 */
  --fill-hover:color-mix(in srgb, var(--c-ink) 6%, var(--c-card));
  --fill-soft:color-mix(in srgb, var(--c-ink) 4%, var(--c-card));

  --accent:var(--c-accent);
  --accent-deep:color-mix(in srgb, var(--c-accent) 84%, #000);
  --accent-soft:color-mix(in srgb, var(--c-accent) 10%, var(--c-card));

  /* 烘焙温时卡片与红心：统一收敛到主色 / 点缀色体系 */
  --bake:var(--c-ink);
  --bake-deep:color-mix(in srgb, var(--c-ink) 84%, #000);
  --bake-soft:var(--fill-soft);
  --bake-line:var(--line);

  --fav:var(--c-accent);
  --fav-soft:var(--accent-soft);

  /* 步骤进度标记：固定蓝，不随主题四色变，跟点缀色明确区分 */
  --step-done:#378ADD;
  --step-done-deep:#185FA5;
  --step-done-soft:#E6F1FB;

  /* 旋钮浅色圆盘：比底色略亮 */
  --dial:color-mix(in srgb, var(--c-card) 55%, var(--c-bg));

  /* 极简风格：卡片与按钮不使用投影，仅弹层保留一点层次 */
  --shadow-card:none;
  --shadow-fab:none;
  --shadow-sheet:0 -8px 32px -12px rgba(0,0,0,.16);

  --safe-t:env(safe-area-inset-top, 0px);
  --safe-b:env(safe-area-inset-bottom, 0px);

  --ease:cubic-bezier(.32,.72,0,1);
}

*,*::before,*::after{box-sizing:border-box;}

html,body{
  margin:0;padding:0;height:100%;
  overflow:hidden;
  background:var(--bg);
  -webkit-tap-highlight-color:transparent;
}

body{
  font-family:"OPPOSans","HarmonyOS Sans SC","MiSans","PingFang SC","Noto Sans SC",system-ui,-apple-system,"Segoe UI",sans-serif;
  color:var(--ink);
  font-size:16px;
  line-height:1.5;
  -webkit-font-smoothing:antialiased;
  text-rendering:optimizeLegibility;
  overscroll-behavior:none;
}

button{font-family:inherit;font-size:inherit;color:inherit;border:0;background:none;padding:0;cursor:pointer;}
input,textarea{font-family:inherit;font-size:15.5px;color:var(--ink);}
input::placeholder,textarea::placeholder{color:var(--ink-3);}
h1,h2,h3,p{margin:0;}
svg{display:block;}

/* ── 视图层 ───────────────────────────────── */
.view{
  position:fixed;inset:0;
  display:flex;flex-direction:column;
  background:var(--bg);
  will-change:transform;
  transition:transform .3s var(--ease);
}
.layer-0{z-index:1;}
/* layer-4 / layer-5（美食日记、记一篇）也要一并移出屏幕，
   漏了的话它们一开始就盖在所有页面上面 */
.layer-1,.layer-2,.layer-3,.layer-4,.layer-5{
  z-index:2;transform:translateX(100%);
  box-shadow:-12px 0 30px -18px rgba(0,0,0,.14);
}
.layer-2{z-index:3;}
.layer-3{z-index:4;}
.layer-4{z-index:5;}
.layer-5{z-index:6;}
.layer-1.is-open,.layer-2.is-open,.layer-3.is-open,
.layer-4.is-open,.layer-5.is-open{transform:translateX(0);}
.view.is-hidden{visibility:hidden;}

.scroll-body{
  flex:1;
  min-height:0;
  overflow-y:auto;
  overflow-x:hidden;
  -webkit-overflow-scrolling:touch;
  overscroll-behavior:contain;
  scrollbar-width:none;
}
.scroll-body::-webkit-scrollbar{display:none;}

/* ── 首页头部 ─────────────────────────────── */
.home-head{
  padding:calc(20px + var(--safe-t)) 16px 10px;
  background:var(--bg);
  position:relative;
  z-index:2;
}
/* 左侧给全局悬浮的汉堡菜单留出位置，首页与计时器页对齐一致 */
.home-head-row{
  display:flex;align-items:flex-start;justify-content:space-between;gap:12px;
  padding-left:54px;
  margin-bottom:16px;
}
.brand{
  font-size:27px;font-weight:750;letter-spacing:-.4px;
  color:var(--ink);line-height:1.15;
}
.brand-sub{
  margin-top:5px;
  font-size:13px;color:var(--ink-3);letter-spacing:.1px;
}
.icon-btn{
  width:42px;height:42px;flex:0 0 42px;
  display:grid;place-items:center;
  border-radius:13px;
  background:var(--surface);
  border:1px solid var(--line-soft);
  color:var(--ink-2);
  transition:transform .16s,background .16s;
}
.icon-btn:active{transform:scale(.92);background:var(--fill-hover);}
.icon-btn svg{width:22px;height:22px;}

/* 搜索框 */
.search{
  display:flex;align-items:center;gap:9px;
  height:46px;padding:0 12px;
  background:var(--surface);
  border:1px solid var(--line-soft);
  border-radius:14px;
  box-shadow:0 1px 2px transparent;
  transition:border-color .18s,box-shadow .18s;
}
.search:focus-within{
  border-color:var(--c-accent);
  box-shadow:0 0 0 3px color-mix(in srgb, var(--c-accent) 10%, transparent);
}
.search-ico{width:19px;height:19px;flex:0 0 19px;color:var(--ink-3);}
.search input{
  flex:1;min-width:0;
  border:0;outline:0;background:none;
  font-size:15.5px;line-height:1.4;
}
.search input::-webkit-search-cancel-button,
.search input::-webkit-search-decoration{-webkit-appearance:none;display:none;}
.search-clear{
  width:26px;height:26px;flex:0 0 26px;display:grid;place-items:center;
  border-radius:50%;background:var(--fill-hover);color:var(--ink-2);
}
.search-clear svg{width:13px;height:13px;}

/* 全局悬浮汉堡菜单：浮在所有页面之上，首页 / 计时器页共用同一个 */
.chrome-menu{
  position:fixed;
  left:16px;top:calc(20px + var(--safe-t));
  z-index:30;
  border-radius:50%;
  color:var(--ink);
  transition:opacity .2s,transform .26s var(--ease),background .16s;
}
.chrome-menu.is-hidden{
  opacity:0;transform:translateY(-14px) scale(.88);
  pointer-events:none;
}

/* 底部悬浮导航：层级高于所有页面，计时器盖上来时它仍在最前 */
.dock{
  position:fixed;
  left:50%;transform:translateX(-50%);
  bottom:calc(14px + var(--safe-b));
  z-index:30;
  display:flex;align-items:center;
  height:64px;
  padding:0 8px;
  max-width:calc(100vw - 20px);
  background:color-mix(in srgb, var(--c-card) 92%, transparent);
  backdrop-filter:blur(16px);
  -webkit-backdrop-filter:blur(16px);
  border:1px solid var(--line-soft);
  border-radius:999px;
  box-shadow:0 14px 36px -14px transparent, 0 2px 8px transparent;
  transition:opacity .22s,transform .3s var(--ease);
}
.dock.is-hidden{
  opacity:0;
  transform:translateX(-50%) translateY(130px);
  pointer-events:none;
}

/* ── 菜谱列表 ─────────────────────────────── */
.recipe-list{
  display:flex;flex-direction:column;gap:9px;
  padding:4px 16px 0;
}
.card{
  display:flex;align-items:center;gap:6px;
  padding:13px 6px 13px 15px;
  background:var(--surface);
  border:1px solid var(--line-soft);
  border-radius:16px;
  box-shadow:var(--shadow-card);
  transition:transform .15s var(--ease),box-shadow .15s;
  animation:cardIn .26s var(--ease) both;
  /* 长按卡片是「进入编辑模式」，不该弹出复制／选择文字的菜单 */
  user-select:none;
  -webkit-user-select:none;
  -webkit-touch-callout:none;
}
@keyframes cardIn{
  from{opacity:0;transform:translateY(6px);}
  to{opacity:1;transform:none;}
}
.card:active{transform:scale(.982);box-shadow:0 1px 2px transparent;}
.card-body{flex:1;min-width:0;cursor:pointer;}

.card-title{
  font-size:16.5px;font-weight:600;letter-spacing:-.1px;
  color:var(--ink);
  line-height:1.35;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.card-meta{
  display:flex;align-items:center;gap:7px;
  margin-top:6px;
  overflow:hidden;
  min-height:18px;
}
.badge{
  flex:0 0 auto;
  height:19px;padding:0 7px;
  display:inline-flex;align-items:center;
  border-radius:5px;
  font-size:11px;font-weight:650;letter-spacing:.2px;
}
.badge-stir{background:var(--accent-soft);color:var(--accent-deep);}
.badge-bake{background:var(--bake-soft);color:var(--bake-deep);}
.card-tags{
  font-size:12.5px;color:var(--ink-3);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
  min-width:0;
}
.card-sum{
  flex:0 0 auto;
  font-size:12px;font-weight:600;color:var(--bake-deep);
  font-variant-numeric:tabular-nums;
  padding:6px 2px 6px 6px;
  cursor:pointer;
}

.fav-btn{
  flex:0 0 44px;width:44px;height:44px;
  display:grid;place-items:center;
  border-radius:13px;
  color:var(--ink-3);
  transition:transform .18s var(--ease),color .18s;
}
.fav-btn svg{width:21px;height:21px;transition:transform .22s var(--ease);}
.fav-btn:active{transform:scale(.88);}
.fav-btn.is-on{color:var(--fav);}
.fav-btn.is-on svg{fill:var(--fav);stroke:var(--fav);}
.fav-btn.is-on svg{animation:pop .34s var(--ease);}
@keyframes pop{
  0%{transform:scale(.7);}
  55%{transform:scale(1.18);}
  100%{transform:scale(1);}
}

.list-tail{height:calc(170px + var(--safe-b));}

/* 空状态 */
.empty{
  padding:64px 40px;
  text-align:center;
}
.empty-ico{
  width:62px;height:62px;margin:0 auto 18px;
  display:grid;place-items:center;
  border-radius:20px;
  background:var(--accent-soft);
  color:var(--accent);
}
.empty-ico svg{width:28px;height:28px;}
.empty-title{font-size:15.5px;font-weight:600;color:var(--ink-2);}
.empty-desc{margin-top:7px;font-size:13px;color:var(--ink-3);line-height:1.6;}

/* 次要浮动按钮：粘贴导入 */
/* ── 顶栏（子页面） ───────────────────────── */
.bar{
  display:flex;align-items:center;justify-content:space-between;gap:6px;
  padding:calc(10px + var(--safe-t)) 8px 8px;
  background:color-mix(in srgb, var(--c-bg) 94%, transparent);
  backdrop-filter:blur(14px);
  -webkit-backdrop-filter:blur(14px);
  position:relative;z-index:2;
}
.bar-title{
  flex:1;text-align:center;
  font-size:15px;font-weight:600;color:var(--ink-2);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
  padding:0 2px;
}
.bar-btn{
  min-width:44px;height:40px;
  padding:0 11px;
  display:inline-flex;align-items:center;justify-content:center;
  border-radius:12px;
  font-size:15px;font-weight:550;color:var(--ink-2);
  transition:background .16s,transform .12s;
}
.bar-btn:active{background:var(--fill-hover);transform:scale(.95);}
.bar-btn svg{width:22px;height:22px;}
.bar-btn-strong{color:var(--accent-deep);font-weight:700;}

/* ── 详情页 ───────────────────────────────── */
.detail-wrap{padding:6px 20px 0;}

.detail-head{margin-bottom:20px;}
.detail-type{
  display:flex;align-items:center;gap:8px;
  margin-bottom:9px;
}
.detail-title-row{
  display:flex;align-items:center;gap:10px;
}
.detail-title{
  flex:1;min-width:0;
  font-size:27px;font-weight:750;line-height:1.25;
  letter-spacing:-.4px;color:var(--ink);
  word-break:break-word;
}
.detail-tags{
  display:flex;flex-wrap:wrap;gap:7px;
  margin-top:14px;
}
.tag-pill{
  height:27px;padding:0 11px;
  display:inline-flex;align-items:center;
  border-radius:8px;
  background:var(--fill-hover);
  color:var(--ink-2);
  font-size:12.5px;font-weight:550;
}
/* 红心：仅图标，位于菜谱名称前 */
.detail-fav{
  flex:0 0 38px;width:38px;height:38px;
  display:grid;place-items:center;
  border-radius:12px;
  color:var(--ink-3);
  transition:.18s;
}
.detail-fav svg{width:23px;height:23px;}
.detail-fav:active{transform:scale(.86);}
.detail-fav.is-on{color:var(--fav);}
.detail-fav.is-on svg{fill:var(--fav);stroke:var(--fav);animation:pop .34s var(--ease);}

.block{margin-bottom:28px;}
.block-head{
  display:flex;align-items:baseline;gap:8px;
  margin-bottom:12px;
}
.block-title{
  font-size:13px;font-weight:700;letter-spacing:1.2px;
  color:var(--ink-3);
  text-transform:uppercase;
}
.block-count{
  font-size:12px;color:var(--ink-3);font-weight:500;
  font-variant-numeric:tabular-nums;
}

/* 材料 */
.ing-card{
  background:var(--surface);
  border:1px solid var(--line-soft);
  border-radius:15px;
  padding:2px 15px;
  box-shadow:var(--shadow-card);
}
.ing-row{
  display:flex;align-items:baseline;justify-content:space-between;gap:14px;
  padding:12px 0;
  border-bottom:1px dashed var(--line);
}
.ing-row:last-child{border-bottom:0;}
.ing-name{font-size:15.5px;color:var(--ink);line-height:1.45;}
.ing-amt{
  flex:0 0 auto;
  background:none;border:0;
  font-size:14.5px;color:var(--ink-2);
  font-variant-numeric:tabular-nums;
  text-align:right;
  line-height:1.45;
}

/* 份量换算条 */
.scale-bar{
  display:flex;align-items:center;gap:8px;
  margin:0 0 16px;
  padding:0;
}
.scale-bar.is-scaled{color:var(--accent-deep);}
/* 「份量」与材料名称同一字号，避免看起来偏小 */
.scale-label{font-size:15.5px;font-weight:650;color:var(--ink);letter-spacing:.2px;}
/* 整组右对齐：新增的「还原」排在减号左侧，加减号不会左右跳动 */
.scale-ctrl{display:flex;align-items:center;gap:2px;margin-left:auto;}
.scale-ctrl .scale-reset{margin-right:4px;}
.scale-btn{
  width:32px;height:32px;
  display:grid;place-items:center;
  border-radius:10px;
  background:none;
  color:var(--ink);
  font-size:19px;font-weight:600;line-height:1;
  transition:transform .12s;
}
.scale-btn:active{transform:scale(.88);}
.scale-num{
  min-width:34px;text-align:center;
  font-size:16.5px;font-weight:750;
  font-variant-numeric:tabular-nums;
}
.scale-unit{font-size:13px;font-weight:600;color:var(--ink-2);}
.scale-hint{font-size:11px;color:var(--ink-3);margin-left:2px;}
.scale-reset{
  font-size:12px;font-weight:600;
  color:var(--accent-deep);
  padding:4px 8px;border-radius:8px;
  background:var(--c-card);
}
.scale-reset:active{background:var(--accent-soft);}

/* 编辑器：份量行 */
.yield-row{display:flex;gap:8px;align-items:center;}
.yield-row .input{flex:1;}
.yield-unit{flex:0 0 84px;height:46px;}

/* 单位换算弹层 */
.conv-main{
  font-size:20px;font-weight:750;
  padding:6px 2px 12px;
  font-variant-numeric:tabular-nums;
}
.conv-row{
  display:flex;align-items:center;justify-content:space-between;
  padding:11px 2px;
  border-bottom:1px solid var(--line-soft);
  font-size:14px;color:var(--ink-2);
}
.conv-row strong{
  color:var(--ink);
  font-size:15.5px;
  font-variant-numeric:tabular-nums;
}
.conv-empty{padding:14px 2px;font-size:13.5px;color:var(--ink-3);}
.conv-note{
  margin-top:10px;
  font-size:11.5px;color:var(--ink-3);line-height:1.6;
}

/* 温度与时间 */
.bake-card{
  display:flex;flex-direction:column;gap:8px;
}
.bake-row{
  display:flex;align-items:center;gap:12px;
  padding:13px 15px;
  background:var(--bake-soft);
  border:1px solid var(--bake-line);
  border-radius:14px;
}
.bake-stage{
  flex:0 0 auto;
  min-width:22px;
  font-size:12px;font-weight:700;
  color:var(--bake-deep);
  opacity:.7;
  font-variant-numeric:tabular-nums;
}
.bake-figures{
  flex:1;
  display:flex;align-items:baseline;gap:16px;
  flex-wrap:wrap;
}
.bake-temp{
  font-size:19px;font-weight:700;color:var(--bake-deep);
  font-variant-numeric:tabular-nums;
  letter-spacing:-.2px;
}
.bake-temp .u{font-size:13px;font-weight:600;opacity:.75;margin-left:1px;}
.bake-time{
  font-size:15.5px;font-weight:600;color:var(--ink-2);
  font-variant-numeric:tabular-nums;
}
.bake-time .u{font-size:12.5px;font-weight:600;opacity:.75;margin-left:1px;}
.bake-label{
  flex:0 0 auto;
  font-size:11.5px;font-weight:600;
  color:var(--bake-deep);opacity:.6;
  padding:2px 7px;
  border-radius:5px;
  background:var(--fill-soft);
  margin-left:auto;
}

/* 步骤 */
.step{
  display:flex;gap:12px;
  padding:0 0 16px;
}
.step:last-child{padding-bottom:0;}
.step-num{
  flex:0 0 24px;height:24px;margin-top:1px;
  display:grid;place-items:center;
  border-radius:8px;
  background:var(--accent-soft);
  color:var(--accent-deep);
  font-size:12px;font-weight:750;
  font-variant-numeric:tabular-nums;
  border:none;padding:0;margin-right:0;
  font-family:inherit;
  transition:transform .14s, background .14s, color .14s;
}
.step-num:active{transform:scale(.88);}
.step-num.is-done{
  background:var(--step-done);
  color:#FFFFFF;
}
.step-text{
  flex:1;min-width:0;
  font-size:15.5px;line-height:1.72;
  color:var(--ink-2);
  white-space:pre-wrap;
  word-break:break-word;
}

/* 烘焙「无需操作」提示 */
.bake-note{
  display:flex;align-items:center;gap:9px;
  padding:13px 15px;
  border-radius:13px;
  background:var(--fill-hover);
  border:1px dashed var(--line);
  color:var(--ink-3);
  font-size:13.5px;
  line-height:1.5;
}
.bake-note svg{width:17px;height:17px;flex:0 0 17px;opacity:.7;}
.bake-note.is-action{
  background:var(--bake-soft);
  border-color:var(--bake-line);
  color:var(--bake-deep);
  cursor:pointer;
  transition:transform .12s var(--ease),background .15s;
}
.bake-note.is-action:active{transform:scale(.985);background:var(--fill-hover);}
.bake-note.is-action svg{opacity:.85;}

.detail-foot{
  margin-top:8px;padding-top:20px;
  border-top:1px solid var(--line);
  display:flex;flex-direction:column;gap:6px;
  padding-bottom:calc(40px + var(--safe-b));
}
.foot-meta{
  font-size:12px;color:var(--ink-3);
  font-variant-numeric:tabular-nums;
}
.danger-text{
  align-self:flex-start;
  margin-top:10px;
  padding:8px 0;
  font-size:13.5px;font-weight:550;color:var(--c-accent);
  opacity:.85;
}

/* ── 编辑表单 ─────────────────────────────── */
.form-body{padding:6px 20px 0;}

.field{margin-bottom:22px;}
.field-label{
  display:flex;align-items:baseline;gap:8px;
  margin-bottom:9px;
  font-size:13px;font-weight:700;letter-spacing:.3px;
  color:var(--ink-2);
}
.field-hint{
  font-size:11.5px;font-weight:500;color:var(--ink-3);letter-spacing:0;
}
.input{
  width:100%;height:48px;
  padding:0 14px;
  background:var(--surface);
  border:1px solid var(--line-soft);
  border-radius:13px;
  outline:0;
  font-size:16px;font-weight:500;
  transition:border-color .18s,box-shadow .18s;
}
.input:focus{
  border-color:var(--c-accent);
  box-shadow:0 0 0 3px color-mix(in srgb, var(--c-accent) 10%, transparent);
}

/* 分段选择器 */
.segmented{
  display:flex;gap:6px;padding:5px;
  background:var(--fill-hover);
  border-radius:14px;
}
.seg-btn{
  flex:1;height:40px;
  display:inline-flex;align-items:center;justify-content:center;gap:7px;
  border-radius:10px;
  font-size:14.5px;font-weight:600;
  color:var(--ink-2);
  transition:background .2s var(--ease),color .2s,box-shadow .2s;
}
.seg-btn svg{width:17px;height:17px;opacity:.8;}
.seg-btn.is-on{
  background:var(--surface);
  color:var(--ink);
  box-shadow:0 1px 3px transparent;
}
.seg-btn.is-on[data-type="bake"]{color:var(--bake-deep);}
.seg-btn.is-on[data-type="stir"]{color:var(--accent-deep);}

/* 标签编辑器 */
.tag-editor{
  display:flex;flex-wrap:wrap;gap:7px;
  align-items:center;
  min-height:48px;padding:8px 10px;
  background:var(--surface);
  border:1px solid var(--line-soft);
  border-radius:13px;
  transition:border-color .18s,box-shadow .18s;
}
.tag-editor:focus-within{
  border-color:var(--c-accent);
  box-shadow:0 0 0 3px color-mix(in srgb, var(--c-accent) 10%, transparent);
}
.tag-list{display:contents;}
.tag-chip{
  display:inline-flex;align-items:center;gap:5px;
  height:28px;padding:0 6px 0 10px;
  border-radius:8px;
  background:var(--fill-hover);
  color:var(--ink-2);
  font-size:13px;font-weight:550;
}
.tag-chip button{
  width:18px;height:18px;
  display:grid;place-items:center;
  border-radius:50%;
  color:var(--ink-2);
  transition:background .15s;
}
.tag-chip button:active{background:rgba(0,0,0,.07);}
.tag-chip svg{width:9px;height:9px;}
.tag-input{
  flex:1;min-width:110px;
  height:30px;border:0;outline:0;background:none;
  font-size:14.5px;
}
.tag-suggest{
  display:flex;flex-wrap:wrap;gap:6px;
  margin-top:9px;
}
.sug-chip{
  height:27px;padding:0 10px;
  border-radius:7px;
  background:transparent;
  border:1px dashed var(--line);
  color:var(--ink-3);
  font-size:12.5px;
}
.sug-chip:active{background:var(--fill-hover);}

/* 区块 */
.section{margin-bottom:26px;}
.section-head{
  display:flex;align-items:center;justify-content:space-between;gap:10px;
  margin-bottom:11px;
}
.section-head h2{
  display:flex;align-items:center;gap:8px;
  font-size:13px;font-weight:700;letter-spacing:.3px;
  color:var(--ink-2);
}
.drag-hint{
  font-size:11px;color:var(--ink-3);
  white-space:nowrap;
}
.opt-tag{
  font-size:10.5px;font-weight:600;
  color:var(--ink-3);
  padding:2px 6px;
  border-radius:5px;
  background:var(--fill-hover);
  letter-spacing:0;
}
/* 通栏 + 添加按钮（位于输入行下方） */
.add-line{
  width:100%;height:44px;margin-top:3px;
  display:flex;align-items:center;justify-content:center;
  border:1.5px dashed var(--line);
  border-radius:13px;
  color:var(--ink-3);
  background:transparent;
  transition:background .16s,color .16s,border-color .16s,transform .12s;
}
.add-line:active{background:var(--fill-hover);border-color:var(--accent);color:var(--accent);transform:scale(.985);}
.add-line svg{width:19px;height:19px;}

/* 材料分组（主料 / 辅料） */
.group-head{
  display:flex;align-items:center;gap:8px;
  margin:2px 0 9px;
}
.group-head + .group-head,
#ing-main-list + .group-head{margin-top:14px;}
.group-title{
  font-size:12.5px;font-weight:700;
  color:var(--ink-2);
  letter-spacing:.5px;
}
.group-hint{
  font-size:11px;color:var(--ink-3);
}

/* 动态行 */
.row-ing{
  display:grid;
  grid-template-columns:18px 1fr 60px 54px 34px;
  gap:6px;align-items:center;
  margin-bottom:8px;
  animation:rowIn .2s var(--ease);
}
/* 拖拽把手 */
.drag-handle{
  width:18px;height:44px;
  display:grid;place-items:center;
  border-radius:8px;
  color:var(--ink-3);
  cursor:grab;
  touch-action:none;
  -webkit-tap-highlight-color:transparent;
  transition:color .15s,background .15s;
}
.drag-handle svg{width:15px;height:15px;pointer-events:none;}
.drag-handle:active{color:var(--ink-3);background:var(--fill-hover);}
.row-ing.is-dragging .drag-handle{color:var(--accent);}

/* 拖拽中：被拖行浮起跟随手指 */
.row-ing.is-dragging{
  background:var(--surface);
  border-radius:13px;
  box-shadow:0 14px 30px -10px rgba(0,0,0,.16), 0 0 0 1px color-mix(in srgb, var(--c-accent) 25%, transparent);
  transform:scale(1.015);
  animation:none;
}
body.is-dragging-ing{cursor:grabbing;user-select:none;-webkit-user-select:none;}
/* 占位块 */
.row-slot{
  border-radius:11px;
  background:var(--fill-hover);
  border:1px dashed color-mix(in srgb, var(--c-accent) 30%, var(--c-card));
  margin-bottom:8px;
}
/* 单位下拉 */
.unit-sel{
  height:44px;width:100%;
  padding:0 12px 0 6px;
  border:1px solid var(--line-soft);
  border-radius:12px;
  background-color:var(--fill-soft);
  color:var(--ink-2);
  font-family:inherit;font-size:12px;font-weight:600;
  appearance:none;-webkit-appearance:none;
  background-image:url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 10 6' fill='none' stroke='%23A2907F' stroke-width='1.6' stroke-linecap='round'%3E%3Cpath d='M1 1l4 4 4-4'/%3E%3C/svg%3E");
  background-repeat:no-repeat;
  background-position:right 5px center;
  background-size:8px;
  text-align:center;text-align-last:center;
  transition:border-color .16s;
}
.unit-sel:focus{outline:none;border-color:var(--c-accent);}
@keyframes rowIn{
  from{opacity:0;transform:translateY(-3px);}
  to{opacity:1;transform:none;}
}
.row-input{
  width:100%;height:44px;
  padding:0 12px;
  background:var(--surface);
  border:1px solid var(--line-soft);
  border-radius:11px;
  outline:0;
  font-size:14.5px;
  transition:border-color .16s;
}
.row-input:focus{border-color:var(--c-accent);background:var(--c-card);}
.row-del{
  width:34px;height:44px;
  display:grid;place-items:center;
  border-radius:11px;
  color:var(--ink-3);
  transition:background .15s,color .15s;
}
.row-del:active{background:var(--fav-soft);color:var(--fav);}
.row-del svg{width:16px;height:16px;}

.row-bake{
  display:grid;
  grid-template-columns:1fr 34px;
  grid-template-areas:"lab del" "line del";
  gap:7px 8px;
  margin-bottom:10px;
  padding:10px;
  background:var(--fill-soft);
  border:1px solid var(--line);
  border-radius:13px;
  animation:rowIn .2s var(--ease);
}
.row-bake .r-lab{grid-area:lab;}
.row-bake .bake-line{grid-area:line;}
.row-bake .row-del{grid-area:del;align-self:center;height:44px;}
.row-bake .row-input{background:var(--c-card);border-color:var(--line);}
.row-bake .row-input:focus{border-color:var(--c-accent);}
.row-bake .unit-sel{background-color:var(--c-card);border-color:var(--line);}
.row-bake .unit-sel:focus{border-color:var(--c-accent);}
/* 温时一行：温度+单位 / 时间+单位，两小行 */
.bake-line{
  display:grid;
  grid-template-columns:1fr 64px;
  gap:7px;
}

.row-empty{
  padding:20px 0;
  text-align:center;
  font-size:13px;color:var(--ink-3);
  border:1px dashed var(--line);
  border-radius:13px;
}

.row-step{
  display:flex;gap:9px;
  margin-bottom:9px;
  animation:rowIn .2s var(--ease);
}
.step-idx{
  flex:0 0 26px;height:26px;margin-top:9px;
  display:grid;place-items:center;
  border-radius:8px;
  background:var(--accent-soft);
  color:var(--accent-deep);
  font-size:12px;font-weight:750;
  font-variant-numeric:tabular-nums;
}
.row-step textarea{
  flex:1;min-width:0;
  min-height:56px;
  padding:10px 12px;
  background:var(--surface);
  border:1px solid var(--line-soft);
  border-radius:12px;
  outline:0;
  resize:none;
  line-height:1.6;
  font-size:14.5px;
  transition:border-color .16s;
  field-sizing:content;
}
.row-step textarea:focus{border-color:var(--c-accent);background:var(--c-card);}
.row-step .row-del{height:auto;align-self:stretch;}

.hint{
  margin-top:9px;
  font-size:12px;line-height:1.6;
  color:var(--ink-3);
}

.form-tail{height:calc(40px + var(--safe-b));}

/* ── 底部面板 ─────────────────────────────── */
.sheet{
  position:fixed;inset:0;z-index:40;
  display:flex;flex-direction:column;justify-content:flex-end;
}
.sheet[hidden]{display:none;}
.sheet-mask{
  position:absolute;inset:0;
  background:rgba(0,0,0,.3);
  backdrop-filter:blur(2px);
  animation:fadeIn .22s ease both;
}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
.sheet-panel{
  position:relative;
  background:var(--bg);
  border-radius:26px 26px 0 0;
  padding:10px 18px calc(16px + var(--safe-b));
  box-shadow:var(--shadow-sheet);
  animation:slideUp .3s var(--ease) both;
  max-height:88vh;
  overflow-y:auto;
}
@keyframes slideUp{from{transform:translateY(100%)}to{transform:translateY(0)}}
.sheet-grip{
  width:38px;height:4px;margin:0 auto 16px;
  border-radius:2px;background:var(--ink-3);
}
.sheet-title{
  font-size:17px;font-weight:700;margin-bottom:4px;
  color:var(--ink);
}
.sheet-stat{
  font-size:12.5px;color:var(--ink-3);
  margin-bottom:16px;
  font-variant-numeric:tabular-nums;
}
.sheet-item{
  width:100%;
  display:flex;flex-direction:column;gap:2px;
  padding:14px 15px;
  margin-bottom:8px;
  text-align:left;
  background:var(--surface);
  border:1px solid var(--line-soft);
  border-radius:14px;
  transition:transform .14s,background .14s;
}
.sheet-item:active{transform:scale(.985);background:var(--fill-hover);}
.sheet-item span{font-size:15px;font-weight:600;color:var(--ink);}
.sheet-item small{font-size:12px;color:var(--ink-3);font-weight:500;}
.sheet-item.is-danger span{color:var(--c-accent);}
.sheet-note{
  margin:10px 2px 16px;
  font-size:12px;line-height:1.65;
  color:var(--ink-3);
}
.sheet-cancel{
  width:100%;height:50px;
  border-radius:14px;
  background:var(--fill-hover);
  color:var(--ink-2);
  font-size:15px;font-weight:600;
}

/* ── 对话框 ───────────────────────────────── */
.dialog{
  position:fixed;inset:0;z-index:50;
  display:grid;place-items:center;
  padding:32px 24px;
}
.dialog[hidden]{display:none;}
.dialog-mask{
  position:absolute;inset:0;
  background:rgba(0,0,0,.34);
  backdrop-filter:blur(2px);
  animation:fadeIn .2s ease both;
}
.dialog-box{
  position:relative;
  width:100%;max-width:330px;
  padding:22px 22px 16px;
  background:var(--surface);
  border-radius:20px;
  box-shadow:0 24px 60px -20px rgba(0,0,0,.2);
  animation:dialogIn .24s var(--ease) both;
}
@keyframes dialogIn{
  from{opacity:0;transform:scale(.94) translateY(8px);}
  to{opacity:1;transform:none;}
}
.dialog-box h3{
  font-size:16.5px;font-weight:700;color:var(--ink);
  margin-bottom:8px;
}
.dialog-box p{
  font-size:14px;line-height:1.6;color:var(--ink-2);
  margin-bottom:20px;
  word-break:break-word;
}
.dialog-actions{
  display:flex;gap:8px;justify-content:flex-end;
}
.dialog-btn{
  height:42px;padding:0 18px;
  border-radius:12px;
  background:var(--fill-hover);
  color:var(--ink-2);
  font-size:14.5px;font-weight:600;
  transition:transform .12s,background .15s;
}
.dialog-btn:active{transform:scale(.95);}
.dialog-btn.is-primary{background:var(--ink);color:var(--c-card);}
.dialog-btn.is-primary.is-danger{background:var(--c-accent);}

/* ── Toast ────────────────────────────────── */
.toast{
  position:fixed;
  left:50%;bottom:calc(96px + var(--safe-b));
  transform:translate(-50%,10px);
  max-width:80vw;
  padding:10px 18px;
  border-radius:999px;
  background:color-mix(in srgb, var(--c-ink) 92%, transparent);
  backdrop-filter:blur(8px);
  color:var(--c-card);
  font-size:13.5px;font-weight:500;
  white-space:nowrap;
  opacity:0;
  pointer-events:none;
  transition:opacity .22s,transform .22s var(--ease);
  z-index:60;
}
.toast.is-on{opacity:1;transform:translate(-50%,0);}

/* ── 滚动细节 ─────────────────────────────── */
.home-head::after{
  content:'';
  position:absolute;left:0;right:0;bottom:-18px;height:18px;
  background:linear-gradient(var(--bg), color-mix(in srgb, var(--c-bg) 0%, transparent));
  opacity:0;
  transition:opacity .22s;
  pointer-events:none;
}
.home-head.is-scrolled::after{opacity:1;}

/* 搜索 / 筛选重排时不重播入场动画，避免闪烁 */
.recipe-list.no-anim .card{animation:none;}

/* ── 粘贴导入 ─────────────────────────────── */
.imp-intro{
  display:flex;flex-direction:column;gap:10px;
  padding:14px 15px;
  margin-bottom:14px;
  background:var(--accent-soft);
  border:1px solid color-mix(in srgb, var(--c-accent) 16%, var(--c-card));
  border-radius:14px;
}
.imp-intro p{
  font-size:13px;line-height:1.65;color:color-mix(in srgb, var(--c-accent) 62%, var(--c-ink));
}
.imp-prompt-btn{
  align-self:flex-start;
  display:inline-flex;align-items:center;gap:5px;
  height:32px;padding:0 11px;
  border-radius:9px;
  background:var(--c-card);
  color:var(--accent-deep);
  font-size:12.5px;font-weight:600;
  box-shadow:0 1px 2px transparent;
  white-space:nowrap;
  transition:transform .14s;
}
.imp-prompt-btn:active{transform:scale(.96);}

.imp-area{
  width:100%;
  min-height:220px;
  padding:14px;
  background:var(--surface);
  border:1px solid var(--line-soft);
  border-radius:14px;
  outline:0;
  resize:vertical;
  font-size:14.5px;
  line-height:1.75;
  font-family:inherit;
  transition:border-color .18s,box-shadow .18s;
}
.imp-area:focus{border-color:var(--c-accent);box-shadow:0 0 0 3px color-mix(in srgb, var(--c-accent) 10%, transparent);}

.imp-preview{margin-top:16px;}

.imp-card{
  background:var(--surface);
  border:1px solid var(--line-soft);
  border-radius:15px;
  padding:15px;
  box-shadow:var(--shadow-card);
}
.imp-card-head{
  display:flex;align-items:center;gap:9px;
  margin-bottom:12px;
  flex-wrap:wrap;
}
.imp-card-name{
  font-size:17px;font-weight:700;color:var(--ink);
  letter-spacing:-.2px;
}
.imp-row{
  display:flex;gap:10px;
  padding:8px 0;
  border-top:1px dashed var(--line);
  font-size:13.5px;
  line-height:1.65;
}
.imp-row:first-of-type{border-top:0;}
.imp-k{
  flex:0 0 54px;
  color:var(--ink-3);
  font-weight:650;
  font-size:12px;
  padding-top:1px;
}
.imp-v{
  flex:1;min-width:0;
  color:var(--ink-2);
  word-break:break-word;
}
.imp-err{
  padding:14px 15px;
  border-radius:13px;
  background:var(--fill-hover);
  border:1px dashed color-mix(in srgb, var(--c-accent) 24%, var(--c-card));
  color:var(--accent-deep);
  font-size:13px;
  line-height:1.65;
}
.imp-ok-note{
  margin-top:10px;
  font-size:12px;
  color:var(--ink-3);
  line-height:1.6;
}

/* ── 首页管理模式（排序 / 删除卡片） ──────── */
.head-edit{
  flex:0 0 auto;
  height:34px;padding:0 14px;
  border-radius:17px;
  background:var(--surface);
  border:1px solid var(--line-soft);
  font-size:13.5px;font-weight:600;color:var(--ink-2);
  transition:background .16s,transform .12s;
}
.head-edit:active{background:var(--fill-hover);transform:scale(.95);}
.card.is-manage{padding-left:4px;cursor:default;}
.card.is-manage .card-body{cursor:default;}
.card-mgr{
  flex:0 0 auto;
  display:flex;flex-direction:column;gap:2px;
  padding-right:2px;
}
.mgr-btn{
  width:34px;height:26px;
  display:grid;place-items:center;
  border-radius:9px;
  color:var(--ink-2);
}
.mgr-btn svg{width:17px;height:17px;}
.mgr-btn:active{background:var(--fill-hover);}
.mgr-btn:disabled{opacity:.28;pointer-events:none;}
.card-del{
  flex:0 0 44px;width:44px;height:44px;
  display:grid;place-items:center;
  border-radius:13px;
  color:var(--accent-deep);
  transition:transform .15s var(--ease);
}
.card-del svg{width:20px;height:20px;}
.card-del:active{transform:scale(.88);}

/* 温时摘要多段显示 */
.card-sum.is-multi{
  display:flex;flex-direction:column;gap:2px;
  align-items:flex-end;
  text-align:right;
  line-height:1.35;
}

/* ── 材料联想浮层 ─────────────────────────── */
.ing-suggest{
  position:fixed;
  z-index:80;
  background:var(--surface);
  border:1px solid var(--line-soft);
  border-radius:12px;
  box-shadow:0 10px 30px -10px transparent;
  padding:4px;
  display:flex;flex-direction:column;
}
.ing-suggest[hidden]{display:none;}   /* display:flex 会盖掉 hidden 属性，必须显式兜底 */
.ing-suggest button{
  text-align:left;
  padding:9px 12px;
  border-radius:9px;
  font-size:14.5px;color:var(--ink);
  display:flex;align-items:center;gap:8px;
}
.ing-suggest button::before{
  content:'';
  width:5px;height:5px;border-radius:50%;
  background:var(--accent);
  flex:0 0 5px;
}
.ing-suggest button:active{background:var(--accent-soft);}

/* ── 大屏微调 ─────────────────────────────── */
@media (min-width:600px){
  .home-head{padding-left:24px;padding-right:24px;}
  .recipe-list{padding-left:24px;padding-right:24px;}
  .detail-wrap,.form-body{padding-left:28px;padding-right:28px;}
  .home-head{padding-left:24px;padding-right:24px;}
  .timer-head{padding-left:24px;padding-right:24px;}
  .chrome-menu{left:24px;}
}

/* 窄屏：收紧旋钮与内边距 */
@media (max-width:400px){
  .timer-body{padding:0 16px;}
}
@media (max-width:350px){
  .dock{padding:0 6px;}
  .dock-tabs{gap:4px;}
  .dock-tab{width:44px;height:44px;}
  .dock-add{width:44px;height:44px;}
  .timer-body{padding:0 12px;}
  .timer-clock{font-size:38px;}
}

/* ══════════ 首页头部：品牌区 + 分类小按钮 ══════════ */
.brand-wrap{flex:1;min-width:0;}

.chip-bar{
  display:flex;align-items:center;gap:7px;
  margin-top:11px;
  overflow-x:auto;
  scrollbar-width:none;
  -webkit-overflow-scrolling:touch;
  padding-bottom:2px;
}
.chip-bar::-webkit-scrollbar{display:none;}
.chip{
  flex:0 0 auto;
  height:32px;padding:0 13px;
  display:inline-flex;align-items:center;gap:5px;
  border-radius:999px;
  background:var(--surface);
  border:1px solid var(--line-soft);
  font-size:13px;font-weight:600;color:var(--ink-2);
  transition:background .18s,color .18s,border-color .18s,transform .12s;
}
.chip:active{transform:scale(.95);}
.chip-n{
  font-size:11.5px;font-weight:650;color:var(--ink-3);
  font-variant-numeric:tabular-nums;
}
.chip.is-on{
  background:var(--ink);border-color:var(--ink);color:var(--c-card);
  box-shadow:0 5px 14px -7px color-mix(in srgb, var(--c-ink) 60%, transparent);
}
.chip.is-on .chip-n{color:color-mix(in srgb, var(--c-card) 72%, transparent);}
.chip.is-on.is-fav{background:var(--fav);border-color:var(--fav);}

/* ══════════ 底部标签栏：菜谱 / 新建 / 计时器 ══════════ */
.dock-tabs{display:flex;align-items:center;gap:6px;}
.dock-tab{
  position:relative;
  width:48px;height:48px;
  display:inline-flex;align-items:center;justify-content:center;
  border-radius:999px;
  color:var(--ink-2);
  transition:background .22s var(--ease),color .22s,box-shadow .22s,transform .12s;
}
/* 后台还在倒计时：计时器图标右上角点一个红点 */
.dock-tab.is-counting::after{
  content:'';
  position:absolute;top:6px;right:6px;
  width:7px;height:7px;border-radius:50%;
  background:var(--c-accent);
}
.dock-tab svg{width:21px;height:21px;}
.dock-tab:active{transform:scale(.94);}
.dock-tab.is-on{
  background:var(--ink);color:var(--c-card);
  box-shadow:0 6px 16px -6px color-mix(in srgb, var(--c-ink) 55%, transparent);
}

/* 新建菜谱：收进底部菜单中间 */
.dock-add{
  width:48px;height:48px;flex:0 0 auto;
  display:inline-flex;align-items:center;justify-content:center;
  border-radius:999px;
  overflow:hidden;
  background:var(--c-ink);
  color:var(--c-card);
  box-shadow:0 8px 18px -8px transparent;
  transition:width .24s var(--ease),margin .24s var(--ease),opacity .2s,transform .16s var(--ease);
}
.dock-add svg{width:23px;height:23px;}
.dock-add:active{transform:scale(.9);}
/* 计时器页不需要新建，收起来 */
.dock.no-add .dock-add,
body.is-manage .dock-add{
  width:0;margin-left:-6px;opacity:0;pointer-events:none;
}

/* ══════════ 计时器 ══════════ */
/* pan-y：纵向滚动交给浏览器，横向手势留给左滑返回 */
#view-timer{touch-action:pan-y;}
.timer-body{padding:0 22px;}
.timer-readout{text-align:center;padding:2px 0 8px;}
.timer-clock{
  font-size:44px;font-weight:750;letter-spacing:-1.2px;
  color:var(--ink);line-height:1.1;
  font-variant-numeric:tabular-nums;
}
.timer-clock.is-done{color:var(--accent);animation:timerFlash 1.1s ease-in-out infinite;}
@keyframes timerFlash{
  0%,100%{opacity:1;}
  50%{opacity:.32;}
}
/* 计时器页头部：与首页 .home-head 同一套留白与层级 */
.timer-head{
  padding:calc(20px + var(--safe-t)) 16px 10px;
  background:var(--bg);
  position:relative;
  z-index:2;
}

/* 大旋钮：无刻度的浅色圆盘，手指绕圈滑动调整，一圈 30 分钟 */
.knob-wrap{
  display:flex;justify-content:center;
  margin:10px 0 2px;
}
.knob{
  position:relative;
  width:min(66vw, 248px);height:min(66vw, 248px);
  border-radius:50%;
  background:var(--dial);
  touch-action:none;
  user-select:none;-webkit-user-select:none;-webkit-touch-callout:none;
  cursor:grab;
}
.knob:active{cursor:grabbing;}

/* 红点：位于白环内外边缘正中间的轨道上，随剩余时间向 0 转动 */
.knob-dot{
  position:absolute;left:50%;top:50%;
  width:13px;height:13px;border-radius:50%;
  background:var(--c-accent);
  pointer-events:none;
  transition:transform .12s linear;
}

/* 中心黑色圆盘：‹ 开始 › 与 重置 都是无边框无底色的文字按钮 */
.knob-center{
  position:absolute;left:50%;top:50%;
  transform:translate(-50%,-50%);
  width:56%;height:56%;
  border-radius:50%;
  background:var(--c-ink);
  display:flex;flex-direction:column;align-items:center;justify-content:center;
  gap:2px;
}
.knob-row{display:flex;align-items:center;justify-content:space-between;width:100%;padding:0 9%;}
.knob-chev{
  flex:0 0 auto;
  width:26%;aspect-ratio:1;
  display:grid;place-items:center;
  font-size:clamp(20px, 6.4vw, 27px);font-weight:400;line-height:1;
  color:var(--c-card);
  border-radius:50%;
  transition:opacity .15s,transform .12s;
}
.knob-chev:active{transform:scale(.86);}
.knob-chev:disabled{opacity:.3;}
.knob-start{
  font-size:clamp(14px, 4.4vw, 17px);font-weight:600;
  color:var(--c-card);
  padding:6px 2px;
  transition:opacity .15s,transform .12s;
}
.knob-start:active{transform:scale(.94);}
.knob-start:disabled{opacity:.38;}
.knob-alt{
  font-size:clamp(11px, 3.2vw, 12.5px);font-weight:400;
  color:color-mix(in srgb, var(--c-card) 62%, var(--c-ink));
  padding:3px 8px;
  transition:opacity .15s;
}
.knob-alt:disabled{opacity:.35;}
/* 响铃时：中心只留一个「完成」 */
.knob-center.is-ringing .knob-chev,
.knob-center.is-ringing .knob-start{display:none;}
.knob-center.is-ringing .knob-alt{
  font-size:clamp(15px, 4.6vw, 18px);font-weight:600;
  color:var(--c-card);
  padding:10px 18px;
}

/* 预设时间：一行 3 个的白色小卡片 */
.presets{
  display:flex;justify-content:center;gap:9px;
  margin-top:18px;
}
.presets:empty{display:none;}
.preset{
  flex:1 1 0;max-width:118px;
  display:flex;flex-direction:column;align-items:flex-start;justify-content:center;gap:2px;
  padding:9px 12px;
  border-radius:14px;
  background:var(--surface);
  border:1px solid var(--line-soft);
  transition:transform .12s,background .16s;
}
.preset:active{transform:scale(.94);background:var(--fill-hover);}
.preset-t{font-size:16px;font-weight:600;color:var(--ink);font-variant-numeric:tabular-nums;}
.preset-l{font-size:11px;color:var(--ink-3);}

/* 底部导航浮在页面之上，给内容留出足够的安全距离 */
.timer-tail{height:calc(112px + var(--safe-b));}

/* ══════════ 侧边栏 ══════════ */
.drawer{position:fixed;inset:0;z-index:60;}
.drawer-mask{
  position:absolute;inset:0;
  background:rgba(0,0,0,.32);
  animation:fadeIn .22s ease both;
}
@keyframes fadeIn{from{opacity:0;}to{opacity:1;}}
.drawer-panel{
  position:absolute;top:0;left:0;bottom:0;
  width:min(84vw,330px);
  background:var(--bg);
  box-shadow:10px 0 44px -14px rgba(0,0,0,.2);
  display:flex;flex-direction:column;
  animation:drawerIn .28s var(--ease) both;
}
@keyframes drawerIn{from{transform:translateX(-100%);}to{transform:translateX(0);}}
.drawer-inner{
  flex:1;min-height:0;overflow-y:auto;
  padding:calc(20px + var(--safe-t)) 18px calc(26px + var(--safe-b));
}
.drawer-title{font-size:20px;font-weight:750;letter-spacing:-.3px;}
.drawer-stat{font-size:12.5px;color:var(--ink-3);margin-top:6px;margin-bottom:20px;line-height:1.65;}
.drawer-sec{margin-bottom:22px;}
.drawer-sec-h{
  font-size:12px;font-weight:700;letter-spacing:.9px;color:var(--ink-3);
  margin-bottom:9px;
}
.drawer-sec-tip{
  float:right;
  font-size:11px;font-weight:500;letter-spacing:0;
  color:var(--ink-3);opacity:.8;
}
.drawer-item{
  width:100%;
  display:flex;flex-direction:column;align-items:flex-start;gap:2px;
  padding:12px 14px;margin-bottom:8px;
  background:var(--surface);
  border:1px solid var(--line-soft);
  border-radius:14px;
  text-align:left;
  transition:transform .12s,background .16s;
}
.drawer-item:active{transform:scale(.98);background:var(--fill-hover);}
.drawer-item span{font-size:15px;font-weight:600;color:var(--ink);}
.drawer-item small{font-size:12px;color:var(--ink-3);}
.drawer-item.is-danger span{color:var(--accent-deep);}
.drawer-note{
  font-size:12px;color:var(--ink-3);line-height:1.7;
  padding:12px 14px;border-radius:12px;background:color-mix(in srgb, var(--c-card) 60%, transparent);
}
.drawer-chips{display:flex;flex-wrap:wrap;gap:7px;}
.drawer-chip{
  height:36px;padding:0 15px;border-radius:999px;
  background:var(--surface);border:1px solid var(--line-soft);
  font-size:13.5px;font-weight:600;color:var(--ink-2);
  transition:background .16s,color .16s;
}
.drawer-chip:active{background:var(--fill-hover);}
.drawer-chip.is-on{background:var(--ink);border-color:var(--ink);color:var(--c-card);}
/* 开关型：亮色 = 启用，灰色 = 关闭 */
.drawer-chip.is-switch.is-on{
  background:var(--c-ink);
  border-color:transparent;color:var(--c-card);
  box-shadow:0 5px 14px -7px transparent;
}
/* 抽屉面板跟手滑动退出 */
.drawer-panel.is-swiping{animation:none;}
.drawer-add{display:flex;gap:8px;margin-top:10px;}
.drawer-add input{
  flex:1;min-width:0;height:44px;padding:0 13px;
  border:1px solid var(--line-soft);border-radius:12px;
  background:var(--surface);font-size:15px;outline:0;
}
.drawer-add input:focus{border-color:var(--c-accent);}
.drawer-add button{
  flex:0 0 auto;height:44px;padding:0 18px;border-radius:12px;
  background:var(--accent);color:var(--c-card);font-size:14.5px;font-weight:650;
}
.drawer-add button:active{background:var(--accent-deep);}
.drawer-preset-row{display:flex;align-items:center;gap:8px;margin-bottom:8px;}
.drawer-preset-row .pt{
  flex:1;min-width:0;padding:11px 13px;border-radius:12px;
  background:var(--surface);border:1px solid var(--line-soft);
  font-size:14.5px;font-weight:600;color:var(--ink);
  font-variant-numeric:tabular-nums;text-align:left;
}
.drawer-preset-row .rm{
  flex:0 0 34px;width:34px;height:34px;border-radius:10px;
  display:grid;place-items:center;color:var(--accent-deep);background:var(--fill-hover);
}
.drawer-preset-row .rm svg{width:16px;height:16px;}
.drawer-empty{font-size:12.5px;color:var(--ink-3);padding:2px 0 6px;}

/* ── 配色自定义 ── */
.swatches{display:flex;flex-direction:column;gap:8px;margin-bottom:10px;}
.swatch{
  position:relative;
  display:flex;align-items:center;gap:10px;
  background:var(--surface);border:1px solid var(--line-soft);border-radius:12px;
  padding:10px 13px;
}
.swatch-color{
  flex:0 0 26px;width:26px;height:26px;border-radius:50%;
  border:1px solid var(--line);
}
.swatch-label{font-size:14px;font-weight:600;}
.swatch-hex{
  margin-left:auto;font-size:12px;color:var(--ink-3);
  font-variant-numeric:tabular-nums;letter-spacing:.4px;
}
.swatch-input{
  position:absolute;inset:0;width:100%;height:100%;
  opacity:0;cursor:pointer;
}
.scheme-save{display:flex;gap:8px;margin-top:10px;}
.scheme-save input{
  flex:1;min-width:0;height:44px;padding:0 13px;
  border:1px solid var(--line-soft);border-radius:12px;
  background:var(--surface);font-size:14.5px;outline:0;
}
.scheme-save input:focus{border-color:var(--c-accent);}
.scheme-save-btn{
  flex:0 0 auto;height:44px;padding:0 15px;border-radius:12px;
  background:var(--ink);color:var(--c-card);font-size:13.5px;font-weight:600;
  transition:transform .12s;
}
.scheme-save-btn:active{transform:scale(.96);}
.scheme-list{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px;}
.scheme-chip{
  display:inline-flex;align-items:center;
  background:var(--surface);border:1px solid var(--line-soft);border-radius:999px;
  overflow:hidden;
}
.scheme-apply{
  display:inline-flex;align-items:center;gap:7px;
  padding:8px 3px 8px 12px;
  font-size:12.5px;font-weight:600;color:var(--ink);
}
.scheme-apply:active{background:var(--fill-hover);}
.scheme-dots{display:inline-flex;gap:2.5px;}
.scheme-dots i{width:9px;height:9px;border-radius:50%;border:1px solid var(--line);}
.scheme-del{
  padding:8px 11px 8px 5px;
  color:var(--ink-3);font-size:15px;line-height:1;
}
.scheme-del:active{color:var(--c-accent);}
.scheme-empty{font-size:12px;color:var(--ink-3);margin-top:10px;line-height:1.6;}

/* ── 在线更新 ── */
.ota-ver{font-size:13px;color:var(--ink-2);margin-bottom:10px;}
.ota-url{display:flex;gap:8px;margin-bottom:10px;}
.ota-url input{
  flex:1;min-width:0;height:44px;padding:0 13px;
  border:1px solid var(--line-soft);border-radius:12px;
  background:var(--surface);font-size:13px;outline:0;
}
.ota-url input:focus{border-color:var(--c-accent);}
.ota-save-url{
  flex:0 0 auto;height:44px;padding:0 15px;border-radius:12px;
  background:var(--ink);color:var(--c-card);font-size:13.5px;font-weight:600;
  transition:transform .12s;
}
.ota-save-url:active{transform:scale(.96);}

/* 版本列表 */
.ota-list{margin:4px 0 10px;display:flex;flex-direction:column;gap:8px;}
.ota-row{
  display:flex;align-items:center;gap:10px;
  background:var(--surface);border:1px solid var(--line-soft);border-radius:12px;
  padding:10px 12px;
}
.ota-info{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px;}
.ota-v{font-size:13.5px;font-weight:600;color:var(--ink);}
.ota-note{font-size:12px;color:var(--ink-2);line-height:1.5;}
.ota-date{font-size:11px;color:var(--ink-3);}
.ota-dl{
  flex:0 0 auto;height:34px;padding:0 14px;border-radius:999px;
  background:var(--ink);color:var(--c-card);font-size:12.5px;font-weight:600;
  transition:transform .12s;
}
.ota-dl:active{transform:scale(.94);}
.ota-dl:disabled{background:var(--fill-hover);color:var(--ink-3);}

/* ══════════ 首页编辑模式：拖动排序 ══════════ */
.card-drag{
  flex:0 0 40px;width:40px;height:44px;
  display:grid;place-items:center;
  border-radius:12px;color:var(--ink-3);
  cursor:grab;touch-action:none;
}
.card-drag svg{width:19px;height:19px;}
.card.is-dragging{
  animation:none;transition:none;
  transform:scale(1.025);
  box-shadow:0 20px 36px -14px rgba(0,0,0,.18);
  border-color:var(--ink-3);
}
.card-slot{
  border-radius:16px;
  border:1px dashed var(--line);
  background:color-mix(in srgb, var(--c-card) 55%, transparent);
}
/* 编辑模式：底部的新建按钮收起，避免误触新建 */

/* ══════════ 详情：可点时间跳转计时器 ══════════ */
.time-chip{
  display:inline;
  padding:1px 6px;margin:0 1px;
  border-radius:7px;
  background:var(--accent-soft);
  color:var(--accent-deep);
  font-weight:650;font-size:inherit;
  line-height:1.35;
}
.time-chip:active{background:color-mix(in srgb, var(--c-accent) 18%, var(--c-card));}
/* 已做到这一步：序号和它里面的时间按钮一起转成蓝色系 */
.time-chip.is-done{
  background:var(--step-done-soft);
  color:var(--step-done-deep);
}
.time-chip.is-done:active{background:color-mix(in srgb, var(--step-done) 18%, var(--c-card));}
.bake-time.is-link{
  border-bottom:1px dashed color-mix(in srgb, var(--c-ink) 50%, transparent);
  padding-bottom:1px;
}

/* 区块标题右侧的小动作按钮（跳转米家） */
.block-act{
  margin-left:auto;flex:none;
  height:28px;padding:0 11px;
  border-radius:9px;
  border:1px solid var(--line-soft);
  background:var(--surface);
  color:var(--ink-2);
  font-size:12px;font-weight:600;
  transition:transform .14s,background .14s;
}
.block-act:active{transform:scale(.95);background:var(--fill-hover);}

/* 从计时器下拉拉出来的那一次：改成从上往下移动出现（平时还是从右侧滑入） */
#view-detail.is-drop{transform:translateY(-100%);}
#view-detail.is-drop.is-open{transform:translateY(0);}

/* 配色面板是从抽屉里点出来的，得盖在抽屉（z-index 60）上面 */
#sheet-color{z-index:70;}

/* 详情页菜名行最右边的固定按钮 */
.detail-pin{
  flex:0 0 32px;width:32px;height:32px;
  margin-left:auto;
  display:grid;place-items:center;
  border-radius:50%;
  border:1px solid var(--line-soft);
  background:var(--surface);
  color:var(--ink-3);
  transition:transform .16s,background .16s,color .16s;
}
.detail-pin:active{transform:scale(.9);}
.detail-pin svg{width:18px;height:18px;}
.detail-pin.is-on{
  background:var(--c-ink);
  border-color:var(--c-ink);
  color:var(--c-card);
}

/* 计时器页顶部：下拉拉出的固定菜谱 */
.timer-pin-hint{
  position:absolute;left:0;right:0;top:0;z-index:3;
  display:flex;align-items:center;gap:9px;
  padding:14px 16px;
  background:var(--surface);
  border-bottom:1px solid var(--line-soft);
  transform:translateY(-100%);
  opacity:0;
  pointer-events:none;
}
.timer-pin-hint[hidden]{display:none;}
.tph-label{
  flex:none;
  font-size:11px;padding:2px 7px;border-radius:6px;
  background:var(--c-ink);color:var(--c-card);
}
.tph-name{
  flex:1;min-width:0;
  font-size:14px;font-weight:600;color:var(--ink);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.tph-tip{flex:none;font-size:11px;color:var(--ink-3);}

/* ══════════ 计时器：当前步骤提示 ══════════ */
.timer-step{
  margin-top:8px;
  font-size:13px;font-weight:600;
  color:var(--ink-3);
  letter-spacing:.3px;
}
.timer-step[hidden]{display:none;}

/* ══════════ 配色：自定义调色面板 ══════════
   不用系统那个取色器（它在 WebView 里又丑又总是从黑色开始），
   自己带出当前色值，靠 hex 输入和 RGB 滑块微调。 */
.color-tabs{display:flex;gap:6px;margin:2px 0 14px;}
.color-tab{
  flex:1;padding:10px 0;
  border-radius:11px;
  border:1px solid var(--line-soft);
  background:var(--surface);
  color:var(--ink-2);
  font-size:13px;font-weight:600;
  transition:transform .14s, background .14s, color .14s;
}
.color-tab:active{transform:scale(.97);}
.color-tab.is-on{
  background:var(--c-ink);
  color:var(--c-card);
  border-color:var(--c-ink);
}
.color-preview{
  height:96px;border-radius:16px;
  display:grid;place-items:center;
  margin-bottom:13px;
  border:1px solid var(--line-soft);
  transition:background .12s;
}
.color-preview-hex{
  font-size:17px;font-weight:700;
  font-variant-numeric:tabular-nums;
  letter-spacing:.4px;
}
.color-hex-row{display:flex;align-items:center;gap:10px;margin-bottom:15px;}
.color-hex-row label{font-size:13px;color:var(--ink-3);flex:none;font-weight:600;}
.color-hex{
  flex:1;min-width:0;height:44px;padding:0 13px;
  border-radius:12px;
  border:1px solid var(--line);
  background:var(--surface);
  color:var(--ink);
  font-size:15px;font-family:ui-monospace,monospace;
  letter-spacing:.5px;
}
.color-hex:focus{border-color:var(--c-accent);outline:none;}
.color-slider{display:flex;align-items:center;gap:10px;margin-bottom:11px;}
.color-slider i{
  font-style:normal;
  font-size:13px;color:var(--ink-3);
  width:14px;flex:none;font-weight:600;
}
.color-slider input[type=range]{
  flex:1;min-width:0;height:32px;
  accent-color:var(--c-ink);
}
.color-slider b{
  font-size:13px;color:var(--ink-2);
  width:34px;text-align:right;flex:none;
  font-variant-numeric:tabular-nums;font-weight:600;
}
.color-demo{
  margin-top:17px;padding:14px 16px;
  border-radius:14px;
  background:var(--c-card);
  border:1px solid var(--line-soft);
}
.color-demo-t{font-size:15px;font-weight:650;color:var(--ink);margin-bottom:3px;}
.color-demo-s{font-size:12.5px;color:var(--ink-3);}

/* ══════════ 美食日记 ══════════ */
.layer-4{z-index:5;}
.layer-5{z-index:6;}

/* 从右上角那颗按钮的位置整片展开：用 clip-path 而不是位移，首页不会跟着动 */
#view-diary{
  /* clip-path 负责展开的观感；visibility 兜底，
     万一系统 WebView 不吃 clip-path，也不会整页盖在首页上 */
  visibility:hidden;
  transform:none;
  clip-path:circle(0% at calc(100% - 36px) 50px);
  opacity:0;
  pointer-events:none;
  /* 收起时让 visibility 等动画走完再隐藏，否则看不到收起过程 */
  transition:clip-path .4s var(--ease), opacity .24s, visibility 0s linear .4s;
}
#view-diary.is-open{
  visibility:visible;
  clip-path:circle(142% at calc(100% - 36px) 50px);
  opacity:1;
  pointer-events:auto;
  transition:clip-path .4s var(--ease), opacity .24s, visibility 0s;
}
/* 左上角没有汉堡菜单，把留白还回来 */
#view-diary .home-head-row{padding-left:2px;}

.round-btn{
  width:40px;height:40px;flex:0 0 40px;
  display:grid;place-items:center;
  border-radius:50%;
  background:var(--surface);
  border:1px solid var(--line-soft);
  color:var(--ink);
  transition:transform .16s,background .16s;
}
.round-btn:active{transform:scale(.92);background:var(--fill-hover);}
.round-btn svg{width:20px;height:20px;}

.brand-wrap{display:flex;align-items:center;gap:6px;}
.brand-text{flex:1;min-width:0;}
.diary-back{
  width:32px;height:32px;flex:0 0 32px;
  display:grid;place-items:center;
  border-radius:50%;border:none;background:transparent;
  color:var(--ink);margin-left:-7px;
  transition:background .14s;
}
.diary-back:active{background:var(--fill-hover);}
.diary-back svg{width:20px;height:20px;}
.diary-back[hidden]{display:none;}

/* 近似正方形的卡片：菜谱一层、日记一层都用它 */
.diary-grid{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:11px;
}
.diary-card{
  padding:8px;
  aspect-ratio:1/1;
  display:flex;flex-direction:column;
  text-align:left;
  background:var(--surface);
  border:1px solid var(--line-soft);
  border-radius:14px;
  transition:transform .14s,background .14s;
}
.diary-card:active{transform:scale(.975);background:var(--fill-hover);}
.diary-thumb{
  flex:1;min-height:0;
  border-radius:9px;
  background:var(--fill-soft);
  overflow:hidden;
  display:grid;place-items:center;
  margin-bottom:7px;
}
.diary-thumb img{width:100%;height:100%;object-fit:cover;display:block;}
.diary-thumb-none{font-size:11px;color:var(--ink-3);}
.diary-name{
  font-size:12.5px;font-weight:650;color:var(--ink);line-height:1.35;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.diary-meta{font-size:11px;color:var(--ink-3);margin-top:2px;}
.diary-note{
  font-size:11px;color:var(--ink-2);line-height:1.4;margin-top:2px;
  overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;
}
.diary-rate{font-size:11px;font-weight:600;margin-top:2px;}
.diary-rate.good{color:var(--step-done);}
.diary-rate.ok{color:var(--ink-3);}
.diary-rate.bad{color:var(--c-accent);}

/* ══════════ 记一篇日记 ══════════ */
.dn-head{
  margin:0 2px 14px;
  font-size:13px;line-height:1.6;color:var(--ink-3);
}
.dn-text{resize:vertical;min-height:88px;line-height:1.6;}
.dn-photos{display:flex;gap:9px;flex-wrap:wrap;}
.dn-add{
  width:88px;height:88px;
  display:grid;place-items:center;gap:4px;
  border-radius:12px;
  border:1px dashed var(--line);
  background:var(--surface);
  color:var(--ink-3);
  font-size:11px;
  transition:transform .14s,background .14s;
}
.dn-add:active{transform:scale(.96);background:var(--fill-hover);}
.dn-add svg{width:24px;height:24px;}
.dn-shot{
  position:relative;
  width:88px;height:88px;border-radius:12px;overflow:hidden;
  border:1px solid var(--line-soft);
}
.dn-shot img{width:100%;height:100%;object-fit:cover;display:block;}
.dn-shot-del{
  position:absolute;right:3px;top:3px;
  width:22px;height:22px;border-radius:50%;
  display:grid;place-items:center;
  background:rgba(0,0,0,.55);color:#FFFFFF;
  font-size:13px;line-height:1;
}
.dn-rating{display:flex;gap:8px;}
.dn-rate{
  flex:1;height:44px;
  border-radius:12px;
  border:1px solid var(--line-soft);
  background:var(--surface);
  color:var(--ink-2);
  font-size:13.5px;font-weight:600;
  transition:transform .14s,background .14s,color .14s,border-color .14s;
}
.dn-rate:active{transform:scale(.97);}
.dn-rate.is-on[data-rate="good"]{background:var(--step-done);border-color:var(--step-done);color:#FFFFFF;}
.dn-rate.is-on[data-rate="ok"]{background:var(--c-ink);border-color:var(--c-ink);color:var(--c-card);}
.dn-rate.is-on[data-rate="bad"]{background:var(--c-accent);border-color:var(--c-accent);color:#FFFFFF;}
.dn-tip{
  margin:14px 2px 0;
  font-size:12px;line-height:1.65;color:var(--ink-3);
}

/* ══════════ 步骤全部完成后：完成 / 重置 ══════════ */
.step-finish{display:flex;gap:9px;margin-top:6px;}
.step-finish button{
  flex:1;height:46px;
  border-radius:13px;
  font-size:14px;font-weight:600;
  border:1px solid var(--line-soft);
  background:var(--surface);
  color:var(--ink);
  transition:transform .14s,background .14s;
}
.step-finish button:active{transform:scale(.98);}
.step-finish .sf-done{
  background:var(--c-ink);
  border-color:var(--c-ink);
  color:var(--c-card);
}

/* 减少动效偏好 */
@media (prefers-reduced-motion:reduce){
  *{animation-duration:.01ms !important;transition-duration:.01ms !important;}
}

