/* ══════════════════════════════════════════════
   存储层
   优先 IndexedDB；不可用时（如某些浏览器的 file:// 环境）
   自动降级为 localStorage。对外暴露统一的异步接口。
   ══════════════════════════════════════════════ */

const Store = (() => {
  const DB_NAME = 'recipe-book';
  const DB_VERSION = 1;
  const STORE = 'recipes';
  const LS_KEY = 'recipe-book:recipes';

  let db = null;
  let mode = 'idb'; // 'idb' | 'ls'

  /* ── IndexedDB 基础 ── */
  function openIDB() {
    return new Promise((resolve, reject) => {
      let req;
      try {
        req = indexedDB.open(DB_NAME, DB_VERSION);
      } catch (e) {
        reject(e);
        return;
      }
      const timer = setTimeout(() => reject(new Error('idb timeout')), 3000);

      req.onupgradeneeded = () => {
        const d = req.result;
        if (!d.objectStoreNames.contains(STORE)) {
          const os = d.createObjectStore(STORE, { keyPath: 'id' });
          os.createIndex('updatedAt', 'updatedAt');
        }
      };
      req.onsuccess = () => { clearTimeout(timer); resolve(req.result); };
      req.onerror = () => { clearTimeout(timer); reject(req.error); };
      req.onblocked = () => { clearTimeout(timer); reject(new Error('idb blocked')); };
    });
  }

  function tx(mode_, fn) {
    return new Promise((resolve, reject) => {
      const t = db.transaction(STORE, mode_);
      const os = t.objectStore(STORE);
      let out;
      try { out = fn(os); } catch (e) { reject(e); return; }
      t.oncomplete = () => resolve(out && out.__req ? out.__req.result : out);
      t.onerror = () => reject(t.error);
      t.onabort = () => reject(t.error);
    });
  }

  /* ── localStorage 降级 ── */
  const ls = {
    read() {
      try {
        const raw = localStorage.getItem(LS_KEY);
        return raw ? JSON.parse(raw) : [];
      } catch { return []; }
    },
    write(arr) {
      localStorage.setItem(LS_KEY, JSON.stringify(arr));
    }
  };

  /* ── 对外接口 ── */
  async function init() {
    if (!('indexedDB' in window) || !indexedDB) {
      mode = 'ls';
      return mode;
    }
    try {
      db = await openIDB();
      // 简单探测一次写入能力
      await new Promise((resolve, reject) => {
        const t = db.transaction(STORE, 'readwrite');
        t.objectStore(STORE).count();
        t.oncomplete = resolve;
        t.onerror = () => reject(t.error);
      });
      mode = 'idb';
    } catch {
      db = null;
      mode = 'ls';
    }
    return mode;
  }

  async function all() {
    if (mode === 'ls') return ls.read();
    const req = db.transaction(STORE, 'readonly').objectStore(STORE).getAll();
    return new Promise((resolve, reject) => {
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = () => reject(req.error);
    });
  }

  async function put(recipe) {
    if (mode === 'ls') {
      const arr = ls.read();
      const i = arr.findIndex(r => r.id === recipe.id);
      if (i >= 0) arr[i] = recipe; else arr.push(recipe);
      ls.write(arr);
      return recipe;
    }
    return tx('readwrite', os => os.put(recipe));
  }

  async function putMany(list) {
    if (mode === 'ls') {
      const arr = ls.read();
      for (const r of list) {
        const i = arr.findIndex(x => x.id === r.id);
        if (i >= 0) arr[i] = r; else arr.push(r);
      }
      ls.write(arr);
      return list.length;
    }
    return new Promise((resolve, reject) => {
      const t = db.transaction(STORE, 'readwrite');
      const os = t.objectStore(STORE);
      list.forEach(r => os.put(r));
      t.oncomplete = () => resolve(list.length);
      t.onerror = () => reject(t.error);
    });
  }

  async function remove(id) {
    if (mode === 'ls') {
      ls.write(ls.read().filter(r => r.id !== id));
      return;
    }
    return tx('readwrite', os => os.delete(id));
  }

  async function clear() {
    if (mode === 'ls') { ls.write([]); return; }
    return tx('readwrite', os => os.clear());
  }

  return { init, all, put, putMany, remove, clear, get mode() { return mode; } };
})();

/* ══════════════════════════════════════════════
   烘焙日记存储
   跟菜谱完全分开：日记里带照片（压缩后的 base64），
   塞进菜谱对象会让每次读写都拖着大字符串跑，所以单开一个库。
   完成次数（doneCount）存在菜谱上，跟着备份走；
   日记本体不进备份，免得备份文件被照片撑爆。
   ══════════════════════════════════════════════ */
const DiaryStore = (() => {
  const DB_NAME = 'recipe-book-diary';
  const DB_VERSION = 1;
  const STORE = 'diary';
  const LS_KEY = 'recipe-book:diary';

  let db = null;
  let mode = 'ls';

  function openIDB() {
    return new Promise((resolve, reject) => {
      let req;
      try { req = indexedDB.open(DB_NAME, DB_VERSION); }
      catch (e) { reject(e); return; }
      const timer = setTimeout(() => reject(new Error('idb timeout')), 4000);
      req.onupgradeneeded = () => {
        const d = req.result;
        if (!d.objectStoreNames.contains(STORE)) {
          const os = d.createObjectStore(STORE, { keyPath: 'id' });
          os.createIndex('recipeId', 'recipeId');
          os.createIndex('createdAt', 'createdAt');
        }
      };
      req.onsuccess = () => { clearTimeout(timer); resolve(req.result); };
      req.onerror = () => { clearTimeout(timer); reject(req.error); };
      req.onblocked = () => { clearTimeout(timer); reject(new Error('idb blocked')); };
    });
  }

  async function init() {
    if (!('indexedDB' in window) || !indexedDB) { mode = 'ls'; return mode; }
    try {
      db = await openIDB();
      mode = 'idb';
    } catch {
      db = null;
      mode = 'ls';
    }
    return mode;
  }

  const ls = {
    read() {
      try { return JSON.parse(localStorage.getItem(LS_KEY) || '[]'); }
      catch { return []; }
    },
    write(arr) {
      try { localStorage.setItem(LS_KEY, JSON.stringify(arr)); }
      catch { /* 照片太多会写不下，此时这次日记只留在内存里 */ }
    }
  };

  function all() {
    if (mode === 'ls') return Promise.resolve(ls.read());
    return new Promise(resolve => {
      try {
        const req = db.transaction(STORE, 'readonly').objectStore(STORE).getAll();
        req.onsuccess = () => resolve(req.result || []);
        req.onerror = () => resolve([]);
      } catch { resolve([]); }
    });
  }

  function put(entry) {
    if (mode === 'ls') {
      const arr = ls.read();
      const i = arr.findIndex(e => e.id === entry.id);
      if (i >= 0) arr[i] = entry; else arr.push(entry);
      ls.write(arr);
      return Promise.resolve(entry);
    }
    return new Promise(resolve => {
      try {
        const t = db.transaction(STORE, 'readwrite');
        t.objectStore(STORE).put(entry);
        t.oncomplete = () => resolve(entry);
        t.onerror = () => resolve(entry);
      } catch { resolve(entry); }
    });
  }

  function remove(id) {
    if (mode === 'ls') {
      ls.write(ls.read().filter(e => e.id !== id));
      return Promise.resolve();
    }
    return new Promise(resolve => {
      try {
        const t = db.transaction(STORE, 'readwrite');
        t.objectStore(STORE).delete(id);
        t.oncomplete = () => resolve();
        t.onerror = () => resolve();
      } catch { resolve(); }
    });
  }

  async function byRecipe(recipeId) {
    const list = await all();
    return list.filter(e => e.recipeId === recipeId)
      .sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
  }

  return { init, all, put, remove, byRecipe, get mode() { return mode; } };
})();

/* ══════════════════════════════════════════════
   在线更新包存储
   独立于菜谱数据：IndexedDB 优先，不可用降级 localStorage，
   再不行就只存内存（更新仅本次有效）。缓存菜谱永远不碰。
   ══════════════════════════════════════════════ */
const OtaStore = (() => {
  const DB_NAME = 'recipe-book-ota';
  const DB_VERSION = 1;
  const STORE = 'kv';
  const LS_PREFIX = 'recipe-book:ota:';

  let db = null;
  let mode = 'ls';
  const mem = new Map();

  function lsWorks() {
    try {
      const k = LS_PREFIX + '__probe';
      localStorage.setItem(k, '1');
      localStorage.removeItem(k);
      return true;
    } catch { return false; }
  }

  function openIDB() {
    return new Promise((resolve, reject) => {
      let req;
      try { req = indexedDB.open(DB_NAME, DB_VERSION); }
      catch (e) { reject(e); return; }
      const timer = setTimeout(() => reject(new Error('idb timeout')), 4000);
      req.onupgradeneeded = () => {
        const d = req.result;
        if (!d.objectStoreNames.contains(STORE)) d.createObjectStore(STORE);
      };
      req.onsuccess = () => { clearTimeout(timer); resolve(req.result); };
      req.onerror = () => { clearTimeout(timer); reject(req.error); };
      req.onblocked = () => { clearTimeout(timer); reject(new Error('idb blocked')); };
    });
  }

  async function init() {
    if (lsWorks()) { mode = 'ls'; return mode; }
    if (!('indexedDB' in window) || !indexedDB) { mode = 'mem'; return mode; }
    try {
      db = await openIDB();
      mode = 'idb';
    } catch {
      db = null;
      mode = 'mem';
    }
    return mode;
  }

  function read(k) {
    if (mode === 'ls') {
      try { return JSON.parse(localStorage.getItem(LS_PREFIX + k) || 'null'); }
      catch { return null; }
    }
    if (mode === 'mem') return mem.has(k) ? mem.get(k) : null;
    return new Promise(resolve => {
      try {
        const t = db.transaction(STORE, 'readonly');
        const req = t.objectStore(STORE).get(k);
        req.onsuccess = () => resolve(req.result || null);
        req.onerror = () => resolve(null);
      } catch { resolve(null); }
    });
  }

  function write(k, v) {
    if (mode === 'ls') {
      try { localStorage.setItem(LS_PREFIX + k, JSON.stringify(v)); }
      catch {}
      return Promise.resolve();
    }
    if (mode === 'mem') { mem.set(k, v); return Promise.resolve(); }
    return new Promise(resolve => {
      try {
        const t = db.transaction(STORE, 'readwrite');
        t.objectStore(STORE).put(v, k);
        t.oncomplete = () => resolve();
        t.onerror = () => resolve();
      } catch { resolve(); }
    });
  }

  function remove(k) {
    if (mode === 'ls') {
      try { localStorage.removeItem(LS_PREFIX + k); } catch {}
      return Promise.resolve();
    }
    if (mode === 'mem') { mem.delete(k); return Promise.resolve(); }
    return new Promise(resolve => {
      try {
        const t = db.transaction(STORE, 'readwrite');
        t.objectStore(STORE).delete(k);
        t.oncomplete = () => resolve();
        t.onerror = () => resolve();
      } catch { resolve(); }
    });
  }

  return { init, read, write, remove, get mode() { return mode; } };
})();

