/* ══════════════════════════════════════════════
   菜谱本 · 应用逻辑
   ──────────────────────────────────────────────
   分类是可扩展的：新增类别只需在 CATEGORIES 里追加一项，
   首页筛选、类型选择器、徽章配色会自动跟随。
   hasBake 控制该类是否需要「温度与时间」区块。
   ══════════════════════════════════════════════ */

const CATEGORIES = [
  {
    id: 'stir',
    name: '家常菜',
    emoji: '🍳',
    badge: 'badge-stir',
    hasBake: false,
    icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M4 10.5h16l-1.5 6.6a3 3 0 0 1-2.9 2.4H8.4a3 3 0 0 1-2.9-2.4L4 10.5z"/><path d="M2 10.5h20"/><path d="M9 7c0-1 .9-1.4.9-2.4"/><path d="M13 7c0-1 .9-1.4.9-2.4"/></svg>'
  },
  {
    id: 'bake',
    name: '烘焙',
    emoji: '🧁',
    badge: 'badge-bake',
    hasBake: true,
    icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="3.5" width="16" height="17" rx="3"/><path d="M4 9h16"/><circle cx="8" cy="6.3" r=".9"/><circle cx="16" cy="6.3" r=".9"/><path d="M9 14.5h6"/><path d="M9 17.5h6"/></svg>'
  }
];

const catOf = id => CATEGORIES.find(c => c.id === id) || CATEGORIES[0];

/* ── 单位选择 ── */
const ING_UNITS = ['g', 'kg', 'ml', '个', '匙'];
const TEMP_UNITS = ['°C', '°F'];
const TIME_UNITS = ['分钟', '小时', '秒'];

/* "200 g" → {num:'200',unit:'g'}；"200g" 同样可拆；"适量" 整体留在 num */
function splitAmount(v) {
  const s = String(v ?? '').trim();
  if (ING_UNITS.includes(s) || TEMP_UNITS.includes(s) || TIME_UNITS.includes(s)) return { num: '', unit: s };
  const m = s.match(/^([\d.\/]+\s*(?:[-~～至]\s*[\d.\/]+)?)\s*(\S+)$/);
  if (m) return { num: m[1].replace(/\s+/g, ''), unit: m[2].replace(/℃/g, '°C') };
  return { num: s, unit: '' };
}

/* 合成存储值："200" + "g" → "200 g"；数字为空则忽略单位 */
function joinAmount(num, unit) {
  const n = String(num || '').trim();
  const u = String(unit || '').trim();
  return n ? [n, u].filter(Boolean).join(' ') : '';
}

/* 材料单位下拉：首项为空（如填「适量」「半个」时不用选） */
function ingUnitSel(unit) {
  const cur = String(unit || '');
  const all = cur && !ING_UNITS.includes(cur) ? [cur, ...ING_UNITS] : ING_UNITS;
  const opts = [`<option value=""${cur ? '' : ' selected'}>单位</option>`]
    .concat(all.map(u => `<option value="${esc(u)}"${u === cur ? ' selected' : ''}>${esc(u)}</option>`));
  return `<select class="unit-sel" data-ing="unit" aria-label="单位">${opts.join('')}</select>`;
}

/* 温时单位下拉：默认 °C / 分钟 */
function bakeUnitSel(attr, units, unit) {
  const cur = units.includes(unit) ? unit : units[0];
  const opts = units.map(u => `<option value="${esc(u)}"${u === cur ? ' selected' : ''}>${esc(u)}</option>`).join('');
  return `<select class="unit-sel" data-bake="${attr}" aria-label="单位">${opts}</select>`;
}

/* ── 份量换算 ── */
const YIELD_UNITS = ['个', '块', '只', '份', '人份', '杯', '张', '条', '颗', '盒'];
const CONV_UNITS = ['g', 'kg', 'ml', 'L', '杯', '汤匙', '茶匙', '勺'];

function evalNum(s) {
  const t = String(s ?? '').trim();
  if (/^\d*\.?\d+$/.test(t)) return parseFloat(t);
  const f = t.match(/^(\d+)\/(\d+)$/);
  if (f && +f[2]) return +f[1] / +f[2];
  return null;
}

/* 换算结果取整：大数取 5、中数取 1、小数取 0.5/0.25 */
function niceNum(x) {
  let n;
  if (x >= 100) n = Math.round(x / 5) * 5;
  else if (x >= 10) n = Math.round(x);
  else if (x >= 1) n = Math.round(x * 2) / 2;
  else n = Math.round(x * 4) / 4;
  return String(parseFloat(n.toFixed(2)));
}

/* 按倍数缩放用量；「适量」「半个」等非数字保持原样 */
function scaleAmount(amount, factor) {
  if (!factor || factor === 1) return String(amount ?? '');
  const s = String(amount ?? '').trim();
  const range = s.match(/^([\d.\/]+)\s*[-~～至]\s*([\d.\/]+)\s*(.*)$/);
  if (range) {
    const a = evalNum(range[1]);
    const b = evalNum(range[2]);
    if (a != null && b != null) {
      return `${niceNum(a * factor)} - ${niceNum(b * factor)}${range[3] ? ' ' + range[3] : ''}`;
    }
  }
  const p = splitAmount(s);
  const n = evalNum(p.num);
  if (n == null) return s;
  return [niceNum(n * factor), p.unit].filter(Boolean).join(' ');
}

/* ── 单位换算（g ↔ ml 等，按食材密度估算） ── */
const DENSITIES = [
  ['面粉|低筋粉|高筋粉|全麦粉|小麦粉|面包粉|蛋糕粉', 0.53, '面粉'],
  ['淀粉|生粉|玉米淀粉', 0.6, '淀粉'],
  ['糖粉|糖霜', 0.55, '糖粉'],
  ['砂糖|白糖|绵糖|细砂|红糖|冰糖|黑糖', 0.85, '糖'],
  ['蜂蜜|糖浆|麦芽糖', 1.4, '蜂蜜'],
  ['可可粉', 0.5, '可可粉'],
  ['杏仁粉', 0.45, '杏仁粉'],
  ['椰蓉|椰子粉', 0.35, '椰蓉'],
  ['牛奶|纯奶|鲜奶|淡奶', 1.03, '牛奶'],
  ['奶油|酸奶|乳酪|芝士', 1.0, '乳制品'],
  ['蛋液|全蛋|蛋白|蛋黄', 1.03, '蛋液'],
  ['食用油|玉米油|橄榄油|花生油|葵花籽油|椰子油|麻油|葱油|辣椒油|色拉油|油', 0.92, '食用油'],
  ['清水|凉水|温水|开水|热水|水', 1.0, '水']
];

function guessDensity(name) {
  const s = String(name ?? '');
  for (const [re, d, label] of DENSITIES) {
    if (new RegExp(re).test(s)) return { d, label };
  }
  return { d: 1.0, label: '' };
}

/* 换算为毫升；无法换算（个、片、适量等）返回 null */
function amountToML(num, unit, density) {
  const n = evalNum(num);
  if (n == null) return null;
  switch (unit) {
    case 'ml': return n;
    case 'L': return n * 1000;
    case 'g': return n / density;
    case 'kg': return n * 1000 / density;
    case '杯': return n * 240;
    case '汤匙': case '勺': return n * 15;
    case '茶匙': return n * 5;
    default: return null;
  }
}

