/* 自定义确认框，返回 Promise<boolean> */
let dialogResolve = null;

function confirmDialog({ title, text, ok = '确定', danger = false }) {
  const dlg = $('dialog');
  $('dialog-title').textContent = title;
  $('dialog-text').textContent = text;
  const okBtn = $('dialog-ok');
  okBtn.textContent = ok;
  okBtn.classList.toggle('is-danger', danger);
  dlg.hidden = false;
  pushLayer();

  return new Promise(resolve => {
    dialogResolve = resolve;
    okBtn.onclick = () => finishDialog(true, true);
    dlg.querySelectorAll('[data-dialog-cancel]').forEach(n => { n.onclick = () => finishDialog(false, true); });
  });
}

function finishDialog(val, fromUI) {
  const dlg = $('dialog');
  if (dlg.hidden) return false;
  dlg.hidden = true;
  const r = dialogResolve;
  dialogResolve = null;
  if (fromUI) backHistory();
  if (r) r(val);
  return true;
}

/* ══════════ 文本菜谱解析 ══════════
   把 AI 整理好的纯文本（或菜谱 JSON）解析成菜谱对象。
   设计目标是容错：容忍 Markdown 标题、加粗、列表符号、表格竖线、
   中英文冒号混用、序号写法差异等 AI 常见输出。
*/

const AI_PROMPT = `你是菜谱整理助手。请把图片里的菜谱整理成下面的纯文本格式，直接输出结果，不要解释，不要用 Markdown 标题或加粗符号。

