2. 翻拌均匀后入模，震出气泡

【截图只拍到一部分时这样输出】
（下面这张只拍到了材料，没有温度和时间）
名称：葡式蛋挞
类型：烘焙
份量：12 个

材料：
蛋挞皮 12 个
牛奶 200 g
淡奶油 180 g
细砂糖 50 g
蛋黄 4 个

【规则】
1. 类型只能是「家常菜」或「烘焙」。就算截图里没写，这一行也必须输出：需要烤箱烘烤的（蛋糕、面包、饼干、蛋挞、派、曲奇、吐司、泡芙等）写「烘焙」，灶上炒、煮、炖、蒸、焖、烧、凉拌的写「家常菜」
2. 家常菜材料分「主料」和「辅料」两栏；烘焙只写一个「材料」
3. 材料每行一项，写成「名称 用量」，名称和用量之间用空格隔开；用量只写数字，单位用 g、ml、个、勺 这类常见单位
4. 「温度时间」每行一段，写成「温度 时间 阶段」，阶段可省略；温度写数字（摄氏），时间写数字（分钟）
5. 操作每行一步，行首加序号；步骤里提到的时间一律写成「25min」「1.5h」这种格式（只有 h 和 min 两种写法会被识别成可点的计时按钮，不要写「25 分钟」）
6. 标签最多 3 个，用空格分隔
7. 「份量」写成「数量 单位」，如「12 个」「2 人份」，图片里没有就省略
8. 截图没拍到的部分，把它那一整段连同标题一起省略，不要编造。绝对不要写「未知」「待定」「见包装」「参考步骤」这类占位内容
9. 「名称」必须输出。截图没截到菜名时，写「未命名菜谱」，不要自己起一个`;

const FIELD_ALIASES = {
  name: ['名称', '菜名', '菜谱名称', '菜品', '名字', 'name', 'title'],
  type: ['类型', '分类', '类别', 'type', 'category'],
  yield: ['份量', '成品', '产量', '几人份', '份数', 'yield', 'servings'],
  tags: ['标签', 'tag', 'tags', 'keywords'],
  main: ['主料', '主要材料', '主材料', '主食材'],
  aux: ['辅料', '配料', '调料', '辅料调料'],
  ing: ['材料', '原料', '食材', '用料', '配料表', 'ingredients'],
  bake: ['温度时间', '温度与时间', '烘烤参数', '烘烤', '烤制', '温时', 'bake', 'temperature'],
  steps: ['操作', '步骤', '做法', '制作', '过程', 'steps']
};

function matchField(key) {
  const k = String(key).toLowerCase().replace(/[\s（）()【】\[\]]/g, '');
  for (const field of Object.keys(FIELD_ALIASES)) {
    if (FIELD_ALIASES[field].some(a => k === a || k.includes(a))) return field;
  }
  return null;
}

function normalizeLine(line) {
  return String(line)
    .replace(/^\s*```.*$/, '')
    .replace(/\*\*|__|`/g, '')
    .replace(/^\s*#{1,6}\s*/, '')
    .replace(/^\s*[-*·•+]\s+/, '')
    .replace(/^\s*\|?[\s]*\|/, '')
    .replace(/\|\s*$/, '')
    .replace(/[|｜]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function stripStepNo(s) {
  return String(s)
    .replace(/^(?:第\s*\d+\s*步[\s:：,，、.．]*|步骤\s*\d+[\s:：,，、.．]*|(?:step\s*)?\d+\s*[.、)）:：]\s*|[-–—·•]\s*)/i, '')
    .trim();
}

function splitTags(v) {
  return String(v || '')
    .split(/[\s,，、;；\/|]+/)
    .map(t => t.replace(/^#+/, '').trim())
    .filter(Boolean)
    .slice(0, 12);
}

function addIng(out, line, group) {
  let s = String(line).replace(/[|｜]/g, ' ').replace(/\s+/g, ' ').trim();
  s = s.replace(/^[-–—]\s*/, '').replace(/[:：]$/, '').trim();
  if (!s) return;

  let name = s;
  let amount = '';
  const sp = s.split(' ');
  if (sp.length >= 2) {
    name = sp[0];
    amount = sp.slice(1).join(' ');
  } else {
    // 「鸡蛋3个」这种无空格写法：从第一个数字处切开
    const m = s.match(/^(.*\D)\s*(\d[\s\S]*)$/);
    if (m) { name = m[1]; amount = m[2]; }
  }
  name = name.replace(/[:：]$/, '').trim();
  if (!name) return;
  out.ingredients.push({ name, amount: amount.trim(), group });
}

function addBake(out, line) {
  const s = String(line).replace(/[|｜，,]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!s) return;

  const toks = s.split(' ');
  const numIdx = [];
  toks.forEach((t, i) => { if (/\d/.test(t)) numIdx.push(i); });

  if (!numIdx.length) {
    out.bakes.push({ temp: '', time: '', label: s });
    return;
  }

  const t1 = toks[numIdx[0]];
  const t2 = numIdx.length > 1 ? toks[numIdx[1]] : '';
  const rest = toks.filter((_, i) => i !== numIdx[0] && i !== numIdx[1]).join(' ');

  // 「180℃/25min」这种一个 token 里同时含温度和时间
  const both = t1.match(/^(\d+\s*(?:℃|°C|度)?)\s*[\/／]\s*(\d+\s*\S*)$/);
  if (both && !t2) {
    out.bakes.push({ temp: both[1], time: both[2], label: rest });
    return;
  }

  out.bakes.push({ temp: t1, time: t2, label: rest });
}

function tryParseJsonRecipe(src) {
  const t = src.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  if (!/^[[{]/.test(t)) return null;

  let data;
  try { data = JSON.parse(t); } catch { return null; }

  let r = data;
  if (Array.isArray(data)) r = data[0];
  else if (Array.isArray(data.recipes)) r = data.recipes[0];
  else if (data.recipe) r = data.recipe;
  if (!r || typeof r !== 'object' || !r.name) return null;

  const rawType = String(r.type || '');
  const type = CATEGORIES.some(c => c.id === rawType) ? rawType
    : (/烘焙|烤|bake|oven/i.test(rawType) ? 'bake' : 'stir');

  return {
    name: String(r.name),
    type,
    yield: r.yield && +r.yield.count > 0 ? { count: +r.yield.count, label: String(r.yield.label || '个') } : null,
    tags: Array.isArray(r.tags) ? r.tags.map(String) : splitTags(r.tags || ''),
    ingredients: (Array.isArray(r.ingredients) ? r.ingredients : []).map(it => ({
      name: String(it?.name ?? it ?? ''),
      amount: String(it?.amount ?? ''),
      group: it?.group === 'aux' ? 'aux' : 'main'
    })).filter(it => it.name),
    bakes: (Array.isArray(r.bakes) ? r.bakes : []).map(b => ({
      temp: String(b?.temp ?? b?.temperature ?? ''),
      time: String(b?.time ?? ''),
      label: String(b?.label ?? '')
    })),
    steps: (Array.isArray(r.steps) ? r.steps : []).map(String)
  };
}

function parseRecipeText(raw) {
  const src = String(raw || '').replace(/\r\n?/g, '\n').trim();
  if (!src) return { data: null, error: '还没有内容。把 AI 整理好的文字粘贴进来。' };

  const asJson = tryParseJsonRecipe(src);
  if (asJson) {
    if (asJson.type === 'bake') asJson.ingredients.forEach(i => { i.group = 'main'; });
    return { data: asJson, error: null };
  }

  const out = { name: '', type: '', yield: null, tags: [], ingredients: [], bakes: [], steps: [] };
  let section = null;

  for (const rawLine of src.split('\n')) {
    const line = normalizeLine(rawLine);
    if (!line) continue;

    const m = line.match(/^([^：:]{1,10})[：:]\s*(.*)$/);
    if (m) {
      const field = matchField(m[1]);
      const val = m[2].trim();
      if (field === 'name') { if (val) { out.name = val; section = null; } continue; }
      if (field === 'type') { if (val) { out.type = val; section = null; } continue; }
      if (field === 'yield') {
        const ym = val.match(/^(\d+(?:\.\d+)?)\s*(.*)$/);
        if (ym) out.yield = { count: +ym[1], label: ym[2].trim() || '个' };
        section = null; continue;
      }
      if (field === 'tags') { out.tags = splitTags(val); section = null; continue; }
      if (field === 'main') { section = 'main'; if (val) addIng(out, val, 'main'); continue; }
      if (field === 'aux') { section = 'aux'; if (val) addIng(out, val, 'aux'); continue; }
      if (field === 'ing') { section = 'ing'; if (val) addIng(out, val, 'main'); continue; }
      if (field === 'bake') { section = 'bake'; if (val) addBake(out, val); continue; }
      if (field === 'steps') { section = 'steps'; const s = stripStepNo(val); if (s) out.steps.push(s); continue; }
    }

    if (section === 'main') addIng(out, line, 'main');
    else if (section === 'aux') addIng(out, line, 'aux');
    else if (section === 'ing') addIng(out, line, 'main');
    else if (section === 'bake') addBake(out, line);
    else if (section === 'steps') { const s = stripStepNo(line); if (s) out.steps.push(s); }
    else if (!out.name) out.name = line;
  }

  if (!out.name) {
    return { data: null, error: '没有识别到菜谱名称。确认文本里有「名称：番茄炒蛋」这样一行，或把菜名放在第一行。' };
  }
  if (!out.ingredients.length && !out.steps.length && !out.bakes.length) {
    return { data: null, error: '只识别到名称，没有找到材料或步骤。检查文本里是否有「主料：」「材料：」「操作：」这类小标题。' };
  }

  // 类型推断：显式「类型」优先；截图只拍到材料、没有温度时间时，靠菜名和材料兜底
  const tRaw = String(out.type || '');
  const BAKE_SIGNAL = /蛋糕|面包|饼干|蛋挞|曲奇|吐司|贝果|司康|马芬|玛芬|泡芙|慕斯|戚风|舒芙蕾|布丁|派皮|塔皮|低筋面粉|高筋面粉|酵母|打发|烤箱|预热|烘烤|烘焙/;
  const corpus = [out.name, ...out.ingredients.map(i => i.name), ...out.steps].join(' ');
  let type = 'stir';
  if (/烘焙|烤|bake|oven|pastry/i.test(tRaw)) type = 'bake';
  else if (/家常|炒|煎|炖|煮|蒸|拌|焖|烧|烩|stir|fry|cook/i.test(tRaw)) type = 'stir';
  else if (out.bakes.length) type = 'bake';
  else if (BAKE_SIGNAL.test(corpus)) type = 'bake';

  if (type === 'bake') out.ingredients.forEach(i => { i.group = 'main'; });

  return {
    data: {
      name: out.name.trim(),
      type,
      yield: out.yield,
      tags: out.tags,
      ingredients: out.ingredients,
      steps: out.steps,
      bakes: type === 'bake' ? out.bakes : []
    },
    error: null
  };
}

