async function loadAll() {
  state.recipes = await Store.all();
}

/* 旧数据没有 order 字段：按更新时间从新到旧补一遍（与原有显示顺序一致） */
function normalizeOrder() {
  const need = state.recipes.some(r => typeof r.order !== 'number');
  if (!need) return;
  const sorted = state.recipes.slice().sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0));
  sorted.forEach((r, i) => { r.order = i; });
  Store.putMany(sorted);
}

/* 新菜谱排到最前（order 越小越靠前） */
function nextOrder() {
  return state.recipes.reduce((m, r) => Math.min(m, typeof r.order === 'number' ? r.order : 0), 0) - 1;
}

function visibleRecipes() {
  let arr = state.recipes;
  if (state.filter === 'fav') arr = arr.filter(r => r.favorite);
  else if (state.filter !== 'all') arr = arr.filter(r => r.type === state.filter);

  const q = state.query.trim().toLowerCase();
  if (q) {
    arr = arr.filter(r =>
      String(r.name || '').toLowerCase().includes(q) ||
      (r.tags || []).some(t => String(t).toLowerCase().includes(q))
    );
  }

  return arr.slice().sort((a, b) =>
    (typeof a.order === 'number' ? a.order : 0) - (typeof b.order === 'number' ? b.order : 0)
  );
}

/* ══════════ 文本中的时间识别 ══════════
   只认 h / min 两种写法（如「焖 10min」「烤 1.5h」），
   变成果可点按钮，点一下跳到计时器并填好时长。
   中文的「10 分钟」「半小时」一律不识别——误伤太多（分成、分钟…）。 */
const UNIT_SEC = { h: 3600, min: 60, 小时: 3600, 分钟: 60, 分: 60, 秒钟: 1, 秒: 1 };

/* 数字后紧跟 h 或 min；后面不能再跟字母，避免把 hours / minutes 也算进来 */
const TIME_RE = /(\d+(?:\.\d+)?)\s*(h|min)(?![a-zA-Z])/gi;

function timeToSec(numStr, unit) {
  const n = parseFloat(numStr);
  if (!isFinite(n)) return null;
  const per = UNIT_SEC[unit] ?? UNIT_SEC[String(unit).toLowerCase()];
  if (!per) return null;
  const sec = Math.round(n * per);
  return sec > 0 && sec <= 24 * 3600 ? sec : null;
}

/* 当前详情页做到第几步（0 = 一步没做）。步骤里的时间按钮要跟着一起变蓝，
   所以做成渲染期间可读的全局值，省得把状态一路传进 linkifyTime。 */
let detailDoneStep = 0;

/* stepNo：这一步是第几步（1 起）。传了才会带上序号，点的时候好提示「第 N 步」 */
function linkifyTime(raw, stepNo) {
  const s = esc(raw);
  let out = '';
  let last = 0;
  TIME_RE.lastIndex = 0;
  let m;
  const done = stepNo && stepNo <= detailDoneStep;
  while ((m = TIME_RE.exec(s))) {
    const end = m.index + m[0].length;
    const sec = timeToSec(m[1], m[2]);
    if (!sec) continue;
    out += s.slice(last, m.index);
    out += `<button class="time-chip${done ? ' is-done' : ''}" data-timer-sec="${sec}"` +
      (stepNo ? ` data-step-no="${stepNo}"` : '') + `>${m[0]}</button>`;
    last = end;
  }
  out += s.slice(last);
  return out;
}

/* 温度 / 时间拆分为数值 + 单位，便于排版 */
function splitFigure(v, defUnit) {
  const s = String(v ?? '').trim();
  if (!s) return null;
  const m = s.match(/^([\d.]+(?:\s*[-~～至]\s*[\d.]+)?)\s*(.*)$/);
  if (!m) return { num: s, unit: '' };
  let unit = m[2].trim();
  if (!unit) unit = defUnit;
  unit = unit.replace(/℃/g, '°C');
  return { num: m[1].replace(/\s+/g, ''), unit };
}

/* ── 首页：搜索栏下方的分类小按钮 ── */
function renderChips() {
  const counts = {};
  CATEGORIES.forEach(c => { counts[c.id] = 0; });
  let favCount = 0;
  state.recipes.forEach(r => {
    if (counts[r.type] !== undefined) counts[r.type]++;
    if (r.favorite) favCount++;
  });

  const chip = (key, label, n, extra = '') => {
    const on = state.filter === key;
    return `<button class="chip ${on ? 'is-on' : ''} ${extra}" data-filter="${key}">${esc(label)}<span class="chip-n">${n}</span></button>`;
  };

  const parts = [chip('all', '全部菜谱', state.recipes.length)];
  CATEGORIES.forEach(c => parts.push(chip(c.id, c.name, counts[c.id])));
  parts.push(chip('fav', '红心', favCount, 'is-fav'));

  chipBar.innerHTML = parts.join('');
}

