          </button>`
        : `<button class="fav-btn ${r.favorite ? 'is-on' : ''}" data-fav="${esc(r.id)}" aria-label="红心" aria-pressed="${r.favorite ? 'true' : 'false'}">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linejoin="round">
              <path d="M12 20.3s-7.2-4.4-7.2-9.2a4.2 4.2 0 0 1 7.2-2.9 4.2 4.2 0 0 1 7.2 2.9c0 4.8-7.2 9.2-7.2 9.2z"/>
