/* ── 首页管理模式：长按进入，拖动排序 / 删除卡片 ── */
function setManage(on) {
  const was = state.manage;
  state.manage = !!on;
  const btn = $('btn-manage');
  if (btn) {
    btn.hidden = !state.manage;
    btn.textContent = '完成';
  }
  homeView.classList.toggle('is-manage-mode', state.manage);
  document.body.classList.toggle('is-manage', state.manage);
  renderHome(false);
  /* 管理模式占用一条历史记录：系统返回键先退出管理，而不是退出应用 */
