/* ── 卡片拖动排序 ── */
let cardDrag = null;
let cardPress = null;
let suppressCardClick = false;
const CARD_PRESS_MS = 460;

function cardDragStart(e, card) {
  cardDrag = {
    card, id: card.dataset.id, pid: e.pointerId,
    startX: e.clientX, startY: e.clientY, active: false
  };
}

function cardDragActivate(s) {
  const rect = s.card.getBoundingClientRect();
  s.active = true;
  s.height = rect.height;
  s.baseTop = rect.top;
  s.scroller = homeBody;
  s.scrollStart = homeBody.scrollTop;

  const slot = document.createElement('div');
  slot.className = 'card-slot';
  slot.style.height = s.height + 'px';
  s.card.parentElement.insertBefore(slot, s.card);
  s.slot = slot;

  document.body.appendChild(s.card);
  s.card.classList.add('is-dragging');
  Object.assign(s.card.style, {
    /* z 低于底部导航（30），拖动的卡片会从导航下面穿过 */
    position: 'fixed', left: rect.left + 'px', top: rect.top + 'px',
    width: rect.width + 'px', margin: '0', zIndex: '20', pointerEvents: 'none'
  });
  if (navigator.vibrate) { try { navigator.vibrate(10); } catch {} }
}

function cardDragMove(e) {
  const s = cardDrag;
  if (!s || e.pointerId !== s.pid) return;
  const dy = e.clientY - s.startY;
  const dx = e.clientX - s.startX;
  if (!s.active) {
    if (Math.abs(dy) < 7 && Math.abs(dx) < 7) return;
    cardDragActivate(s);
  }
  e.preventDefault();

  const scroller = s.scroller;
  const sd = scroller ? scroller.scrollTop - s.scrollStart : 0;
  s.card.style.top = (s.baseTop + dy - sd) + 'px';

  if (scroller) {
    const sr = scroller.getBoundingClientRect();
    if (e.clientY < sr.top + 70) scroller.scrollTop -= 10;
    else if (e.clientY > sr.bottom - 70) scroller.scrollTop += 10;
  }

  const center = s.baseTop + dy - sd + s.height / 2;
  const cards = [...recipeList.querySelectorAll('.card')].filter(c => c !== s.card);
  let before = null;
  for (const c of cards) {
    const r = c.getBoundingClientRect();
    if (center < r.top + r.height / 2) { before = c; break; }
  }
  if (before) recipeList.insertBefore(s.slot, before);
  else recipeList.appendChild(s.slot);
}

async function cardDragEnd() {
  const s = cardDrag;
  if (!s) return;
  cardDrag = null;
  if (!s.active) return;

  // 拖拽后浏览器可能补发一次 click，吞掉它
  suppressCardClick = true;
  setTimeout(() => { suppressCardClick = false; }, 180);

  // 占位块之前有几张卡，就是拖到第几位
  let idx = 0;
  for (const n of recipeList.children) {
    if (n === s.slot) break;
    if (n.classList.contains('card')) idx++;
  }

  s.card.classList.remove('is-dragging');
  s.card.removeAttribute('style');
  if (s.slot && s.slot.parentElement) s.slot.replaceWith(s.card);

  await commitCardOrder(s.id, idx);
}

/* 只在可见列表内重排：用相邻项的 order 取中间值，避免顺序打架 */
async function commitCardOrder(id, newIdx) {
  const vis = visibleRecipes();
  const from = vis.findIndex(r => r.id === id);
  if (from < 0 || from === newIdx) { renderHome(false); return; }

  const arr = vis.slice();
  const [item] = arr.splice(from, 1);
  arr.splice(newIdx, 0, item);

  const pv = typeof arr[newIdx - 1]?.order === 'number' ? arr[newIdx - 1].order : null;
  const nv = typeof arr[newIdx + 1]?.order === 'number' ? arr[newIdx + 1].order : null;
  item.order = (pv !== null && nv !== null) ? (pv + nv) / 2
    : pv !== null ? pv + 1
    : nv !== null ? nv - 1
    : 0;

  await Store.put(item);
  renderHome(false);
}

/* 长按卡片进入管理模式；手指没抬起就接着变成拖动 */
function cardPressDown(e) {
  if (e.button !== undefined && e.button > 0) return;
  const card = e.target.closest('.card');
  if (!card) return;
  if (e.target.closest('.fav-btn') || e.target.closest('.card-del')) return;

  const handle = e.target.closest('[data-card-handle]');
  if (state.manage) {
    if (handle) cardDragStart(e, card);
    return;
  }
  if (handle) return;

  clearTimeout(cardPress && cardPress.timer);
  const id = card.dataset.id;
  cardPress = {
    id,
    pid: e.pointerId,
    x: e.clientX,
    y: e.clientY,
    timer: setTimeout(() => {
      cardPress = null;
      /* 长按是功能手势，不是选文字：清掉系统可能已产生的选区 */
      try { window.getSelection()?.removeAllRanges(); } catch {}
      setManage(true);
      const fresh = recipeList.querySelector(`.card[data-id="${id}"]`);
      if (fresh) cardDragStart(e, fresh);
      toast('已进入编辑模式，拖动左侧把手排序');
    }, CARD_PRESS_MS)
  };
}

function cardPressMove(e) {
  const p = cardPress;
  if (!p || e.pointerId !== p.pid) return;
  if (Math.abs(e.clientX - p.x) > 8 || Math.abs(e.clientY - p.y) > 8) {
    clearTimeout(p.timer);
    cardPress = null;
  }
}

function cardPressCancel() {
  if (cardPress) { clearTimeout(cardPress.timer); cardPress = null; }
}

async function deleteCard(id) {
  const r = state.recipes.find(x => x.id === id);
  if (!r) return;
  const ok = await confirmDialog({
    title: '删除这道菜？',
    text: `「${r.name}」将被永久删除，无法恢复。`,
    ok: '删除',
    danger: true
  });
  if (!ok) return;
  await Store.remove(id);
  state.recipes = state.recipes.filter(x => x.id !== id);
  renderHome(false);
  toast('已删除');
}

/* 单位换算弹层 */
function openConvert(name, amt) {
  $('conv-title').textContent = name;
  const p = splitAmount(amt);
  const { d, label } = guessDensity(name);
  const ml = amountToML(p.num, p.unit, d);
  const body = $('conv-body');

  if (ml == null) {
    body.innerHTML = '<p class="conv-empty">这个用量暂时无法自动换算。</p>';
  } else {
    const g = ml * d;
    const rows = [];
    if (p.unit !== 'g') rows.push(['克（g）', g]);
    if (p.unit !== 'ml') rows.push(['毫升（ml）', ml]);
    if (g >= 1000 && p.unit !== 'kg') rows.push(['千克（kg）', g / 1000]);
    if (ml >= 1000 && p.unit !== 'L') rows.push(['升（L）', ml / 1000]);
    if (p.unit !== '杯') rows.push(['杯（240ml）', ml / 240]);
    if (p.unit !== '汤匙' && p.unit !== '勺') rows.push(['汤匙（15ml）', ml / 15]);
    if (p.unit !== '茶匙') rows.push(['茶匙（5ml）', ml / 5]);

    body.innerHTML = `
      <div class="conv-main">${esc(p.num)} ${esc(p.unit)}</div>
      ${rows.map(([n, v]) => `<div class="conv-row"><span>${n}</span><strong>≈ ${niceNum(v)}</strong></div>`).join('')}
      <p class="conv-note">${label ? `按${label}密度约 ${d} g/ml 估算` : '未识别食材种类，按水/通用液体密度估算'}，实际以食材为准。</p>`;
  }
  $('sheet-convert').hidden = false;
}

/* ══════════ 计时器 ══════════
   顶部倒计时读数，中间大旋钮：绕圈滑动调整时间，一圈 = 30 分钟。
   左右加减按钮每次调整 5 分钟（可在侧边栏改成 1/2/3/5/10 分钟）。 */
const KNOB_FULL = 30 * 60;      // 旋钮一圈对应的秒数
const KNOB_STEP = 30;           // 滑动的最小步进：30 秒
const MAX_SEC = 24 * 60 * 60;   // 最长 24 小时
const LS_STEP = 'recipe-book:timer-step';
const LS_PIN = 'recipe-book:pinned-recipe';
const LS_PRESETS = 'recipe-book:timer-presets';
const LS_VIBRATE = 'recipe-book:timer-vibrate';
const LS_SOUND = 'recipe-book:timer-sound';

const timer = { set: 0, remain: 0, running: false, ringing: false, endAt: 0, tick: null, stepNo: 0 };

/* 某些 WebView 的 file:// 源不允许 localStorage，读写一律兜底，不能让脚本中断 */
const lsGet = (k, d) => { try { const v = localStorage.getItem(k); return v === null ? d : v; } catch { return d; } };
const lsSet = (k, v) => { try { localStorage.setItem(k, v); } catch {} };

/* 到点后的提醒方式，可在计时器的汉堡菜单里开关 */
let ringVibrate = lsGet(LS_VIBRATE, '1') !== '0';
let ringSound = lsGet(LS_SOUND, '1') !== '0';

let timerStepMin = Number(lsGet(LS_STEP, 5)) || 5;
let timerPresets = (() => {
  try {
    const v = JSON.parse(lsGet(LS_PRESETS, '[]'));
    return (Array.isArray(v) ? v : []).filter(n => +n > 0).slice(0, 3).map(n => Math.round(n));
  } catch { return []; }
})();

const savePresets = () => lsSet(LS_PRESETS, JSON.stringify(timerPresets));

/* ── 时间格式 ── */
function fmtClock(sec) {
  const t = Math.max(0, Math.round(sec || 0));
  return `${pad(Math.floor(t / 3600))}:${pad(Math.floor(t % 3600 / 60))}:${pad(t % 60)}`;
}

function fmtCompact(sec) {
  const t = Math.max(0, Math.round(sec || 0));
  const h = Math.floor(t / 3600), m = Math.floor(t % 3600 / 60), s = t % 60;
  return h ? `${h}:${pad(m)}:${pad(s)}` : `${pad(m)}:${pad(s)}`;
}

/* 旋钮能以 30 秒为单位调整，所以这里要把秒显示出来，不然读数会跳 */
function fmtShort(sec) {
  const t = Math.max(0, Math.round(sec || 0));
  const h = Math.floor(t / 3600), m = Math.floor(t % 3600 / 60), s = t % 60;
  if (!h && !m) return `${s} 秒`;
  if (!h) return s ? `${m} 分 ${s} 秒` : `${m} 分钟`;
  if (!m && !s) return `${h} 小时`;
  return `${h} 小时 ${m} 分${s ? ` ${s} 秒` : ''}`;
}

/* ── 时间设定 ── */
function shownSec() {
  return timer.running ? Math.max(0, (timer.endAt - Date.now()) / 1000) : timer.remain;
}

/* ── 计时状态持久化 ──
   离开计时器页面、退到后台、甚至重启 App 或热更新之后，倒计时都接着走。
   存的是「设定时长 + 到点时间戳」，不依赖页面是否活着。 */
const K_TIMER = 'timer';
const LS_NOTIFY_ASKED = 'notifyAsked';

/* ══════ 通知栏倒计时 ══════
   最小化、锁屏之后还能在系统通知栏看到剩余时间。
   这需要 APK 原生壳带 TimerNotify 服务；老包或纯热更新环境里没有这些方法，
   下面全部静默跳过，只影响「看不看得见」，不影响计时本身。 */
function notifyBridge() {
  const b = window.AndroidShell;
  return (b && typeof b.notifyStart === 'function') ? b : null;
}

/* 通知栏标题：从菜谱步骤进来时带上「第 N 步」，方便在通知栏分辨是哪一步 */
const notifyLabel = () => (timer.stepNo ? `第 ${timer.stepNo} 步` : '');

function syncNotify() {
  const b = notifyBridge();
  if (!b) return;
  try {
    if (timer.running && timer.endAt > Date.now()) {
      b.notifyStart(String(timer.endAt), String(Math.round(timer.set || timer.remain)), notifyLabel());
    } else if (timer.ringing) {
      /* 到点了：让通知停在「计时完成」，直到点完成才撤掉 */
      b.notifyStart(String(Date.now()), String(Math.round(timer.set)), notifyLabel());
    } else {
      b.notifyStop();
    }
  } catch {}
}

/* 通知权限只问一次，免得每次点开始都弹系统框 */
function askNotify() {
  const b = notifyBridge();
  if (!b || typeof b.notifyAsk !== 'function') return;
  if (lsGet(LS_NOTIFY_ASKED, '0') === '1') return;
  lsSet(LS_NOTIFY_ASKED, '1');
  try { b.notifyAsk(); } catch {}
}

function saveTimer() {
  OtaStore.write(K_TIMER, {
    set: timer.set,
    remain: timer.remain,
    endAt: timer.endAt,
    running: timer.running,
    ringing: timer.ringing,
    at: Date.now()
  });
}

async function restoreTimer() {
  const s = await OtaStore.read(K_TIMER);
  if (!s || !s.set) return;
  timer.set = s.set;
  timer.endAt = s.endAt || 0;
  if (s.running) {
    const left = (timer.endAt - Date.now()) / 1000;
    if (left <= 0) {                      // 离开期间已经到点了
      timer.running = true;
      finishTimer();
      return;
    }
    timer.running = true;
    timer.remain = left;
    clearInterval(timer.tick);
    timer.tick = setInterval(timerTick, 250);
    syncNotify();                         // 重启 / 热更新后把通知栏也接上
  } else {
    timer.running = false;
    timer.remain = s.remain > 0 ? s.remain : s.set;
    timer.ringing = !!s.ringing;
  }
  renderTimer();
}

/* 从后台回到前台：按真实时间补算一次，错过了到点就立刻提醒 */
function timerCatchUp() {
  if (!timer.running) return;
  const left = (timer.endAt - Date.now()) / 1000;
  if (left <= 0) { finishTimer(); return; }
  timer.remain = left;
  renderTimer();
}

/* 直接设定（旋钮拖动用）：running 时改的是剩余时间 */
function applyTime(sec) {
  const v = Math.min(MAX_SEC, Math.max(0, Math.round(sec)));
  if (timer.running) {
    timer.remain = v;
    timer.set = Math.max(timer.set, v);
    timer.endAt = Date.now() + v * 1000;
  } else {
    timer.set = v;
    timer.remain = v;
  }
  renderTimer();
  saveTimer();
  syncNotify();
}

/* 相对调整（加减按钮用） */
function adjustTime(delta) {
  applyTime((timer.running ? timer.remain : timer.set) + delta);
}

function startTimer() {
  const sec = timer.remain > 0 ? timer.remain : timer.set;
  if (sec <= 0) return;
  timer.set = Math.max(timer.set, sec);
  timer.remain = sec;
  timer.running = true;
  timer.endAt = Date.now() + sec * 1000;
  clearInterval(timer.tick);
  timer.tick = setInterval(timerTick, 250);
  renderTimer();
  saveTimer();
  askNotify();
  syncNotify();
  /* 刚弹出权限框时用户还没点允许，补发一次才赶得上 */
  setTimeout(syncNotify, 900);
}

/* 回到设定时长：未开始时叫「重置」，计时中途叫「取消」 */
function resetTimer() {
  stopRing();
  timer.ringing = false;
  timer.running = false;
  timer.remain = timer.set;
  clearInterval(timer.tick);
  timer.tick = null;
  renderTimer();
  saveTimer();
  syncNotify();
}

function pauseTimer() {
  timer.remain = Math.max(0, (timer.endAt - Date.now()) / 1000);
  timer.running = false;
  clearInterval(timer.tick);
  timer.tick = null;
  renderTimer();
  saveTimer();
  syncNotify();
}

let tickCount = 0;
function timerTick() {
  const left = (timer.endAt - Date.now()) / 1000;
  if (left <= 0) { finishTimer(); return; }
  timer.remain = left;
  renderTimer();
  if (++tickCount % 8 === 0) saveTimer();   // 每 2 秒记一次，掉电也不丢
}

function buzz(pattern) {
  if (navigator.vibrate) { try { navigator.vibrate(pattern); } catch {} }
}

/* ── 响铃：蜂鸣用 Web Audio 现场合成，不依赖任何音频文件 ── */
let audioCtx = null;
function beep() {
  try {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    audioCtx = audioCtx || new AC();
    if (audioCtx.state === 'suspended') audioCtx.resume();
    const t = audioCtx.currentTime;
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(880, t);
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(0.32, t + 0.03);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.45);
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start(t);
    osc.stop(t + 0.5);
  } catch {}
}

/* ── 到点提醒：一直响到点「完成」为止（最多 60 秒自动收） ── */
let ringTick = null;
let ringAutoTimer = null;

function ringOnce() {
  if (ringVibrate) buzz([600, 260, 600, 260, 900]);
  if (ringSound) beep();
}

function startRing() {
  stopRing();
  ringOnce();
  ringTick = setInterval(ringOnce, 1300);
  ringAutoTimer = setTimeout(() => stopRing(), 60000);
}

function stopRing() {
  clearInterval(ringTick); ringTick = null;
  clearTimeout(ringAutoTimer); ringAutoTimer = null;
  if (navigator.vibrate) { try { navigator.vibrate(0); } catch {} }
}

/* 点「完成」：停掉提醒，回到设定时长 */
function finishRing() {
  stopRing();
  timer.ringing = false;
  timer.remain = timer.set;
  renderTimer();
  saveTimer();
  syncNotify();                         // 点完成后撤掉通知
}

function finishTimer() {
  timer.running = false;
  timer.remain = 0;
  clearInterval(timer.tick);
  timer.tick = null;
  timer.ringing = true;
  renderTimer();
  saveTimer();
  syncNotify();                         // 通知栏也翻成「计时完成」
  /* 人不在计时器页也要能看到「完成」，否则只能干等着响铃 */
  if (!timerView.classList.contains('is-open')) openTimer();
  startRing();
  toast('时间到');
}

/* ── 渲染 ── */
/* 红点位置：剩余时间（未开始时等于设定值）占一圈 30 分钟的角度，
   运行时随剩余时间逆时针回到 0（正上方） */
function renderKnobDot() {
  const deg = (Math.max(0, timer.remain) / KNOB_FULL * 360) % 360;
  const outer = knob.offsetWidth / 2;
  const inner = knobCenter.offsetWidth / 2;
  const midR = (outer + inner) / 2;               // 白环内外边缘的居中轨道
  knobDot.style.transform = `translate(-50%,-50%) rotate(${deg}deg) translateY(${-midR}px)`;
}

function renderTimer() {
  const shown = shownSec();
  const isDone = !timer.running && timer.set > 0 && timer.remain <= 0;

  timerClock.textContent = fmtClock(shown);
  timerClock.classList.toggle('is-done', isDone);

  const has = timer.set > 0 || timer.remain > 0;
  knobCenter.classList.toggle('is-ringing', timer.ringing);
  /* 响铃时中心只留一个「完成」 */
  timerStartBtn.hidden = timer.ringing;
  timerStartBtn.disabled = !has || timer.ringing;
  timerStartBtn.textContent = timer.running ? '暂停' : (timer.remain > 0 && timer.remain < timer.set ? '继续' : '开始');

  timerAltBtn.hidden = !has && !timer.ringing;
  timerAltBtn.disabled = !has && !timer.ringing;
  timerAltBtn.textContent = timer.ringing ? '完成' : (timer.running ? '取消' : '重置');

  renderKnobDot();

  /* 底部「计时器」图标上点一个红点，表示后台还在走 */
  const timerTab = document.querySelector('#tab-bar .dock-tab[data-tab="timer"]');
  if (timerTab) timerTab.classList.toggle('is-counting', timer.running);

  /* 从菜谱某一步的时间按钮进来时，读数下面标出是第几步 */
  const stepTip = $('timer-step');
  if (stepTip) {
    const n = timer.stepNo || 0;
    stepTip.textContent = n ? `第 ${n} 步` : '';
    stepTip.hidden = !n;
  }
}

function renderPresets() {
  presetsEl.innerHTML = timerPresets.map((sec, i) => `
    <button class="preset" data-preset="${i}">
      <span class="preset-t">${esc(fmtShort(sec))}</span>
      <span class="preset-l">${esc(fmtCompact(sec))}</span>
    </button>`).join('');
}

/* ── 全局浮层：汉堡菜单 + 底部导航 ──
   两者都在页面之外，层级高于首页和计时器，
   所以计时器从右侧盖上来时它们仍浮在最前。
   进入详情 / 编辑 / 导入这类子页面时才退场。 */
function updateChrome() {
  const onTimer = timerView.classList.contains('is-open');
  const onSub = detailView.classList.contains('is-open')
    || editView.classList.contains('is-open')
    || importView.classList.contains('is-open')
    || diaryView.classList.contains('is-open')
    || diaryNewView.classList.contains('is-open');
  /* 美食日记是全屏整页，底部菜单和汉堡都不出现；但计时器要照常浮着 */
  const show = onTimer || !onSub;

  dock.classList.toggle('is-hidden', !show);
  chromeMenu.classList.toggle('is-hidden', !show);
  /* 计时器页没有「新建菜谱」 */
  dock.classList.toggle('no-add', onTimer);

  const on = tabBar.querySelector('.dock-tab.is-on');
  const want = onTimer ? 'timer' : 'home';
  if (!on || on.dataset.tab !== want) {
    tabBar.querySelectorAll('.dock-tab').forEach(b => {
      b.classList.toggle('is-on', b.dataset.tab === want);
    });
  }
}

/* ── 打开 / 关闭 ── */
function openTimer(sec, stepNo) {
  ingSuggestReset();
  /* 从菜谱步骤里的时间按钮进来时带着步骤号；从底部菜单进来则清空 */
  timer.stepNo = Number(stepNo) || 0;
  renderTimerPinHint();          // 顺带刷新顶部那条固定菜谱的名字
  if (typeof sec === 'number' && sec > 0) {
    /* 换成一个明确的新时长：正在响的提醒也一并收掉，不然会和新计时打架 */
    stopRing();
    timer.ringing = false;
    timer.set = Math.min(MAX_SEC, Math.round(sec));
    timer.remain = timer.set;
    timer.running = false;
    clearInterval(timer.tick);
    timer.tick = null;
  }
  renderPresets();
  renderTimer();
  timerView.classList.add('is-open');
  pushLayer();
  updateChrome();
}

function closeTimer() {
  timerView.classList.remove('is-open');
  timerView.style.transform = '';
  timerView.style.transition = '';
  updateChrome();
}

/* 底部标签切换：计时器从右往左盖住首页 */
function switchTab(name) {
  if (name === 'timer') {
    if (timerView.classList.contains('is-open')) return;
    /* 编辑模式占了一条历史记录，先退掉再开计时器，免得返回栈错位 */
    if (state.manage) { setManage(false); backHistory(); }
    openTimer();
    return;
  }
  if (timerView.classList.contains('is-open')) {
    closeTimer();
    backHistory();
    return;
  }
  homeBody.scrollTo({ top: 0, behavior: 'smooth' });
}

/* ══════════ 左右滑动切换首页 / 计时器 ══════════
   空白处横向滑一下（从左到右、从右到左都认）就在两个页面间切换：
   首页滑一下进计时器，计时器滑一下回首页（露出下面那一层）。
   卡片、旋钮、按钮这些要操作的地方不参与，避免和点击 / 旋转打架。 */
/* 不参与页面切换手势的地方：旋钮要绕圈滑动、搜索框和表单控件要点按。
   注意这里刻意不排除 .card —— 首页几乎被卡片铺满，排除了就等于哪儿都滑不动。 */
const SWIPE_SKIP = '.knob, .search, button, input, select, textarea, a';

let tabSwipe = null;

/* 用 touch 事件而不是 pointer：安卓 WebView 容易把滑动判定成滚动并
   发 pointercancel 打断手势；touchmove 里 preventDefault 能真正拦住滚动。 */
function bindTabSwipe() {
  const W = () => window.innerWidth || document.documentElement.clientWidth || 360;
  const pointOf = e => (e.touches && e.touches[0]) || (e.changedTouches && e.changedTouches[0]) || e;

  const resetTransforms = () => {
    timerView.style.transition = '';
    homeView.style.transition = '';
    timerView.style.transform = '';
    homeView.style.transform = '';
  };

  const start = e => {
    if (state.manage) return;                 // 编辑模式要拖卡片排序，整个页面都不抢这个手势
    if (e.target.closest(SWIPE_SKIP)) return;
    const t = pointOf(e);
    tabSwipe = { x0: t.clientX, y0: t.clientY, t0: Date.now(), locked: false, dx: 0 };
  };

  const move = e => {
    const s = tabSwipe;
    if (!s) return;
    if (state.manage) { tabSwipe = null; return; }   // 滑着进了编辑模式就撒手
    const t = pointOf(e);
    const dx = t.clientX - s.x0;
    const dy = t.clientY - s.y0;

    if (!s.locked) {
      /* 竖向意图明显就交给滚动，不抢 */
      if (Math.abs(dy) > 10 && Math.abs(dy) > Math.abs(dx)) { tabSwipe = null; return; }
      if (Math.abs(dx) < 8) return;
      s.locked = true;
      s.opening = !timerView.classList.contains('is-open');   // 在首页→拉开计时器；在计时器→收起
      if (s.opening) { renderPresets(); renderTimer(); }
      timerView.style.transition = 'none';
      homeView.style.transition = 'none';
      s.w = W();
    }
    s.dx = dx;
    if (e.cancelable) e.preventDefault();      // 拦住纵向滚动，手势才不会被系统抢走

    /* 计时器始终从右侧进出，跟随手指位移的绝对值；首页轻微视差 */
    const w = s.w || W();
    const p = Math.max(0, Math.min(1, Math.abs(dx) / w));
    if (s.opening) {
      timerView.style.transform = `translateX(${(w * (1 - p)).toFixed(1)}px)`;
      homeView.style.transform = `translateX(${(-30 * p).toFixed(1)}px)`;
    } else {
      timerView.style.transform = `translateX(${(w * p).toFixed(1)}px)`;
      homeView.style.transform = `translateX(${(-30 * (1 - p)).toFixed(1)}px)`;
    }
  };

  const end = e => {
    const s = tabSwipe;
    if (!s) return;
    tabSwipe = null;
    if (!s.locked) return;
    resetTransforms();

    const w = s.w || W();
    const fast = (Date.now() - s.t0) < 380 && Math.abs(s.dx) > 40;
    if (!fast && Math.abs(s.dx) < w * 0.26) return;   // 没滑到位，弹回原样

    if (s.opening) {
      if (!timerView.classList.contains('is-open')) openTimer();
    } else if (timerView.classList.contains('is-open')) {
      closeTimer();
      backHistory();
    }
  };

  [homeView, timerView].forEach(v => {
    v.addEventListener('touchstart', start, { passive: true });
    v.addEventListener('touchmove', move, { passive: false });
    v.addEventListener('touchend', end);
    v.addEventListener('touchcancel', () => {
      if (!tabSwipe) return;
      tabSwipe = null;
      resetTransforms();
    });
  });
}

/* ══════════ 固定菜谱 ══════════
   详情页菜名右边的小图钉，同时只能固定一个（再点一下取消，固定别的会顶掉）。
   固定之后在计时器页从上方往下划，就能把这道菜拉出来。
   原来「左滑回上次菜谱」和左右滑切页打架，所以换成这个下拉动作。 */
function loadPinned() {
  state.pinnedId = lsGet(LS_PIN, '') || null;
  /* 固定的菜谱可能已经被删掉了 */
  if (state.pinnedId && !state.recipes.some(r => r.id === state.pinnedId)) {
    state.pinnedId = null;
    lsSet(LS_PIN, '');
  }
}

function togglePin(id) {
  const on = state.pinnedId === id;
  state.pinnedId = on ? null : id;
  lsSet(LS_PIN, state.pinnedId || '');
  renderDetail();
  toast(on ? '已取消固定' : '已固定，计时器页向下拉就能看到');
}

/* 提示条平时藏在顶边外，只有下拉时才露出来 */
function renderTimerPinHint() {
  const hint = $('timer-pin-hint');
  if (!hint) return;
  const r = state.pinnedId && state.recipes.find(x => x.id === state.pinnedId);
  const name = $('tph-name');
  if (name) name.textContent = r ? r.name : '';
  hint.hidden = true;
  hint.style.transform = 'translateY(-100%)';
  hint.style.opacity = '0';
}

/* 拉出来：计时不中断，只是把计时器页收起腾地方 */
function openPinnedFromTimer() {
  const id = state.pinnedId;
  if (!id || !state.recipes.some(r => r.id === id)) return;
  if (timerView.classList.contains('is-open')) closeTimer();
  openDetail(id, true);          // 从上往下移动出现，呼应下拉的动作
}

function bindTimerPull() {
  const hint = $('timer-pin-hint');
  const body = $('timer-body');
  if (!hint || !body) return;
  let s = null;
  /* touches 不一定有（合成事件可能只给 clientX/Y），跟滑动手势一样做回退 */
  const pt = e => (e.touches && e.touches[0]) || (e.changedTouches && e.changedTouches[0]) || e;

  const settle = () => {
    hint.style.transition = 'transform .22s var(--ease), opacity .22s';
    hint.style.transform = 'translateY(-100%)';
    hint.style.opacity = '0';
  };

  const start = e => {
    if (!state.pinnedId) return;
    if (!timerView.classList.contains('is-open')) return;
    if (body.scrollTop > 0) return;        // 已经滚下去了，交回给滚动
    const t = pt(e);
    if (!t || typeof t.clientY !== 'number') return;
    s = { y0: t.clientY, dy: 0, on: false, h: 0 };
  };

  const move = e => {
    if (!s) return;
    const t = pt(e);
    if (!t || typeof t.clientY !== 'number') { s = null; return; }
    const dy = t.clientY - s.y0;
    if (dy <= 0) {                          // 往上划不参与
      if (s.on) { settle(); setTimeout(() => { if (!s) hint.hidden = true; }, 220); }
      s.on = false;
      s.dy = 0;
      return;
    }
    s.dy = dy;
    if (!s.on) {
      s.on = true;
      hint.hidden = false;
      hint.style.transition = 'none';
      s.h = hint.offsetHeight || 96;
    }
    const p = Math.min(1, dy / (s.h * 1.7));
    hint.style.transform = `translateY(${((-s.h) * (1 - p)).toFixed(1)}px)`;
    hint.style.opacity = String(Math.min(1, p * 1.5));
    if (e.cancelable) e.preventDefault();
  };

  const end = () => {
    if (!s) return;
    const opened = s.on && s.dy > s.h * 0.95;
    s = null;
    settle();
    setTimeout(() => { if (!s) hint.hidden = true; }, 220);
    if (opened) openPinnedFromTimer();
  };

  timerView.addEventListener('touchstart', start, { passive: true });
  timerView.addEventListener('touchmove', move, { passive: false });
  timerView.addEventListener('touchend', end);
  timerView.addEventListener('touchcancel', () => { s = null; settle(); hint.hidden = true; });
}

/* ── 旋钮手势 ── */
let knobDrag = null;

function knobAngle(x, y) {
  const r = knob.getBoundingClientRect();
  return Math.atan2(y - (r.top + r.height / 2), x - (r.left + r.width / 2)) * 180 / Math.PI;
}

function knobDown(e) {
  if (e.button !== undefined && e.button > 0) return;
  if (e.target.closest('.knob-center')) return;   // 中心圆盘里是按钮，不参与旋转
  e.preventDefault();
  knobDrag = {
    pid: e.pointerId,
    last: knobAngle(e.clientX, e.clientY),
    acc: (timer.running ? timer.remain : timer.set) / KNOB_FULL * 360
  };
  try { knob.setPointerCapture(e.pointerId); } catch {}
}

function knobMove(e) {
  const s = knobDrag;
  if (!s || e.pointerId !== s.pid) return;
  e.preventDefault();
  const a = knobAngle(e.clientX, e.clientY);
  let d = a - s.last;
  if (d > 180) d -= 360;
  else if (d < -180) d += 360;
  s.last = a;
  s.acc += d;
  /* 绕圈滑动的角度换算成秒，再按 30 秒取整 */
  applyTime(Math.round(s.acc / 360 * KNOB_FULL / KNOB_STEP) * KNOB_STEP);
}

function knobUp() { knobDrag = null; }

/* ── 侧边栏 ── */
let drawerMode = 'home';

function renderDrawer() {
  drawerInner.innerHTML = drawerMode === 'timer' ? timerDrawerHtml() : homeDrawerHtml();
}

function openDrawer(mode) {
  drawerMode = mode;
  renderDrawer();
  drawer.hidden = false;
  pushLayer();
}

function closeDrawer() {
  if (drawer.hidden) return;
  drawer.hidden = true;
  /* 复位面板，下次打开才会重新播入场动画 */
  const p = $('drawer-panel');
  if (p) {
    p.classList.remove('is-swiping');
    p.style.transition = '';
    p.style.transform = '';
  }
  backHistory();
}

/* ══════════ 配色自定义 ══════════
   4 个可改颜色：底色 / 卡片 / 主色 / 点缀，
   其余颜色全部由 CSS color-mix 自动推导。
   当前配色与保存的方案都存 localStorage。 */
const LS_THEME = 'recipe-book:theme-colors';
const LS_SCHEMES = 'recipe-book:color-schemes';

const THEME_DEFAULT = { bg: '#E7E7E4', card: '#FFFFFF', ink: '#141412', accent: '#E24B4A' };
const THEME_KEYS = [['bg', '底色'], ['card', '卡片'], ['ink', '主色'], ['accent', '点缀']];
const MAX_SCHEMES = 8;

let themeColors = { ...THEME_DEFAULT };
let colorSchemes = [];

function normalizeHex(v, fallback) {
  v = String(v || '').trim();
  return /^#[0-9a-fA-F]{6}$/.test(v) ? v.toUpperCase() : fallback;
}

function applyTheme(c) {
  themeColors = {
    bg: normalizeHex(c && c.bg, THEME_DEFAULT.bg),
    card: normalizeHex(c && c.card, THEME_DEFAULT.card),
    ink: normalizeHex(c && c.ink, THEME_DEFAULT.ink),
    accent: normalizeHex(c && c.accent, THEME_DEFAULT.accent)
  };
  const r = document.documentElement.style;
  r.setProperty('--c-bg', themeColors.bg);
  r.setProperty('--c-card', themeColors.card);
  r.setProperty('--c-ink', themeColors.ink);
  r.setProperty('--c-accent', themeColors.accent);
}

const saveTheme = () => lsSet(LS_THEME, JSON.stringify(themeColors));
const saveSchemes = () => lsSet(LS_SCHEMES, JSON.stringify(colorSchemes));

function loadTheme() {
  try {
    const c = JSON.parse(lsGet(LS_THEME, ''));
    if (c) applyTheme(c);
  } catch {}
  try {
    const s = JSON.parse(lsGet(LS_SCHEMES, '[]'));
    if (Array.isArray(s)) {
      colorSchemes = s.filter(x => x && x.name && x.colors).slice(0, MAX_SCHEMES);
    }
  } catch {}
}

function themeSectionHtml() {
  const schemes = colorSchemes.map((s, i) => `
    <span class="scheme-chip">
      <button class="scheme-apply" data-apply-scheme="${i}">
        <span class="scheme-dots">${['bg', 'card', 'ink', 'accent'].map(k =>
          `<i style="background:${esc(normalizeHex(s.colors[k], '#CCCCCC'))}"></i>`).join('')}</span>
        ${esc(s.name)}
      </button>
      <button class="scheme-del" data-del-scheme="${i}" aria-label="删除方案 ${esc(s.name)}">×</button>
    </span>`).join('');

  return `
    <div class="drawer-sec">
      <div class="drawer-sec-h">配色<span class="drawer-sec-tip">带出当前色值再微调</span></div>
      <button class="drawer-item" data-act="open-color"><span>更改配色</span><small>底色 · 卡片 · 主色 · 点缀</small></button>
      <button class="drawer-item" data-act="reset-theme"><span>恢复默认配色</span><small>浅灰底 · 白卡片 · 黑主色 · 红点缀</small></button>
      <div class="scheme-save">
        <input id="scheme-name" type="text" placeholder="给当前配色起个名字" maxlength="10" autocomplete="off">
        <button class="scheme-save-btn" data-act="save-scheme">保存方案</button>
      </div>
      ${schemes
        ? `<div class="scheme-list">${schemes}</div>`
        : '<p class="scheme-empty">还没有保存的配色方案。调好颜色后可以把整套存起来。</p>'}
    </div>`;
}

/* ══════════ 配色面板 ══════════
   不用 <input type="color">：它在 WebView 里弹出的取色器又简陋又总从黑色开始，
   没法在现有颜色上微调。这里自己带出当前色值，靠色值输入和 RGB 滑块改。 */
let colorEditKey = 'ink';

function hexToRgb(hex) {
  const h = normalizeHex(hex, '#000000');
  return [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
}

function rgbToHex(r, g, b) {
  return '#' + [r, g, b].map(v =>
    ('0' + Math.max(0, Math.min(255, Math.round(v))).toString(16)).slice(-2)).join('').toUpperCase();
}

/* 预览块上的字要在任意底色上都看得清，按亮度选黑或白 */
function readableInk(r, g, b) {
  return (r * 299 + g * 587 + b * 114) / 1000 > 140 ? '#141412' : '#FFFFFF';
}

function setThemeKey(k, hex) {
  themeColors[k] = normalizeHex(hex, themeColors[k]);
  applyTheme(themeColors);
  saveTheme();
}

function renderColorSheet() {
  $('color-body').innerHTML = `
    <div class="color-tabs" id="color-tabs">
      ${THEME_KEYS.map(([k, label]) =>
        `<button class="color-tab" data-color-key="${k}" type="button">${label}</button>`).join('')}
    </div>
    <div class="color-preview" id="color-preview">
      <span class="color-preview-hex" id="color-preview-hex"></span>
    </div>
    <div class="color-hex-row">
      <label for="color-hex">色值</label>
      <input class="color-hex" id="color-hex" type="text" maxlength="7" spellcheck="false" autocomplete="off">
    </div>
    <div class="color-slider"><i>R</i><input type="range" id="color-r" min="0" max="255" step="1"><b id="color-rv"></b></div>
    <div class="color-slider"><i>G</i><input type="range" id="color-g" min="0" max="255" step="1"><b id="color-gv"></b></div>
    <div class="color-slider"><i>B</i><input type="range" id="color-b" min="0" max="255" step="1"><b id="color-bv"></b></div>
    <div class="color-demo">
      <div class="color-demo-t">番茄炒蛋</div>
      <div class="color-demo-s">随手看看整体感觉，改完点完成</div>
    </div>`;

  $('color-body').querySelectorAll('[data-color-key]').forEach(btn => {
    btn.addEventListener('click', () => {
      colorEditKey = btn.dataset.colorKey;
      syncColorSheet(true);
    });
  });

  const hex = $('color-hex');
  hex.addEventListener('input', () => {
    const v = hex.value.trim();
    if (!/^#?[0-9a-fA-F]{6}$/.test(v)) return;
    setThemeKey(colorEditKey, v.startsWith('#') ? v : '#' + v);
    syncColorSheet(false);        // 正在打字，别回写输入框
  });
  hex.addEventListener('blur', () => syncColorSheet(true));

  ['r', 'g', 'b'].forEach((ch, i) => {
    $('color-' + ch).addEventListener('input', e => {
      const c = hexToRgb(themeColors[colorEditKey]);
      c[i] = Number(e.target.value);
      setThemeKey(colorEditKey, rgbToHex(c[0], c[1], c[2]));
      syncColorSheet(true);
    });
  });
}

/* 把面板上的控件同步到当前颜色；syncHex=false 表示别动色值输入框（正在输入） */
function syncColorSheet(syncHex) {
  const cur = themeColors[colorEditKey];
  const c = hexToRgb(cur);
  $('color-preview').style.background = cur;
  const ph = $('color-preview-hex');
  ph.textContent = cur;
  ph.style.color = readableInk(c[0], c[1], c[2]);
  if (syncHex) $('color-hex').value = cur;
  ['r', 'g', 'b'].forEach((ch, i) => {
    $('color-' + ch).value = c[i];
    $('color-' + ch + 'v').textContent = c[i];
  });
  document.querySelectorAll('#color-tabs [data-color-key]').forEach(b => {
    b.classList.toggle('is-on', b.dataset.colorKey === colorEditKey);
  });
}

function openColorSheet() {
  colorEditKey = 'ink';
  renderColorSheet();
  syncColorSheet(true);
  $('sheet-color').hidden = false;
}

function closeColorSheet() {
  $('sheet-color').hidden = true;
  renderDrawer();               // 抽屉里的配色入口跟着刷新
}

/* ══════════ 在线更新 ══════════
   界面与逻辑全在 assets/www 的三个文件里，所以只要能联网，
   点一下就能从 GitHub 拉新版热替换，不必重新装 APK。
   改权限、图标这类原生部分仍然只能装新 APK。
   远程版本文件格式见 README 的「在线更新」一节。 */
const APP_VERSION = 4;                 // APK 内置版本，与远程 version.json 对齐
const OTA_DEFAULT_URL = 'https://raw.githubusercontent.com/214263749/caipuben-update/main/version.json';
const K_OTA = 'pkg';
const K_OTA_URL = 'url';

let otaUrl = OTA_DEFAULT_URL;
let otaState = { version: 0, note: '', html: '', pending: false, appliedOnce: false, ok: false };
let otaVersions = [];     // 「检查更新」后拿到的版本列表（只存本次会话）

async function otaLoad() {
  const s = await OtaStore.read(K_OTA);
  if (s && s.html) otaState = s;
  const u = await OtaStore.read(K_OTA_URL);
  if (u) otaUrl = String(u);
  return otaState;
}
async function otaSave() { await OtaStore.write(K_OTA, otaState); }
const otaCurVersion = () => Math.max(APP_VERSION, Number(otaState.version) || 0);

/* 把三个文件拼成一个自包含 HTML：样式内联、脚本内联 */
function buildSelfHtml(f) {
  const safe = s => String(s || '').replace(/<\/script/gi, '<\\/script');
  let html = String(f.html || '');

  html = html.replace(/<link[^>]*href=["']css\/app\.css["'][^>]*>/i,
    '<style>\n' + String(f.css || '') + '\n</style>');

  /* 两个脚本合并成一个内联脚本，并包进 IIFE。
     热替换是在同一个页面上下文里重写文档，旧页面顶层的 const 还留在
     全局词法作用域中，新页面再声明同名 const 会直接抛
     「Identifier has already been declared」，更新就永远起不来。
     包进函数作用域后，内部的声明会正常遮蔽掉外层，互不干扰。 */
  const merged = '<script>\n(function(){\n' + safe(f.db) + '\n' + safe(f.js) + '\n})();\n<\/script>';
  html = html.replace(/<script[^>]*src=["']js\/db\.js["'][^>]*><\/script>/i, merged);
  html = html.replace(/<script[^>]*src=["']js\/app\.js["'][^>]*><\/script>/i, '');

  return html;
}

function applyUpdateHtml(html) {
  document.open();
  document.write(html);
  document.close();
}

async function fetchJson(url) {
  const res = await fetch(url + (url.includes('?') ? '&' : '?') + 't=' + Date.now(), { cache: 'no-store' });
  if (!res.ok) throw new Error('HTTP ' + res.status);
  return await res.json();
}

/* 把远程 version.json 整理成统一的版本列表。
   兼容旧格式（单个 version/app.json）和新格式（versions 数组）；
   相对路径的包地址按版本文件所在目录解析。 */
function normalizeVersions(man, src) {
  const base = src.replace(/[^\/]*$/, '');
  const fixUrl = v => {
    if (v.url) return /^https?:\/\//.test(v.url) ? v.url : base + v.url;
    return base + (v.file || ('v' + v.version + '.json'));
  };
  let list = [];
  if (Array.isArray(man.versions) && man.versions.length) {
    list = man.versions;
  } else if (man.version) {
    list = [{ version: man.version, note: man.note, date: man.date, url: man.url, file: 'app.json' }];
  }
  return list
    .map(v => ({
      version: Number(v.version) || 0,
      note: String(v.note || ''),
      date: String(v.date || ''),
      url: fixUrl(v)
    }))
    .filter(v => v.version > 0)
    .sort((a, b) => b.version - a.version);
}

async function downloadVersion(entry) {
  try {
    toast(`正在下载 v${entry.version}…`);
    const files = await fetchJson(entry.url);
    if (!files || !files.html || !files.css || !files.js) throw new Error('更新包缺文件');
    const html = buildSelfHtml(files);
    if (html.length < 3000) throw new Error('更新包内容异常');

    otaState = { version: entry.version, note: entry.note || '', html, pending: true, appliedOnce: false, ok: false, at: Date.now() };
    await otaSave();
    applyUpdateHtml(html);          // 立即生效
  } catch (err) {
    toast('下载失败：' + ((err && err.message) || '网络不通'));
  }
}

async function checkUpdate() {
  if (!otaUrl) { toast('先在下面填版本文件地址'); return; }
  toast('正在检查…');
  try {
    const man = await fetchJson(otaUrl);

    /* 远程把 disabled 改成 true，就能一键停用热更新并回到出厂版 */
    if (man && man.disabled) {
      await OtaStore.remove(K_OTA);
      otaState = { version: 0, note: '', html: '', pending: false, appliedOnce: false, ok: false };
      otaVersions = [];
      renderDrawer();
      toast('热更新已停用，下次启动回到出厂版本');
      return;
    }

    otaVersions = normalizeVersions(man || {}, otaUrl);
    if (!otaVersions.length) throw new Error('版本文件里没有版本号');
    renderDrawer();

    const latest = otaVersions[0];
    if (latest.version > otaCurVersion()) toast(`发现新版本 v${latest.version}，点下方对应版本即可更新`);
    else toast('已经是最新版，下面是可选的历史版本');
  } catch (err) {
    toast('更新失败：' + ((err && err.message) || '网络不通'));
  }
}

function otaSectionHtml() {
  const cur = otaCurVersion();
  const list = otaVersions.length ? `
      <div class="ota-list">
        ${otaVersions.map((v, i) => {
          const isCur = v.version === cur;
          return `
          <div class="ota-row">
            <div class="ota-info">
              <span class="ota-v">v${v.version}${isCur ? ' · 当前' : ''}${i === 0 && !isCur ? ' · 最新' : ''}</span>
              ${v.note ? `<span class="ota-note">${esc(v.note)}</span>` : ''}
              ${v.date ? `<span class="ota-date">${esc(v.date)}</span>` : ''}
            </div>
            <button class="ota-dl" data-ota-dl="${i}" ${isCur ? 'disabled' : ''}>${isCur ? '使用中' : (v.version > cur ? '更新' : '回退')}</button>
          </div>`;
        }).join('')}
      </div>` : '';

  return `
    <div class="drawer-sec">
      <div class="drawer-sec-h">在线更新<span class="drawer-sec-tip">手动检查，不自动联网</span></div>
      <p class="ota-ver">当前版本 v${cur}${otaState.note ? ' · ' + esc(otaState.note) : '（出厂版本）'}</p>
      <div class="ota-url">
        <input id="ota-url" type="url" spellcheck="false" autocomplete="off"
               placeholder="粘贴 version.json 直链" value="${esc(otaUrl)}">
        <button class="ota-save-url" data-act="save-ota-url">保存</button>
      </div>
      <button class="drawer-item" data-act="check-update"><span>检查更新</span><small>拉取版本列表，可任选版本更新或回退</small></button>
      ${list}
      <button class="drawer-item is-danger" data-act="reset-ota"><span>恢复出厂版本</span><small>删掉在线更新，菜谱不受影响</small></button>
    </div>`;
}

function homeDrawerHtml() {
  const parts = CATEGORIES.map(c => `${c.name} ${state.recipes.filter(r => r.type === c.id).length}`);
  const fav = state.recipes.filter(r => r.favorite).length;
  return `
    <h2 class="drawer-title">备份与设置</h2>
