}

function timerDrawerHtml() {
  const chips = [1, 2, 3, 5, 10].map(m =>
    `<button class="drawer-chip ${m === timerStepMin ? 'is-on' : ''}" data-step="${m}">${m} 分钟</button>`
  ).join('');

  const rmIcon = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg>';
  const rows = timerPresets.length
    ? timerPresets.map((sec, i) => `
        <div class="drawer-preset-row">
