    <div class="drawer-sec">
      <div class="drawer-sec-h">提醒方式<span class="drawer-sec-tip">亮色为启用，灰色为关闭</span></div>
      <div class="drawer-chips">
        ${sw('vibrate', '震动', ringVibrate)}
        ${sw('sound', '响铃', ringSound)}
      </div>
    </div>
