      <div class="drawer-sec-h">加减按钮步长</div>
      <div class="drawer-chips">${chips}</div>
    </div>
    <div class="drawer-sec">
      <div class="drawer-sec-h">预设时间（最多 3 个）</div>
      ${rows}
