async function clearAllRecipes() {
  if (!state.recipes.length) { toast('本来就没有菜谱'); return; }
  const ok = await confirmDialog({
    title: '清空全部菜谱？',
    text: `${state.recipes.length} 道菜谱将被永久删除，无法恢复。建议先导出备份。`,
    ok: '全部删除',
    danger: true
  });
  if (!ok) return;
  await Store.clear();
  state.recipes = [];
  closeDrawer();
  renderHome(false);
  toast('已清空');
}

/* ── 步骤进度 ──
   点第 N 步：记成「做到第 N 步」，1~N 的序号连同这些步骤里的时间按钮一起转蓝。
   再点一次已经转蓝的第 N 步：取消它和它之后的全部步骤，退回第 N-1 步。
   进度存在菜谱里，下次打开还在。 */
async function toggleStepDone(n) {
  const r = state.recipes.find(x => x.id === state.detailId);
  if (!r || !n) return;
  const cur = Number(r.doneStep) || 0;
  r.doneStep = n > cur ? n : Math.max(0, n - 1);
  await Store.put(r);
  renderDetail();
}

/* 从步骤里的时间按钮跳计时器：带上步骤号，读数下方和通知栏都能看到。
   已经在跑的计时不能直接顶掉，先问一句。 */
async function openTimerForStep(sec, stepNo) {
  if (timer.running) {
    const ok = await confirmDialog({
      title: '正在计时中',
      text: '要取消当前计时，换成这一次的时间吗？',
      ok: '取消并开始新的',
      danger: true
    });
    if (!ok) return;                     // 选了就不要动当前计时
    openTimer(sec, stepNo);
    startTimer();                        // 确认之后直接开跑，不用再点一次开始
  } else {
    openTimer(sec, stepNo);              // 没在计时就照旧：填好时长，等你点开始
  }
  if (timer.stepNo) toast(`第 ${timer.stepNo} 步`);
}

/* 拉起米家 App。
   网页只能做到这一步：扔一个 intent:// 让系统解析，能不能起来取决于装没装米家。
   没法自动把温度时间设好——米家没开放给三方这种入口（详见更新说明）。 */
function openMihome() {
  const uri = 'intent://home#Intent' +
    ';scheme=mihome' +
    ';package=com.xiaomi.smarthome' +
    ';S.browser_fallback_url=' + encodeURIComponent('https://home.mi.com') +
    ';end';
  let went = false;
  const mark = () => { went = true; };
  document.addEventListener('visibilitychange', mark, { once: true });
  try { window.location.href = uri; } catch { /* 系统不认这个协议就算了 */ }
  setTimeout(() => {
    document.removeEventListener('visibilitychange', mark);
    /* 页面还亮着，说明没拉起来 */
    if (!went && document.visibilityState === 'visible') {
      toast('没能打开米家，确认装了米家 App');
    }
  }, 1200);
}

/* 步骤全部点亮后的「完成」：先累加次数，再打开记一篇 */
async function confirmFinishRecipe() {
  const r = state.recipes.find(x => x.id === state.detailId);
  if (!r) return;
  const ok = await confirmDialog({
    title: '完成这道菜？',
    text: '会记下这是第几次完成，接着可以写一篇日记。',
    ok: '完成'
  });
  if (!ok) return;
  r.doneCount = (Number(r.doneCount) || 0) + 1;
  await Store.put(r);
  renderDetail();
  /* 都在记这一次的成果了，计时器还在响就说不过去——顺手收掉，
     不然提醒声会一直响在记日记页面的背后 */
  if (timer.ringing) finishRing();
  openDiaryNew(r.id, r.doneCount);
}

/* 「重置」只清步骤进度，完成次数留着 */
async function confirmResetSteps() {
  const r = state.recipes.find(x => x.id === state.detailId);
  if (!r) return;
  const ok = await confirmDialog({
    title: '重置步骤进度？',
    text: '所有序号和时间按钮都会恢复默认颜色，已经记录的完成次数不受影响。',
    ok: '重置',
    danger: true
  });
  if (!ok) return;
  r.doneStep = 0;
  await Store.put(r);
  renderDetail();
  toast('已重置步骤进度');
}

/* ══════════ 美食日记 ══════════
   两层：先是按菜谱归拢的近似正方形卡片，点开才是这道菜的日记，
   日记本身也是同样的正方形卡片。完成次数记在菜谱上，日记本体另存。 */
const DIARY_RATES = { good: '好！', ok: '一般', bad: '失败' };

async function loadDiaries() {
  state.diaries = await DiaryStore.all();
}

function diaryOf(recipeId) {
  return state.diaries
    .filter(d => d.recipeId === recipeId)
    .sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
}

/* 写过日记、或者至少记过完成次数的菜谱，都算有记录 */
function diaryRecipes() {
  const withEntry = new Set(state.diaries.map(d => d.recipeId));
  return state.recipes.filter(r => withEntry.has(r.id) || (Number(r.doneCount) || 0) > 0);
}

function diaryMatchFilter(r) {
  const f = state.diaryFilter;
  if (f === 'all') return true;
  if (f === 'fav') return !!r.favorite;
  return r.type === f;
}

function diaryMatchQuery(r) {
  const q = state.diaryQuery.trim().toLowerCase();
  if (!q) return true;
  if (String(r.name).toLowerCase().includes(q)) return true;
  return (r.tags || []).some(t => String(t).toLowerCase().includes(q));
}

function renderDiaryChips() {
  const all = diaryRecipes();
  const chip = (key, label, n, extra = '') =>
    `<button class="chip ${state.diaryFilter === key ? 'is-on' : ''} ${extra}" data-diary-filter="${key}">${esc(label)}<span class="chip-n">${n}</span></button>`;
  const parts = [chip('all', '全部', all.length)];
  CATEGORIES.forEach(c => parts.push(chip(c.id, c.name, all.filter(r => r.type === c.id).length)));
  parts.push(chip('fav', '红心', all.filter(r => r.favorite).length, 'is-fav'));
  diaryChipBar.innerHTML = parts.join('');
}

/* 卡面上的图：优先用最近一篇带照片的日记 */
function diaryCover(list) {
  const hit = list.find(d => d.photo);
  return hit ? hit.photo : '';
}

function renderDiary() {
  renderDiaryChips();
  const inList = !!state.diaryRecipeId;

  /* 二级（某道菜的日记）时收起搜索栏和分类，顶部换成返回 + 菜名 */
  diaryBack.hidden = !inList;
  diarySearch.closest('.search').hidden = inList;
  diaryChipBar.hidden = inList;

  if (!inList) {
    const list = diaryRecipes().filter(diaryMatchFilter).filter(diaryMatchQuery);
    diaryTitle.textContent = '美食日记';
    diaryCount.textContent = list.length
      ? `${list.length} 道有记录`
      : '还没有记录';

    diaryGrid.innerHTML = list.map(r => {
      const entries = diaryOf(r.id);
      const cover = diaryCover(entries);
      const times = Number(r.doneCount) || 0;
      return `
        <button class="diary-card" data-diary-recipe="${esc(r.id)}">
          <span class="diary-thumb">${cover
            ? `<img src="${cover}" alt="">`
            : '<span class="diary-thumb-none">还没有照片</span>'}</span>
          <span class="diary-name">${esc(r.name)}</span>
          <span class="diary-meta">${entries.length} 篇 · 做过 ${times} 次</span>
        </button>`;
    }).join('');

    diaryEmpty.hidden = list.length > 0;
    if (!list.length) {
      diaryEmpty.innerHTML = state.recipes.length
        ? '<div class="empty-desc">还没有完成记录。在菜谱里把步骤全部点亮，点「完成」就能记一笔。</div>'
        : '<div class="empty-desc">还没有菜谱，先去首页加一道。</div>';
    }
    return;
  }

  const r = state.recipes.find(x => x.id === state.diaryRecipeId);
  const entries = diaryOf(state.diaryRecipeId);
  diaryTitle.textContent = r ? r.name : '日记';
  diaryCount.textContent = `${entries.length} 篇 · 做过 ${Number(r && r.doneCount) || 0} 次`;

  diaryGrid.innerHTML = entries.map(d => `
    <div class="diary-card">
      <span class="diary-thumb">${d.photo
        ? `<img src="${d.photo}" alt="">`
        : '<span class="diary-thumb-none">没有照片</span>'}</span>
      ${d.text ? `<span class="diary-note">${esc(d.text)}</span>` : ''}
      <span class="diary-meta">第 ${d.times || 1} 次 · ${fmtDate(d.createdAt)}</span>
      ${d.rate ? `<span class="diary-rate ${esc(d.rate)}">${DIARY_RATES[d.rate] || ''}</span>` : ''}
    </div>`).join('');

  diaryEmpty.hidden = entries.length > 0;
  if (!entries.length) {
    diaryEmpty.innerHTML = '<div class="empty-desc">这道菜只记了完成次数，还没有写过日记。</div>';
  }
}

function openDiary() {
  state.diaryRecipeId = null;
  renderDiary();
  diaryView.classList.add('is-open');
  pushLayer();
  updateChrome();
}

function closeDiary() {
  if (state.diaryRecipeId) {         // 先退回上一层，不直接关整页
    state.diaryRecipeId = null;
    renderDiary();
    return;
  }
  diaryView.classList.remove('is-open');
  updateChrome();
}

/* ══════════ 记一篇日记 ══════════ */
function openDiaryNew(recipeId, times) {
  const r = state.recipes.find(x => x.id === recipeId);
  state.diaryDraft = { recipeId, times, photo: '', rate: '' };
