/* 相册选完先压一压：原图动辄好几兆，存进库里太占地方 */
function compressImage(file, maxSide = 760, quality = 0.72) {
  return new Promise(resolve => {
    const fr = new FileReader();
    fr.onerror = () => resolve(null);
    fr.onload = () => {
      const img = new Image();
      img.onerror = () => resolve(null);
      img.onload = () => {
        try {
          const scale = Math.min(1, maxSide / Math.max(img.width, img.height));
          const w = Math.max(1, Math.round(img.width * scale));
          const h = Math.max(1, Math.round(img.height * scale));
          const cv = document.createElement('canvas');
          cv.width = w; cv.height = h;
          cv.getContext('2d').drawImage(img, 0, 0, w, h);
          resolve(cv.toDataURL('image/jpeg', quality));
        } catch { resolve(null); }
      };
      img.src = fr.result;
    };
    fr.readAsDataURL(file);
  });
}

async function saveDiaryDraft() {
  const d = state.diaryDraft;
  if (!d) { closeDiaryNew(); return; }
  const text = ($('dn-text').value || '').trim();
  const r = state.recipes.find(x => x.id === d.recipeId);

  /* 只有写了字或配了图才生成卡片，否则就只是累计次数 */
  if (text || d.photo) {
    const entry = {
      id: uid(),
      recipeId: d.recipeId,
      recipeName: r ? r.name : '',
      text,
      photo: d.photo || '',
      rate: d.rate || '',
      times: d.times,
      createdAt: Date.now()
    };
    await DiaryStore.put(entry);
    state.diaries.push(entry);
    toast('日记已保存');
  } else {
    toast(`已记下第 ${d.times} 次完成`);
  }
  closeDiaryNew();
}

/* ── 详情 ── */
function renderDetail() {
  const r = state.recipes.find(x => x.id === state.detailId);
  if (!r) { closeDetail(); return; }

  const cat = catOf(r.type);
  const steps = (r.steps || []).filter(s => String(s).trim());
  const bakes = (r.bakes || []).filter(b => b.temp || b.time || b.label);
  detailDoneStep = Number(r.doneStep) || 0;

  detailCrumb.textContent = cat.name;

  const html = [];

  const y = r.yield && +r.yield.count > 0 ? r.yield : null;
  const scale = y ? (state.scale || +y.count) : 0;
  const factor = y ? scale / +y.count : 1;

  html.push(`
    <div class="detail-wrap">
      <div class="detail-head">
        <div class="detail-type">
          <span class="badge ${cat.badge}">${esc(cat.name)}</span>
        </div>
        <div class="detail-title-row">
          <button class="detail-fav ${r.favorite ? 'is-on' : ''}" data-fav="${esc(r.id)}" aria-label="红心" aria-pressed="${r.favorite ? 'true' : 'false'}">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linejoin="round">
              <path d="M12 20.3s-7.2-4.4-7.2-9.2a4.2 4.2 0 0 1 7.2-2.9 4.2 4.2 0 0 1 7.2 2.9c0 4.8-7.2 9.2-7.2 9.2z"/>
            </svg>
          </button>
          <h1 class="detail-title">${esc(r.name)}</h1>
          <button class="detail-pin ${state.pinnedId === r.id ? 'is-on' : ''}" data-pin="${esc(r.id)}"
                  aria-label="固定到计时器" aria-pressed="${state.pinnedId === r.id ? 'true' : 'false'}">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.85" stroke-linecap="round" stroke-linejoin="round">
              <path d="M9 4h6l-.7 5.2 3.2 3.1H6.5l3.2-3.1z"/>
              <path d="M12 12.3V20"/>
            </svg>
          </button>
        </div>
        ${(r.tags || []).length ? `<div class="detail-tags">${r.tags.map(t => `<span class="tag-pill">${esc(t)}</span>`).join('')}</div>` : ''}
      </div>`);

  // 材料（家常菜分主料 / 辅料；旧数据无 group 一律视为主料）
  const allIngs = r.ingredients || [];
  const mainIngs = allIngs.filter(it => (it.group || 'main') === 'main');
  const auxIngs = allIngs.filter(it => it.group === 'aux');

  /* 材料用量：保持普通文本样式（点按仍可查看单位换算） */
  const amtHtml = (it, factor) => {
    const amt = scaleAmount(it.amount, factor);
    if (!amt) return '';
    const p = splitAmount(amt);
    const conv = evalNum(p.num) != null && CONV_UNITS.includes(p.unit);
    return conv
      ? `<button class="ing-amt" data-conv-ing="${esc(it.name)}" data-conv-amt="${esc(amt)}" aria-label="查看单位换算">${esc(amt)}</button>`
      : `<span class="ing-amt">${esc(amt)}</span>`;
  };

  const ingBlock = (list, title) => `
      <div class="block">
        <div class="block-head">
          <span class="block-title">${title}</span>
          <span class="block-count">${list.length} 项</span>
        </div>
        <div class="ing-card">
          ${list.map(it => `
            <div class="ing-row">
              <span class="ing-name">${esc(it.name)}</span>
              ${amtHtml(it, factor)}
            </div>`).join('')}
        </div>
      </div>`;

  /* 份量换算条：放在主料前。
     「还原」排在减号左侧，这样它出现/消失时加减号不会左右移位。 */
  if (y) {
    html.push(`
      <div class="scale-bar${scale !== +y.count ? ' is-scaled' : ''}">
        <span class="scale-label">份量</span>
        <div class="scale-ctrl">
          ${scale !== +y.count ? `<button class="scale-reset" data-scale="0">还原</button>` : ''}
          <button class="scale-btn" data-scale="-1" aria-label="减少">−</button>
          <span class="scale-num">${scale}</span>
          <button class="scale-btn" data-scale="1" aria-label="增加">＋</button>
        </div>
        <span class="scale-unit">${esc(y.label || '个')}</span>
      </div>`);
  }

  if (mainIngs.length) html.push(ingBlock(mainIngs, '主料'));
  if (auxIngs.length) html.push(ingBlock(auxIngs, '辅料'));
  if (!mainIngs.length && !auxIngs.length) {
    html.push(`
      <div class="block">
        <div class="bake-note">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
            <circle cx="12" cy="12" r="8.5"/><path d="M12 8v4.4"/><path d="M12 16h.01"/>
          </svg>
          <span>还没有填写材料。</span>
        </div>
      </div>`);
  }

  // 温度与时间
  if (cat.hasBake && bakes.length) {
    html.push(`
      <div class="block">
        <div class="block-head">
          <span class="block-title">温度与时间</span>
          ${bakes.length > 1 ? `<span class="block-count">${bakes.length} 段</span>` : ''}
          <button class="block-act" data-act="open-mihome">去米家</button>
        </div>
        <div class="bake-card">
          ${bakes.map((b, i) => {
            const t = splitFigure(b.temp, '°C');
            const tm = splitFigure(b.time, '分钟');
            return `
              <div class="bake-row">
                <span class="bake-stage">${bakes.length > 1 ? i + 1 : ''}</span>
                <div class="bake-figures">
                  ${t ? `<span class="bake-temp">${esc(t.num)}<span class="u">${esc(t.unit)}</span></span>` : ''}
                  ${tm ? `<span class="bake-time">${esc(tm.num)}<span class="u">${esc(tm.unit)}</span></span>` : ''}
                </div>
                ${b.label ? `<span class="bake-label">${esc(b.label)}</span>` : ''}
              </div>`;
          }).join('')}
        </div>
      </div>`);
  } else if (cat.hasBake) {
    html.push(`
      <div class="block">
        <div class="bake-note is-action" data-edit-note="1">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
            <path d="M12 3.5v3M12 17.5v3M4.2 12h3M16.8 12h3M6.5 6.5l2.1 2.1M15.4 15.4l2.1 2.1M17.5 6.5l-2.1 2.1M8.6 15.4l-2.1 2.1"/>
          </svg>
          <span>这份菜谱还没有温度和时间，点这里补充（原截图可能只拍了材料部分）。</span>
        </div>
      </div>`);
  }

  // 操作步骤
  if (steps.length) {
    html.push(`
      <div class="block">
        <div class="block-head">
          <span class="block-title">操作</span>
          <span class="block-count">${steps.length} 步</span>
        </div>
        <div>
          ${steps.map((s, i) => `
            <div class="step">
              <button class="step-num${(i + 1) <= detailDoneStep ? ' is-done' : ''}" data-step-no="${i + 1}" aria-label="标记完成到第 ${i + 1} 步">${i + 1}</button>
              <div class="step-text">${linkifyTime(s, i + 1)}</div>
            </div>`).join('')}
        </div>
        ${(steps.length && detailDoneStep === steps.length) ? `
          <div class="step-finish">
            <button class="sf-done" data-act="finish-recipe">完成</button>
            <button data-act="reset-steps">重置</button>
          </div>` : ''}
      </div>`);
  } else if (cat.hasBake) {
    html.push(`
      <div class="block">
        <div class="bake-note">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
            <circle cx="12" cy="12" r="8.5"/><path d="M12 8v4.4"/><path d="M12 16h.01"/>
          </svg>
          <span>无需额外操作：预热后直接放入烘烤即可。</span>
        </div>
      </div>`);
  } else {
    html.push(`
      <div class="block">
        <div class="bake-note">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
            <circle cx="12" cy="12" r="8.5"/><path d="M12 8v4.4"/><path d="M12 16h.01"/>
          </svg>
          <span>还没有填写操作步骤。</span>
        </div>
      </div>`);
  }

  html.push(`
      <div class="detail-foot">
        <button class="danger-text" data-del-recipe>删除这道菜</button>
        <div class="foot-meta">更新于 ${fmtDate(r.updatedAt)}</div>
      </div>
    </div>`);

  detailBody.innerHTML = html.join('');
  detailBody.scrollTop = 0;
}

/* fromTop：从计时器页下拉拉出来时走「从上往下移动出现」，
   其余入口维持原来从右侧滑入的观感 */
function openDetail(id, fromTop = false) {
  ingSuggestReset();
  state.detailId = id;
  const r = state.recipes.find(x => x.id === id);
  state.scale = r && r.yield && +r.yield.count > 0 ? +r.yield.count : 0;
  renderDetail();
  if (fromTop) {
    detailView.classList.add('is-drop');
    void detailView.offsetHeight;      // 强制重排，否则两个 class 同一帧加上去不会有过渡
  }
  detailView.classList.add('is-open');
  pushLayer();
  updateChrome();
}

function closeDetail() {
  ingSuggestReset();
  detailView.classList.remove('is-open');
  /* 留着 is-drop 让它向上收回去，动画走完再摘掉 */
  setTimeout(() => detailView.classList.remove('is-drop'), 340);
  detailBody.scrollTop = 0;
  updateChrome();
}

/* ── 编辑器 ── */
function blankDraft(type = 'stir') {
  return {
    id: uid(),
    type,
    name: '',
    tags: [],
    ingredients: type === 'bake'
      ? [{ name: '', amount: '', group: 'main' }]
      : [
          { name: '', amount: '', group: 'main' },
          { name: '', amount: '', group: 'aux' }
        ],
    steps: [],
    bakes: type === 'bake' ? [{ label: '', temp: '', time: '' }] : [],
    favorite: false,
    createdAt: Date.now(),
    updatedAt: Date.now()
  };
}

function renderTypeSeg() {
  /* 编辑页里烘焙在左、家常菜在右（首页 Dock 顺序不受影响） */
  typeSeg.innerHTML = CATEGORIES.slice().reverse().map(c => `
    <button class="seg-btn ${state.draft.type === c.id ? 'is-on' : ''}" data-type="${c.id}">
      ${c.icon}${esc(c.name)}
    </button>`).join('');
}

function renderTags() {
  const tags = state.draft.tags || [];
  tagList.innerHTML = tags.map((t, i) => `
    <span class="tag-chip">${esc(t)}
      <button data-rmtag="${i}" aria-label="移除标签">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg>
      </button>
    </span>`).join('');
  renderSuggest();
}

function allTags() {
  const set = new Map();
  state.recipes.forEach(r => (r.tags || []).forEach(t => {
    const k = String(t).toLowerCase();
    set.set(k, (set.get(k) || 0) + 1);
  }));
  return [...set.entries()].sort((a, b) => b[1] - a[1]).map(e => e[0]);
}

function renderSuggest() {
  const chosen = new Set((state.draft.tags || []).map(t => t.toLowerCase()));
  const pool = allTags().filter(t => !chosen.has(t)).slice(0, 8);
  if (!pool.length) { tagSuggest.innerHTML = ''; return; }
  tagSuggest.innerHTML = pool.map(t => `<button class="sug-chip" data-sug="${esc(t)}">${esc(t)}</button>`).join('');
}

/* ── 材料联想：把保存过的材料名记下来，填写时提示 ── */
function allIngNames() {
  const counts = new Map();
  state.recipes.forEach(r => (r.ingredients || []).forEach(it => {
    const n = String(it?.name || '').trim();
    if (!n) return;
    counts.set(n, (counts.get(n) || 0) + 1);
  }));
  return [...counts.entries()].sort((a, b) => b[1] - a[1]).map(e => e[0]);
}

const ingSuggest = $('ing-suggest');
let ingSuggestTarget = null;
let ingSuggestHideTimer = null;

function hideIngSuggest() {
  clearTimeout(ingSuggestHideTimer);
  ingSuggestTarget = null;
  ingSuggest.hidden = true;
}

function showIngSuggest(input) {
  clearTimeout(ingSuggestHideTimer);   // 别让上一次延迟隐藏吃掉新浮层
  const pool = allIngNames();
  if (!pool.length) { hideIngSuggest(); return; }
  const q = input.value.trim().toLowerCase();
  const hits = (q
    ? pool.filter(n => n.toLowerCase().includes(q) && n.toLowerCase() !== q)
    : pool
  ).slice(0, 6);
  if (!hits.length) { hideIngSuggest(); return; }
  ingSuggestTarget = input;
  ingSuggest.innerHTML = hits.map(n => `<button type="button" data-sug-ing="${esc(n)}">${esc(n)}</button>`).join('');
  const rect = input.getBoundingClientRect();
  ingSuggest.style.left = rect.left + 'px';
  ingSuggest.style.top = (rect.bottom + 5) + 'px';
  ingSuggest.style.minWidth = Math.max(rect.width, 120) + 'px';
  ingSuggest.hidden = false;
}

/* 视图切换 / 列表重绘后，输入框已不在原位，一律收起浮层 */
function ingSuggestReset() {
  if (!ingSuggest.hidden) hideIngSuggest();
}

function renderIngs() {
  ingSuggestReset();   // 列表重建后旧输入框已失效，浮层位置不再可靠
  const d = state.draft;
  const isStir = !catOf(d.type).hasBake;

  // 家常菜分主料 / 辅料；烘焙只有一个材料列表，但仍保留「添加」按钮
  ingMainHead.style.display = '';
  ingMainTitle.hidden = !isStir;
  ingMainHint.hidden = isStir;
  ingAuxWrap.style.display = isStir ? '' : 'none';

  const row = (it, i, group) => {
    const { num, unit } = splitAmount(it.amount);
    return `
    <div class="row-ing">
      <button class="drag-handle" data-drag-handle aria-label="按住拖动调整顺序">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M9 9h6M9 15h6"/></svg>
      </button>
      <input class="row-input" data-ing="name" value="${esc(it.name)}" placeholder="${group === 'aux' ? '辅料，如 葱花' : '材料，如 鸡蛋'}" autocomplete="off">
      <input class="row-input amt" data-ing="amount" inputmode="decimal" value="${esc(num)}" placeholder="用量" autocomplete="off">
      ${ingUnitSel(unit)}
      <button class="row-del" data-del-ing="${i}" data-del-group="${group}" aria-label="删除">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg>
      </button>
    </div>`;
  };

  const all = d.ingredients || [];
  const main = all.filter(x => (x.group || 'main') === 'main');
  const aux = all.filter(x => x.group === 'aux');

  ingMainList.innerHTML = main.map((it, i) => row(it, i, 'main')).join('');
  ingAuxList.innerHTML = isStir ? aux.map((it, i) => row(it, i, 'aux')).join('') : '';

  // 始终有空行可填，占位提示不再显示
  ingEmpty.hidden = true;
}

/* ── 材料行拖拽排序（Pointer Events，兼容触屏） ── */
let ingDrag = null;
let suppressIngClick = false;

const nodeVisible = el => {
  for (let n = el; n && n.nodeType === 1; n = n.parentElement) {
    if (n.hidden || n.style.display === 'none') return false;
  }
  return true;
};

function ingDragDown(e) {
  if (!state.draft) return;
  const handle = e.target.closest('[data-drag-handle]');
  if (!handle) return;
  const row = handle.closest('.row-ing');
  const list = row && row.parentElement;
  if (!row || !list) return;
  if (e.button !== undefined && e.button > 0) return;
  e.preventDefault();
  ingDrag = {
    row,
    list,
    pid: e.pointerId,
    startX: e.clientX,
    startY: e.clientY,
    active: false
  };
  try { handle.setPointerCapture(e.pointerId); } catch {}
}

function ingDragActivate(s, e) {
  const rect = s.row.getBoundingClientRect();
  s.active = true;
  s.baseTop = rect.top;
  s.height = rect.height || 44;
  s.scroller = document.querySelector('#view-edit .scroll-body');
  s.scrollStart = s.scroller ? s.scroller.scrollTop : 0;

  // 占位块顶住原位置，被拖行脱流后仍保持列表高度
  const slot = document.createElement('div');
  slot.className = 'row-slot';
  slot.style.height = s.height + 'px';
  s.row.parentElement.insertBefore(slot, s.row);
  s.slot = slot;

  document.body.appendChild(s.row);
  s.row.classList.add('is-dragging');
  s.row.style.position = 'fixed';
  s.row.style.left = rect.left + 'px';
  s.row.style.top = rect.top + 'px';
  s.row.style.width = rect.width + 'px';
  s.row.style.margin = '0';
  s.row.style.zIndex = '70';
  s.row.style.pointerEvents = 'none';
  document.body.classList.add('is-dragging-ing');
  if (navigator.vibrate) { try { navigator.vibrate(8); } catch {} }
}

function ingDragMove(e) {
  const s = ingDrag;
  if (!s || e.pointerId !== s.pid) return;
  const dy = e.clientY - s.startY;
  if (!s.active) {
    if (Math.abs(dy) < 6 && Math.abs(e.clientX - s.startX) < 6) return;
    ingDragActivate(s, e);
  }
  e.preventDefault();

  const scroller = s.scroller;
  const scrollDelta = scroller ? scroller.scrollTop - s.scrollStart : 0;
  s.row.style.top = (s.baseTop + dy - scrollDelta) + 'px';

  // 拖到边缘时自动滚动
  if (scroller) {
    const sr = scroller.getBoundingClientRect();
    if (e.clientY < sr.top + 70) scroller.scrollTop -= 10;
    else if (e.clientY > sr.bottom - 70) scroller.scrollTop += 10;
  }

  // 命中哪个分组（辅料用整组包裹层做热区，空组也能放进去）
  const zones = [
    { list: ingMainList, zone: ingMainList },
    { list: ingAuxList, zone: ingAuxWrap }
  ].filter(z => nodeVisible(z.list));
  if (!zones.length) return;

  const center = s.baseTop + dy - scrollDelta + s.height / 2;
  let target = null;
  let best = Infinity;
  zones.forEach(z => {
    const r = z.zone.getBoundingClientRect();
    const d = center < r.top ? r.top - center : center > r.bottom ? center - r.bottom : 0;
    if (d < best) { best = d; target = z; }
  });
  if (!target) return;

  const rows = [...target.list.querySelectorAll('.row-ing')];
  let before = null;
  for (const r of rows) {
    const rr = r.getBoundingClientRect();
    if (center < rr.top + rr.height / 2) { before = r; break; }
  }
  if (before) target.list.insertBefore(s.slot, before);
  else target.list.appendChild(s.slot);
}

function ingDragEnd() {
  const s = ingDrag;
  if (!s) return;
  ingDrag = null;
  document.body.classList.remove('is-dragging-ing');
  if (!s.active) return;
  // 拖拽结束时浏览器可能补发一次 click，吞掉它，但 160ms 后自动失效，避免误伤后续点击
  suppressIngClick = true;
  setTimeout(() => { suppressIngClick = false; }, 160);

  s.row.classList.remove('is-dragging');
  s.row.removeAttribute('style');
  if (s.slot && s.slot.parentElement) s.slot.replaceWith(s.row);

  // DOM 顺序即新顺序，syncFromDOM 同时会按所在容器重新归组
  syncFromDOM();
  renderIngs();
}

function renderBakes() {
  const list = state.draft.bakes || [];
  const isBake = catOf(state.draft.type).hasBake;
  bakeSection.style.display = isBake ? '' : 'none';
  if (!isBake) return;

  bakeList.innerHTML = list.map((b, i) => {
    const t = splitAmount(b.temp);
    const tm = splitAmount(b.time);
    return `
    <div class="row-bake">
      <input class="row-input r-lab" data-bake="label" data-idx="${i}" value="${esc(b.label)}" placeholder="阶段（可选），如 预热 / 上色" autocomplete="off">
      <div class="bake-line">
        <input class="row-input r-temp" data-bake="temp" data-idx="${i}" inputmode="decimal" value="${esc(t.num)}" placeholder="温度" autocomplete="off">
        ${bakeUnitSel('tunit', TEMP_UNITS, t.unit)}
        <input class="row-input r-time" data-bake="time" data-idx="${i}" inputmode="decimal" value="${esc(tm.num)}" placeholder="时间" autocomplete="off">
        ${bakeUnitSel('tmunit', TIME_UNITS, tm.unit)}
      </div>
      <button class="row-del" data-del-bake="${i}" aria-label="删除">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg>
      </button>
    </div>`;
  }).join('');
}

function renderSteps() {
  const list = state.draft.steps || [];
  const isBake = catOf(state.draft.type).hasBake;

  stepOpt.hidden = !isBake;
  stepHint.textContent = isBake
    ? '若只需预热后放入，这里留空即可，详情页不会显示操作部分。'
    : '';

  stepList.innerHTML = list.map((s, i) => `
    <div class="row-step">
      <span class="step-idx">${i + 1}</span>
      <textarea data-step="${i}" placeholder="第 ${i + 1} 步做什么" rows="1">${esc(s)}</textarea>
      <button class="row-del" data-del-step="${i}" aria-label="删除">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg>
      </button>
    </div>`).join('');

  // 有内容时按内容撑开高度
  requestAnimationFrame(() => {
    stepList.querySelectorAll('textarea').forEach(ta => {
      ta.style.height = 'auto';
      ta.style.height = Math.max(56, ta.scrollHeight) + 'px';
    });
  });
}

function syncFromDOM() {
  if (!state.draft) return;
  const d = state.draft;

  d.name = fName.value;

  const yNum = parseFloat(fYieldNum.value);
  d.yield = yNum > 0 ? { count: yNum, label: fYieldUnit.value || '个' } : null;

  const read = container => [...container.querySelectorAll('.row-ing')].map(rowEl => ({
    name: rowEl.querySelector('[data-ing="name"]').value,
    amount: joinAmount(
      rowEl.querySelector('[data-ing="amount"]').value,
      rowEl.querySelector('[data-ing="unit"]').value
    )
  }));
  const isStir = !catOf(d.type).hasBake;
  // 烘焙时不显示辅料，但暂存已有辅料，切回家常菜还能恢复
  const keptAux = (d.ingredients || []).filter(x => x.group === 'aux');
  d.ingredients = [
    ...read(ingMainList).map(x => ({ ...x, group: 'main' })),
    ...(isStir ? read(ingAuxList).map(x => ({ ...x, group: 'aux' })) : keptAux)
  ];

  d.bakes = [...bakeList.querySelectorAll('.row-bake')].map(row => ({
    label: row.querySelector('[data-bake="label"]').value,
    temp: joinAmount(
      row.querySelector('[data-bake="temp"]').value,
      row.querySelector('[data-bake="tunit"]').value
    ),
    time: joinAmount(
      row.querySelector('[data-bake="time"]').value,
      row.querySelector('[data-bake="tmunit"]').value
    )
  }));

  d.steps = [...stepList.querySelectorAll('textarea')].map(t => t.value);
}

function renderEditor() {
  const d = state.draft;
  const isEdit = !!d.__isEdit;

  editCrumb.textContent = isEdit ? '编辑菜谱' : '新建菜谱';
  editDelete.hidden = !isEdit;

  fName.value = d.name || '';
  fYieldNum.value = d.yield && d.yield.count ? d.yield.count : '';
  if (!fYieldUnit.options.length) {
    fYieldUnit.innerHTML = YIELD_UNITS.map(u => `<option value="${esc(u)}">${esc(u)}</option>`).join('');
  }
  fYieldUnit.value = YIELD_UNITS.includes(d.yield?.label) ? d.yield.label : '个';
  renderTypeSeg();
  renderTags();
  renderIngs();
  renderBakes();
  renderSteps();
}

function openEditor(id) {
  const existing = id ? state.recipes.find(r => r.id === id) : null;
  if (existing) {
    state.draft = JSON.parse(JSON.stringify(existing));
    state.draft.__isEdit = true;
    state.editFrom = 'detail';
  } else {
    state.draft = blankDraft('bake');
    state.draft.__isEdit = false;
    state.editFrom = 'home';
  }
  renderEditor();
  editView.classList.add('is-open');
  document.querySelector('#view-edit .scroll-body').scrollTop = 0;
  pushLayer();
  updateChrome();
}

function closeEditor() {
  ingSuggestReset();
  editView.classList.remove('is-open');
  state.draft = null;
  updateChrome();
}

async function saveDraft() {
  syncFromDOM();
  const d = state.draft;
  if (!d) return;

  const name = (d.name || '').trim();
  if (!name) {
    toast('先给菜谱起个名字');
    fName.focus();
    return;
  }

  const cat = catOf(d.type);
  const record = {
    id: d.id,
    type: d.type,
    name,
    yield: d.yield && +d.yield.count > 0 ? { count: +d.yield.count, label: String(d.yield.label || '个') } : null,
    tags: (d.tags || []).map(t => String(t).trim()).filter(Boolean),
    order: typeof d.order === 'number' ? d.order : nextOrder(),
    ingredients: (d.ingredients || [])
      .filter(it => !cat.hasBake || it.group !== 'aux')
      .map(it => ({
        name: String(it.name || '').trim(),
        amount: String(it.amount || '').trim(),
        group: it.group === 'aux' ? 'aux' : 'main'
      }))
      .filter(it => it.name),
    steps: (d.steps || []).map(s => String(s).trim()).filter(Boolean),
    bakes: cat.hasBake
      ? (d.bakes || [])
          .map(b => ({
            label: String(b.label || '').trim(),
            temp: String(b.temp || '').trim(),
            time: String(b.time || '').trim()
          }))
          .filter(b => b.temp || b.time || b.label)
      : [],
    favorite: !!d.favorite,
    doneStep: Number(d.doneStep) || 0,
    createdAt: d.createdAt || Date.now(),
    updatedAt: Date.now()
  };

  await Store.put(record);

  const i = state.recipes.findIndex(r => r.id === record.id);
  if (i >= 0) state.recipes[i] = record; else state.recipes.push(record);

  const wasEdit = d.__isEdit;
  closeEditor();
  backHistory();
  renderHome(false);

  const detailOpen = detailView.classList.contains('is-open');
  if (detailOpen) {
    state.detailId = record.id;
    renderDetail();
  } else {
    openDetail(record.id);
  }
  toast(wasEdit ? '已保存' : '已添加');
}

/* ── 删除 ── */
async function deleteRecipe(id) {
  const r = state.recipes.find(x => x.id === id);
  if (!r) return;
  const ok = await confirmDialog({
    title: '删除这道菜？',
    text: `「${r.name}」将被永久删除，无法恢复。`,
    ok: '删除',
    danger: true
  });
  if (!ok) return;

  await Store.remove(id);
  state.recipes = state.recipes.filter(x => x.id !== id);

  /* 固定的正好是这道菜，就一并解除 */
  if (state.pinnedId === id) {
    state.pinnedId = null;
    lsSet(LS_PIN, '');
  }

  /* 菜谱没了，它的日记也没意义了，一并清掉免得留下读不到的孤儿数据 */
  const orphan = state.diaries.filter(d => d.recipeId === id);
  if (orphan.length) {
    await Promise.all(orphan.map(d => DiaryStore.remove(d.id)));
    state.diaries = state.diaries.filter(d => d.recipeId !== id);
  }

  closeEditor();
  closeDetail();
  backHistory();
  renderHome(false);
  toast('已删除');
}

/* ── 备份 ── */
function exportBackup() {
  if (!state.recipes.length) { toast('还没有菜谱可导出'); return; }
  const data = {
    app: 'recipe-book',
    version: 1,
    exportedAt: new Date().toISOString(),
    recipes: state.recipes.map(r => {
      const copy = { ...r };
      delete copy.__isEdit;
      return copy;
    })
  };
  const d = new Date();
  const stamp = `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}`;
  const fileName = `菜谱备份-${stamp}.json`;
  const json = JSON.stringify(data, null, 2);

  // 安卓壳：交给原生写进系统「下载」目录（WebView 不支持 blob 下载）
  const bridge = window.AndroidShell;
  if (bridge && typeof bridge.saveBackup === 'function') {
    const saved = bridge.saveBackup(fileName, json);
    if (saved) {
      toast(`已保存到 ${saved}`);
      return;
    }
    toast('保存失败，请检查存储权限');
    return;
  }

  const blob = new Blob([json], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  toast(`已导出 ${data.recipes.length} 道菜谱`);
}

async function importBackup(file) {
  let data;
  try {
    const text = await file.text();
    data = JSON.parse(text);
  } catch {
    toast('文件读取失败，不是有效的备份');
    return;
  }
  const list = Array.isArray(data) ? data : (data && data.recipes);
  if (!Array.isArray(list) || !list.length) { toast('备份里没有菜谱'); return; }

  let ord = nextOrder();
  const cleaned = list
    .filter(r => r && typeof r === 'object' && r.name)
    .map(r => ({
      id: r.id || uid(),
      type: CATEGORIES.some(c => c.id === r.type) ? r.type : 'stir',
      name: String(r.name),
      order: typeof r.order === 'number' ? r.order : ord++,
      yield: r.yield && +r.yield.count > 0 ? { count: +r.yield.count, label: String(r.yield.label || '个') } : null,
      tags: Array.isArray(r.tags) ? r.tags.map(String) : [],
      ingredients: Array.isArray(r.ingredients) ? r.ingredients.map(it => ({
        name: String(it?.name ?? ''),
        amount: String(it?.amount ?? ''),
        group: it?.group === 'aux' ? 'aux' : 'main'
      })).filter(it => it.name) : [],
      steps: Array.isArray(r.steps) ? r.steps.map(String) : [],
      bakes: Array.isArray(r.bakes) ? r.bakes.map(b => ({
        label: String(b?.label ?? ''),
        temp: String(b?.temp ?? ''),
        time: String(b?.time ?? '')
      })) : [],
      favorite: !!r.favorite,
      doneStep: Number(r.doneStep) || 0,
      createdAt: r.createdAt || Date.now(),
      updatedAt: r.updatedAt || Date.now()
    }));

  if (!cleaned.length) { toast('备份里没有可用的菜谱'); return; }

  const ok = await confirmDialog({
    title: '导入备份',
    text: `将导入 ${cleaned.length} 道菜谱，与本机现有 ${state.recipes.length} 道合并，相同的菜谱会被覆盖。`,
    ok: '导入'
  });
  if (!ok) return;

  await Store.putMany(cleaned);
  await loadAll();
  renderHome(false);
  toast(`已导入 ${cleaned.length} 道菜谱`);
}

/* ── 粘贴导入 ── */
let importData = null;
let importTimer = null;

function openImport() {
  ingSuggestReset();
  importText.value = '';
  importPreview.innerHTML = '';
  importSaveBtn.disabled = true;
  importData = null;
  document.querySelector('#view-import .scroll-body').scrollTop = 0;
  importView.classList.add('is-open');
  updateChrome();
}

function closeImport() {
  ingSuggestReset();
  importView.classList.remove('is-open');
  updateChrome();
}

function renderImportPreview() {
  const raw = importText.value;
  if (!raw.trim()) {
    importPreview.innerHTML = '';
    importData = null;
    importSaveBtn.disabled = true;
    return;
  }

  const { data, error } = parseRecipeText(raw);
  if (!data) {
    importData = null;
    importSaveBtn.disabled = true;
    importPreview.innerHTML = `<div class="imp-err">${esc(error)}</div>`;
    return;
  }

  importData = data;
  importSaveBtn.disabled = false;

  const cat = catOf(data.type);
  const main = data.ingredients.filter(i => (i.group || 'main') === 'main');
  const aux = data.ingredients.filter(i => i.group === 'aux');

  const fmtIng = list => {
    const shown = list.slice(0, 6).map(i => i.name + (i.amount ? ' ' + i.amount : ''));
    return shown.join('、') + (list.length > 6 ? ` 等 ${list.length} 项` : '');
  };

  const rows = [];
  if (data.yield) rows.push(['份量', `${data.yield.count} ${data.yield.label || '个'}`]);
  if (data.tags.length) rows.push(['标签', data.tags.join(' · ')]);
  if (main.length) rows.push(['主料', fmtIng(main)]);
  if (aux.length) rows.push(['辅料', fmtIng(aux)]);
  if (data.bakes.length) {
    const bs = data.bakes.map(b => [b.temp, b.time, b.label].filter(Boolean).join(' '));
    rows.push(['温时', bs.slice(0, 4).join(' / ') + (bs.length > 4 ? ` 等 ${bs.length} 段` : '')]);
  } else if (cat.hasBake) {
    rows.push(['温时', '未提供，保存后可补充']);
  }
  if (data.steps.length) {
    const shown = data.steps.slice(0, 3).map((s, i) => `${i + 1}. ${s}`);
    rows.push(['操作', shown.join('　') + (data.steps.length > 3 ? ` 等 ${data.steps.length} 步` : '')]);
  }

  importPreview.innerHTML = `
    <div class="imp-card">
      <div class="imp-card-head">
        <span class="badge ${cat.badge}">${esc(cat.name)}</span>
        <span class="imp-card-name">${esc(data.name)}</span>
      </div>
      ${rows.map(([k, v]) => `<div class="imp-row"><span class="imp-k">${k}</span><span class="imp-v">${esc(v)}</span></div>`).join('')}
    </div>
    <p class="imp-ok-note">确认无误后点右上角「保存」。保存后仍可继续编辑。</p>`;
}

async function saveImport() {
  if (!importData) return;
  const record = {
    id: uid(),
    type: importData.type,
    name: importData.name,
    yield: importData.yield || null,
    tags: importData.tags,
    ingredients: importData.ingredients,
    steps: importData.steps,
    bakes: importData.bakes,
    favorite: false,
    order: nextOrder(),
    createdAt: Date.now(),
    updatedAt: Date.now()
  };
  await Store.put(record);
  state.recipes.push(record);
  closeImport();
  backHistory();
  renderHome(false);
  /* 从编辑页打开导入时，回到原来的编辑器继续填 */
  if (editView.classList.contains('is-open')) {
    toast('已导入');
  } else {
    openDetail(record.id);
  }
}

/* ── 剪贴板 ── */
function fallbackCopy(text) {
  try {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.cssText = 'position:fixed;top:0;left:0;opacity:0;pointer-events:none;';
    document.body.appendChild(ta);
    ta.focus();
    ta.select();
    const ok = document.execCommand('copy');
    ta.remove();
    return ok;
  } catch { return false; }
}

function copyText(text) {
  return new Promise(resolve => {
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text)
        .then(() => resolve(true))
        .catch(() => resolve(fallbackCopy(text)));
    } else {
      resolve(fallbackCopy(text));
    }
  });
}

async function copyPrompt() {
  const ok = await copyText(AI_PROMPT);
  if (ok) { toast('提示词已复制，发截图时一起发给 AI'); return; }
  if (!importText.value.trim()) {
    importText.value = AI_PROMPT;
    renderImportPreview();
  }
  toast('自动复制失败，提示词已填入文本框，可手动复制');
}

/* ── 事件绑定 ── */
function bindEvents() {
  /* 首页分类小按钮 */
  chipBar.addEventListener('click', e => {
    const btn = e.target.closest('[data-filter]');
    if (!btn) return;
    state.filter = btn.dataset.filter;
    renderHome(false);
  });

  /* 底部标签：菜谱 / 计时器 */
  tabBar.addEventListener('click', e => {
    const btn = e.target.closest('[data-tab]');
    if (!btn) return;
    switchTab(btn.dataset.tab);
  });

  /* 底部菜单的新建按钮 */
  $('btn-add').addEventListener('click', () => {
    if (state.manage) return;
    openEditor(null);
  });

  /* 卡片：长按进入编辑模式，编辑模式下拖动排序 */
  recipeList.addEventListener('pointerdown', cardPressDown);
  document.addEventListener('pointermove', e => {
    cardPressMove(e);
    cardDragMove(e);
  }, { passive: false });
  document.addEventListener('pointerup', e => { cardPressCancel(); cardDragEnd(); });
  document.addEventListener('pointercancel', e => { cardPressCancel(); cardDragEnd(); });

  /* 搜索 */
  let searchTimer;
  searchInput.addEventListener('input', () => {
    state.query = searchInput.value;
    searchClear.hidden = !searchInput.value;
    clearTimeout(searchTimer);
    searchTimer = setTimeout(() => renderHome(false), 90);
  });
  searchClear.addEventListener('click', () => {
    searchInput.value = '';
    state.query = '';
    searchClear.hidden = true;
    renderHome(false);
    searchInput.focus();
  });

  /* 首页滚动时头部加渐隐 */
  homeBody.addEventListener('scroll', () => {
    homeHead.classList.toggle('is-scrolled', homeBody.scrollTop > 4);
  }, { passive: true });

  /* 列表点击 */
  recipeList.addEventListener('click', e => {
    if (suppressCardClick) { suppressCardClick = false; e.stopPropagation(); e.preventDefault(); return; }
    const del = e.target.closest('[data-del-card]');
    if (del) { deleteCard(del.dataset.delCard); return; }
    if (state.manage) return;   // 管理模式下点卡片不进入详情
    const fav = e.target.closest('[data-fav]');
    if (fav) { toggleFavorite(fav.dataset.fav); return; }
    const open = e.target.closest('[data-open]');
    if (open) openDetail(open.dataset.open);
  });

  /* 退出管理模式 */
  $('btn-manage').addEventListener('click', () => {
    if (!state.manage) return;
    setManage(false);
    backHistory();
  });

  renderKnobDot();
  renderPresets();
  renderTimer();

  /* 计时器：旋钮 */
  knob.addEventListener('pointerdown', knobDown);
  knob.addEventListener('pointermove', knobMove);
  knob.addEventListener('pointerup', knobUp);
  knob.addEventListener('pointercancel', knobUp);

  /* 计时器：加减 / 开始暂停 */
  $('timer-minus').addEventListener('click', () => adjustTime(-timerStepMin * 60));
  $('timer-plus').addEventListener('click', () => adjustTime(timerStepMin * 60));
  timerStartBtn.addEventListener('click', () => {
    if (timer.running) { pauseTimer(); toast('已暂停'); }
    else startTimer();
  });
  timerAltBtn.addEventListener('click', () => {
    if (timer.ringing) { finishRing(); return; }
    const wasRunning = timer.running;
    resetTimer();
    toast(wasRunning ? '已取消' : '已重置');
  });

  /* 计时器：预设（点击套用，长按删除） */
  let presetPress = null;
  presetsEl.addEventListener('click', e => {
    const b = e.target.closest('[data-preset]');
    if (!b) return;
    const sec = timerPresets[Number(b.dataset.preset)];
    if (!sec) return;
    applyTime(sec);
    toast('已设为 ' + fmtShort(sec));
  });
  presetsEl.addEventListener('pointerdown', e => {
    const b = e.target.closest('[data-preset]');
    if (!b) return;
    const i = Number(b.dataset.preset);
    clearTimeout(presetPress);
    presetPress = setTimeout(async () => {
      presetPress = null;
      const ok = await confirmDialog({
        title: '删除这个预设？',
        text: `「${fmtShort(timerPresets[i])}」将从预设里移除。`,
        ok: '删除',
        danger: true
      });
      if (!ok) return;
      timerPresets.splice(i, 1);
      savePresets();
      renderPresets();
      if (!drawer.hidden && drawerMode === 'timer') renderDrawer();
      toast('已删除预设');
    }, 560);
  });
  ['pointerup', 'pointercancel', 'pointerleave'].forEach(ev =>
    presetsEl.addEventListener(ev, () => { clearTimeout(presetPress); presetPress = null; })
  );

  /* 左右滑动切换首页 / 计时器：整块空白处都能滑，不再只认边缘 */
  bindTabSwipe();
  bindTimerPull();

  /* 详情 */
  $('detail-back').addEventListener('click', () => { closeDetail(); backHistory(); });
  $('detail-edit').addEventListener('click', () => {
    if (state.detailId) openEditor(state.detailId);
  });
  detailBody.addEventListener('click', e => {
    /* 步骤序号：点一下记「做到这一步」，再点一次就退回上一步 */
    const sn = e.target.closest('.step-num');
    if (sn) { toggleStepDone(Number(sn.dataset.stepNo)); return; }
    /* 菜谱里提到的时间：点一下直接跳计时器并填好时长 */
    const tchip = e.target.closest('[data-timer-sec]');
    if (tchip) { openTimerForStep(Number(tchip.dataset.timerSec), Number(tchip.dataset.stepNo) || 0); return; }
    const fav = e.target.closest('[data-fav]');
    if (fav) { toggleFavorite(fav.dataset.fav); return; }
    const pin = e.target.closest('[data-pin]');
    if (pin) { togglePin(pin.dataset.pin); return; }
    if (e.target.closest('[data-act="open-mihome"]')) { openMihome(); return; }
    if (e.target.closest('[data-edit-note]')) {
      if (state.detailId) openEditor(state.detailId);
      return;
    }
    const sc = e.target.closest('[data-scale]');
    if (sc) {
      const r = state.recipes.find(x => x.id === state.detailId);
      const base = r && r.yield ? +r.yield.count : 0;
      if (!base) return;
      const v = Number(sc.dataset.scale);
      state.scale = v === 0 ? base : Math.max(1, (state.scale || base) + v);
      renderDetail();
      return;
    }
    const conv = e.target.closest('[data-conv-ing]');
    if (conv) { openConvert(conv.dataset.convIng, conv.dataset.convAmt); return; }
    if (e.target.closest('[data-act="finish-recipe"]')) { confirmFinishRecipe(); return; }
    if (e.target.closest('[data-act="reset-steps"]')) { confirmResetSteps(); return; }
    if (e.target.closest('[data-del-recipe]')) deleteRecipe(state.detailId);
  });

  /* ══════ 美食日记 ══════ */
  $('btn-diary').addEventListener('click', openDiary);

  $('diary-close').addEventListener('click', () => {
    /* 不管停在哪一层，× 都是整页收起；压了几层就退几条历史 */
    const layers = state.diaryRecipeId ? 2 : 1;
    state.diaryRecipeId = null;
    diaryView.classList.remove('is-open');
    updateChrome();
    for (let i = 0; i < layers; i++) backHistory();
  });

  diaryBack.addEventListener('click', () => { closeDiary(); backHistory(); });

  diaryChipBar.addEventListener('click', e => {
    const b = e.target.closest('[data-diary-filter]');
    if (!b) return;
    state.diaryFilter = b.dataset.diaryFilter;
    renderDiary();
  });

  diarySearch.addEventListener('input', () => {
    state.diaryQuery = diarySearch.value;
    state.diaryRecipeId = null;        // 一搜索就回到总览
    renderDiary();
    diarySearchClear.hidden = !diarySearch.value;
  });

  diarySearchClear.addEventListener('click', () => {
    diarySearch.value = '';
    state.diaryQuery = '';
    diarySearchClear.hidden = true;
    renderDiary();
  });

  diaryGrid.addEventListener('click', e => {
    const card = e.target.closest('[data-diary-recipe]');
    if (!card) return;
    state.diaryRecipeId = card.dataset.diaryRecipe;
    renderDiary();
    pushLayer();
  });

  /* ══════ 记一篇日记 ══════ */
  $('dn-cancel').addEventListener('click', () => { closeDiaryNew(); backHistory(); });
  $('dn-save').addEventListener('click', saveDiaryDraft);
  /* add-photo 必须走委托：renderDraftPhotos 用 innerHTML 整体替换会销毁原按钮的监听 */
  $('dn-file').addEventListener('change', async e => {
    const f = e.target.files && e.target.files[0];
    if (!f || !state.diaryDraft) { e.target.value = ''; return; }
    const data = await compressImage(f);
    if (data) { state.diaryDraft.photo = data; renderDraftPhotos(); }
    else toast('这张图读不出来，换一张试试');
    e.target.value = '';              // 允许再次选同一张
  });
  $('dn-photos').addEventListener('click', e => {
    if (!state.diaryDraft) return;
    if (e.target.closest('#dn-add-photo')) { $('dn-file').click(); return; }
    if (e.target.closest('#dn-del-photo')) {
      state.diaryDraft.photo = '';
      renderDraftPhotos();
    }
  });
  $('dn-rating').addEventListener('click', e => {
    const b = e.target.closest('[data-rate]');
    if (!b || !state.diaryDraft) return;
    /* 再点一次同一个就取消选择 */
    state.diaryDraft.rate = state.diaryDraft.rate === b.dataset.rate ? '' : b.dataset.rate;
    renderDraftRates();
  });

  /* 编辑页顶栏：粘贴导入（关闭首页入口后移到这里） */
  $('edit-import').addEventListener('click', () => { openImport(); pushLayer(); });
  $('import-cancel').addEventListener('click', () => { closeImport(); backHistory(); });
  $('import-save').addEventListener('click', saveImport);
  $('copy-prompt').addEventListener('click', copyPrompt);
  importText.addEventListener('input', () => {
    clearTimeout(importTimer);
    importTimer = setTimeout(renderImportPreview, 240);
  });

  /* 编辑器：类型切换 */
  typeSeg.addEventListener('click', e => {
    const btn = e.target.closest('[data-type]');
    if (!btn) return;
    syncFromDOM();
    state.draft.type = btn.dataset.type;
    const hasBake = catOf(btn.dataset.type).hasBake;
    if (hasBake && !state.draft.bakes.length) {
      state.draft.bakes = [{ label: '', temp: '', time: '' }];
    }
    // 切到家常菜时保证辅料组存在；切到烘焙时辅料只是隐藏，数据保留
    if (!hasBake && !(state.draft.ingredients || []).some(x => x.group === 'aux')) {
      state.draft.ingredients.push({ name: '', amount: '', group: 'aux' });
    }
    renderTypeSeg();
    renderIngs();
    renderBakes();
    renderSteps();
  });

  /* 编辑器：标签 */
  function commitTag(raw) {
    const t = String(raw || '').trim().replace(/^#+/, '').replace(/\s+/g, ' ');
    if (!t) return;
    if (t.length > 14) { toast('标签最多 14 个字'); return; }
    const exists = (state.draft.tags || []).some(x => x.toLowerCase() === t.toLowerCase());
    if (exists) { tagInput.value = ''; return; }
    state.draft.tags.push(t);
    tagInput.value = '';
    renderTags();
  }

  tagInput.addEventListener('keydown', e => {
    if (e.key === 'Enter' || e.key === ',' || e.key === '，') {
      e.preventDefault();
      commitTag(tagInput.value);
    } else if (e.key === 'Backspace' && !tagInput.value) {
      if (state.draft.tags.length) {
        state.draft.tags.pop();
        renderTags();
      }
    }
  });
  tagInput.addEventListener('blur', () => {
    if (tagInput.value.trim()) commitTag(tagInput.value);
  });
  tagList.addEventListener('click', e => {
    const btn = e.target.closest('[data-rmtag]');
    if (!btn) return;
    state.draft.tags.splice(Number(btn.dataset.rmtag), 1);
    renderTags();
  });
  tagSuggest.addEventListener('click', e => {
    const btn = e.target.closest('[data-sug]');
    if (!btn) return;
    commitTag(btn.dataset.sug);
  });
  tagEditor.addEventListener('click', e => {
    if (e.target === tagEditor || e.target === tagList) tagInput.focus();
  });

  /* 编辑器：材料（主料 / 辅料） */
  function addIngRow(group) {
    syncFromDOM();
    state.draft.ingredients.push({ name: '', amount: '', group });
    renderIngs();
    const list = group === 'aux' ? ingAuxList : ingMainList;
    const inputs = list.querySelectorAll('[data-ing="name"]');
    if (inputs.length) inputs[inputs.length - 1].focus();
  }
  $('add-ing-main').addEventListener('click', () => addIngRow('main'));
  $('add-ing-aux').addEventListener('click', () => addIngRow('aux'));

  [ingMainList, ingAuxList].forEach(list => {
    list.addEventListener('pointerdown', ingDragDown);
    list.addEventListener('click', e => {
      const btn = e.target.closest('[data-del-ing]');
      if (!btn || !state.draft) return;
      syncFromDOM();
      const group = btn.dataset.delGroup;
      const idx = Number(btn.dataset.delIng);
      // 组内索引 → 全局数组位置
      let nth = -1, target = -1;
      state.draft.ingredients.forEach((x, i) => {
        if ((x.group || 'main') === group) { nth++; if (nth === idx) target = i; }
      });
      if (target >= 0) state.draft.ingredients.splice(target, 1);
      renderIngs();
    });
    list.addEventListener('input', e => {
      if (e.target.matches('[data-ing]')) ingEmpty.hidden = true;
    });
  });

  /* 材料拖拽：移动 / 结束（监听在 document 上，手指移出列表也不丢） */
  document.addEventListener('pointermove', ingDragMove, { passive: false });
  document.addEventListener('pointerup', ingDragEnd);
  document.addEventListener('pointercancel', ingDragEnd);
  window.addEventListener('blur', ingDragEnd);
  document.addEventListener('click', e => {
    if (!suppressIngClick) return;
    suppressIngClick = false;
    e.stopPropagation();
    e.preventDefault();
  }, true);

  /* 材料联想浮层 */
  document.addEventListener('focusin', e => {
    if (e.target.matches && e.target.matches('[data-ing="name"]')) showIngSuggest(e.target);
    else hideIngSuggest();
  });
  document.addEventListener('input', e => {
    if (e.target.matches && e.target.matches('[data-ing="name"]')) showIngSuggest(e.target);
  });
  document.addEventListener('focusout', e => {
    if (e.target && e.target.matches && e.target.matches('[data-ing="name"]')) {
      // 延迟收起以便点击候选词；若焦点只是换到另一个材料输入框，由 focusin 重新定位
      clearTimeout(ingSuggestHideTimer);
      ingSuggestHideTimer = setTimeout(() => {
        const ae = document.activeElement;
        if (!(ae && ae.matches && ae.matches('[data-ing="name"]'))) hideIngSuggest();
      }, 180);
    }
  });
  // pointerdown 拦掉默认行为，点候选词时输入框不失焦
  ingSuggest.addEventListener('pointerdown', e => e.preventDefault());
  ingSuggest.addEventListener('click', e => {
    const btn = e.target.closest('[data-sug-ing]');
    if (!btn || !ingSuggestTarget) return;
    ingSuggestTarget.value = btn.dataset.sugIng;
    hideIngSuggest();
  });
  document.addEventListener('scroll', () => hideIngSuggest(), { capture: true, passive: true });
  // 输入法弹出 / 收起会改变可视区域，fixed 定位会错位，直接收起
  if (window.visualViewport) {
    window.visualViewport.addEventListener('resize', hideIngSuggest);
  }

  /* 编辑器：温度时间 */
  $('add-bake').addEventListener('click', () => {
    syncFromDOM();
    state.draft.bakes.push({ label: '', temp: '', time: '' });
    renderBakes();
    const inputs = bakeList.querySelectorAll('[data-bake="temp"]');
    if (inputs.length) inputs[inputs.length - 1].focus();
  });
  bakeList.addEventListener('click', e => {
    const btn = e.target.closest('[data-del-bake]');
    if (!btn) return;
    syncFromDOM();
    state.draft.bakes.splice(Number(btn.dataset.delBake), 1);
    renderBakes();
  });

  /* 编辑器：步骤 */
  $('add-step').addEventListener('click', () => {
    syncFromDOM();
    state.draft.steps.push('');
    renderSteps();
    const tas = stepList.querySelectorAll('textarea');
    if (tas.length) tas[tas.length - 1].focus();
  });
  stepList.addEventListener('click', e => {
    const btn = e.target.closest('[data-del-step]');
    if (!btn) return;
    syncFromDOM();
    state.draft.steps.splice(Number(btn.dataset.delStep), 1);
    renderSteps();
  });
  stepList.addEventListener('input', e => {
    const ta = e.target.closest('textarea');
    if (!ta) return;
    ta.style.height = 'auto';
    ta.style.height = ta.scrollHeight + 'px';
  });

  /* 编辑器：保存 / 取消 / 删除 */
  $('edit-save').addEventListener('click', saveDraft);

  const leaveEditor = () => { closeEditor(); backHistory(); };

  $('edit-cancel').addEventListener('click', () => {
    const hasInput = fName.value.trim() || fYieldNum.value.trim() ||
      (state.draft && (state.draft.tags || []).length) ||
      [...ingMainList.querySelectorAll('input'), ...ingAuxList.querySelectorAll('input')].some(i => i.value.trim()) ||
      [...bakeList.querySelectorAll('input')].some(i => i.value.trim()) ||
      [...stepList.querySelectorAll('textarea')].some(t => t.value.trim());
    if (hasInput) {
      const isNew = state.draft && !state.draft.__isEdit;
      confirmDialog({
        title: isNew ? '取消新建菜谱？' : '放弃这次编辑？',
        text: '已填写的内容不会保存。',
        ok: isNew ? '取消新建' : '放弃',
        danger: true
      }).then(ok => { if (ok) leaveEditor(); });
    } else {
      leaveEditor();
    }
  });
  editDelete.addEventListener('click', () => {
    if (state.draft) deleteRecipe(state.draft.id);
  });

  /* 侧边栏：首页=备份设置，计时器=步长与预设 */
  /* 汉堡菜单是全局的：在计时器页打开就显示计时器设置，其余情况显示备份设置 */
  chromeMenu.addEventListener('click', () => {
    openDrawer(timerView.classList.contains('is-open') ? 'timer' : 'home');
  });
  drawer.addEventListener('click', e => {
    if (e.target.closest('[data-close-drawer]')) closeDrawer();
  });

  /* 抽屉关闭手势：
     1) 点右侧遮罩直接关（click + 点按兜底双保险）；
     2) 遮罩或面板内的空白处从右往左滑，面板跟手收起。
     面板里的开关 / 按钮 / 输入框不参与滑动，避免误触。 */
  const drawerMask = drawer.querySelector('.drawer-mask');
  const drawerPanel = $('drawer-panel');
  const DRAWER_SKIP = 'button, input, select, textarea, a, label, .drawer-chip, .is-switch, [data-toggle], [data-step], [data-act], [data-del-preset]';
  let drawerSwipe = null;

  const drawerSwipeStart = e => {
    if (e.button !== undefined && e.button > 0) return;
    const onMask = e.currentTarget === drawerMask;
    if (!onMask && e.target.closest(DRAWER_SKIP)) return;
    drawerSwipe = { pid: e.pointerId, x0: e.clientX, y0: e.clientY, dx: 0, tap: onMask };
  };

  const drawerSwipeMove = e => {
    const s = drawerSwipe;
    if (!s || e.pointerId !== s.pid) return;
    const dx = e.clientX - s.x0;
    const dy = e.clientY - s.y0;
    if (Math.abs(dy) > Math.abs(dx)) { drawerSwipe = null; return; }
    if (dx >= 0) return;                       // 只认从右往左
    s.tap = false;
    s.dx = dx;
    e.preventDefault();
    drawerPanel.classList.add('is-swiping');
    drawerPanel.style.transition = 'none';
    drawerPanel.style.transform = `translateX(${Math.max(dx, -drawerPanel.offsetWidth)}px)`;
  };

  const endDrawerSwipe = e => {
    const s = drawerSwipe;
    if (!s || (e && e.pointerId !== s.pid)) return;
    drawerSwipe = null;
    /* 遮罩上几乎没动 = 点按：直接关（click 可能被系统手势吞掉，这里兜底） */
    if (s.tap && Math.abs(e.clientX - s.x0) < 10 && Math.abs(e.clientY - s.y0) < 10) {
      closeDrawer();
      return;
    }
    if (s.dx < -36 || s.dx < -drawerPanel.offsetWidth * 0.35) {
      closeDrawer();          // 关掉时会顺手把面板样式复位
      return;
    }
    /* 没滑到位：弹回去（保留 is-swiping，免得入场动画重播） */
    drawerPanel.style.transition = 'transform .22s var(--ease)';
    drawerPanel.style.transform = '';
  };

  [drawerMask, drawerPanel].forEach(el => {
    el.addEventListener('pointerdown', drawerSwipeStart);
    el.addEventListener('pointermove', drawerSwipeMove, { passive: false });
    el.addEventListener('pointerup', endDrawerSwipe);
    el.addEventListener('pointercancel', endDrawerSwipe);
  });

  drawerInner.addEventListener('click', async e => {
    const tog = e.target.closest('[data-toggle]');
    if (tog) {
      if (tog.dataset.toggle === 'vibrate') {
        ringVibrate = !ringVibrate;
        lsSet(LS_VIBRATE, ringVibrate ? '1' : '0');
        toast(ringVibrate ? '到点会震动' : '到点不震动');
      } else {
        ringSound = !ringSound;
        lsSet(LS_SOUND, ringSound ? '1' : '0');
        if (ringSound) beep();               // 打开时响一下，确认能听见
        toast(ringSound ? '到点会响铃' : '到点不响铃');
      }
      renderDrawer();
      return;
    }

    const chip = e.target.closest('[data-step]');
    if (chip) {
      timerStepMin = Number(chip.dataset.step);
      lsSet(LS_STEP, String(timerStepMin));
      renderDrawer();
      renderTimer();
      toast(`加减一次 ${timerStepMin} 分钟`);
      return;
    }

    const rm = e.target.closest('[data-rm-preset]');
    if (rm) {
      timerPresets.splice(Number(rm.dataset.rmPreset), 1);
      savePresets();
      renderDrawer();
      renderPresets();
      return;
    }

    const act = e.target.closest('[data-act]');
    const otaDl = e.target.closest('[data-ota-dl]');
    if (otaDl && !otaDl.disabled) {
      const v = otaVersions[Number(otaDl.dataset.otaDl)];
      if (v) downloadVersion(v);
      return;
    }
    const applyScheme = e.target.closest('[data-apply-scheme]');
    if (applyScheme) {
      const s = colorSchemes[Number(applyScheme.dataset.applyScheme)];
      if (!s) return;
      applyTheme(s.colors);
      saveTheme();
      renderDrawer();
      toast(`已应用「${s.name}」`);
      return;
    }
    const delScheme = e.target.closest('[data-del-scheme]');
    if (delScheme) {
      const i = Number(delScheme.dataset.delScheme);
      const s = colorSchemes[i];
      if (!s) return;
      colorSchemes.splice(i, 1);
      saveSchemes();
      renderDrawer();
      toast(`已删除「${s.name}」`);
      return;
    }
    if (!act) return;
    switch (act.dataset.act) {
      case 'save-ota-url': {
        const inp = $('ota-url');
        const u = (inp && inp.value || '').trim();
        if (!u) { toast('地址不能为空'); return; }
        if (!/^https:\/\//.test(u)) { toast('要填 https:// 开头的地址'); return; }
        otaUrl = u;
        OtaStore.write(K_OTA_URL, u);
        toast('更新地址已保存');
        return;
      }
      case 'check-update':
        checkUpdate();
        return;
      case 'reset-ota': {
        const ok = await confirmDialog({
          title: '恢复出厂版本？',
          text: '删掉已下载的在线更新，重启后用回 APK 内置版本。你的菜谱不受影响。',
          ok: '恢复',
          danger: true
        });
        if (!ok) return;
        await OtaStore.remove(K_OTA);
        otaState = { version: 0, note: '', html: '', pending: false, appliedOnce: false, ok: false };
        location.reload();
        return;
      }
      case 'open-color':
        openColorSheet();
        return;
      case 'reset-theme':
        applyTheme(THEME_DEFAULT);
        saveTheme();
        renderDrawer();
        toast('已恢复默认配色');
        return;
      case 'save-scheme': {
        const inp = $('scheme-name');
        const name = (inp && inp.value || '').trim();
        if (!name) { toast('先给配色方案起个名字'); return; }
        if (colorSchemes.length >= MAX_SCHEMES) { toast(`最多保存 ${MAX_SCHEMES} 个方案`); return; }
        if (colorSchemes.some(s => s.name === name)) { toast('已经有同名方案了'); return; }
        colorSchemes.push({ name, colors: { ...themeColors } });
        saveSchemes();
        renderDrawer();
        toast(`已保存「${name}」`);
        return;
      }
      case 'add-preset': {
        const inp = $('preset-input');
        const v = Math.round(Number(inp && inp.value));
        if (!v || v <= 0 || v > 1440) { toast('请填写 1 - 1440 之间的分钟数'); return; }
        if (timerPresets.length >= 3) { toast('最多 3 个预设'); return; }
        const sec = v * 60;
        if (timerPresets.includes(sec)) { toast('这个预设已经有了'); return; }
        timerPresets.push(sec);
        savePresets();
        renderDrawer();
        renderPresets();
        toast(`已添加 ${fmtShort(sec)}`);
        return;
      }
      case 'export':
        closeDrawer();
        exportBackup();
        return;
      case 'import':
        closeDrawer();
        $('import-file').click();
        return;
      case 'import-text':
        // 复用侧边栏占用的那条历史记录
        drawer.hidden = true;
        openImport();
        return;
      case 'clear':
        await clearAllRecipes();
        return;
    }
  });

  /* 配色：取色器实时生效并持久化 */
  drawerInner.addEventListener('input', e => {
    const inp = e.target.closest('[data-color-key]');
    if (!inp) return;
    const key = inp.dataset.colorKey;
    themeColors[key] = normalizeHex(inp.value, themeColors[key]);
    applyTheme(themeColors);
    saveTheme();
    const wrap = inp.closest('.swatch');
    if (wrap) {
      const hex = wrap.querySelector('.swatch-hex');
      const dot = wrap.querySelector('.swatch-color');
      if (hex) hex.textContent = themeColors[key];
      if (dot) dot.style.background = themeColors[key];
    }
  });

  $('import-file').addEventListener('change', async e => {
    const f = e.target.files && e.target.files[0];
    e.target.value = '';
    if (f) await importBackup(f);
  });

  /* 单位换算面板 */
  const convSheet = $('sheet-convert');
  convSheet.addEventListener('click', e => {
    if (e.target.closest('[data-close-sheet]')) convSheet.hidden = true;
  });

  /* 配色面板 */
  $('sheet-color').addEventListener('click', e => {
    if (e.target.closest('[data-close-color]')) closeColorSheet();
  });

}

/* ══════════ 返回栈 ══════════
   打开子页面时压入一条历史记录，这样侧滑返回、系统返回键
   都能逐层后退，而不是直接退出应用。 */
let suppressPop = 0;

function pushLayer() {
  try { history.pushState({ layer: 1 }, ''); } catch (e) { /* 忽略 */ }
}

function backHistory() {
  if (history.state && history.state.layer) {
    suppressPop++;
    history.back();
  }
}

/* 由系统返回键触发：只关 UI，不再操作历史（浏览器已后退） */
function popTopLayer() {
  if (!$('dialog').hidden) { finishDialog(false, false); return; }
  if (!drawer.hidden) { drawer.hidden = true; return; }
  if (state.manage) { setManage(false); return; }
  if (!$('sheet-color').hidden) { closeColorSheet(); return; }
  if (!$('sheet-convert').hidden) { $('sheet-convert').hidden = true; return; }
  if (diaryNewView.classList.contains('is-open')) { closeDiaryNew(); return; }
  if (diaryView.classList.contains('is-open')) { closeDiary(); return; }
  if ($('view-import').classList.contains('is-open')) { closeImport(); return; }
  if (editView.classList.contains('is-open')) { closeEditor(); return; }
  if (timerView.classList.contains('is-open')) { closeTimer(); return; }
  if (detailView.classList.contains('is-open')) { closeDetail(); return; }
}

window.addEventListener('popstate', () => {
  if (suppressPop > 0) { suppressPop--; return; }
  popTopLayer();
});

/* ── 启动 ── */
async function boot() {
  await OtaStore.init();
  await otaLoad();

  /* 有待生效的在线更新：
     appliedOnce 为真却没被标记 ok，说明上次写进去没能启动起来 → 丢弃，回到出厂版 */
  if (otaState.pending) {
    if (otaState.appliedOnce && !otaState.ok) {
      await OtaStore.remove(K_OTA);
      otaState = { version: 0, note: '', html: '', pending: false, appliedOnce: false, ok: false };
    } else if (Number(otaState.version) < APP_VERSION) {
      /* 装了更新的 APK：本地存的在线更新包比内置还旧，留着会把新页面盖回去 */
      await OtaStore.remove(K_OTA);
      otaState = { version: 0, note: '', html: '', pending: false, appliedOnce: false, ok: false };
    } else {
      otaState.appliedOnce = true;
      await otaSave();
      applyUpdateHtml(otaState.html);
      return;                       // 让新页面自己去跑剩下的流程
    }
  }

  loadTheme();            // 配色要在首次渲染前生效，避免闪一下默认色
  await Store.init();
  await loadAll();
  normalizeOrder();
  await DiaryStore.init();
  await loadDiaries();
  loadPinned();
  bindEvents();
  renderHome();
  updateChrome();
  await restoreTimer();

  /* 退到后台 / 回到前台：按真实时间补算，页面被系统冻住也不会走慢 */
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') timerCatchUp();
    else { timerCatchUp(); saveTimer(); }
  });
  window.addEventListener('pageshow', timerCatchUp);

  /* 更新包自己跑起来了 → 标记为可用；下次启动就不会误判成启动失败 */
  if (otaState.pending) {
    otaState.ok = true;
    await otaSave();
  }

  // Service Worker（离线可用）。安卓壳内部资源走本地拦截，无需缓存，反而会让
  // 升级后的 APK 读到旧版本，所以壳里跳过注册。
  const inShell = !!(window.AndroidShell && window.AndroidShell.isNativeShell);
  if ('serviceWorker' in navigator && location.protocol.startsWith('http') && !inShell) {
    try {
      await navigator.serviceWorker.register('sw.js');
    } catch (err) {
      console.warn('SW 注册失败', err);
    }
  }
}

boot();
